INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26250, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "重金属是一种很重的金属，比如铅和汞，它们对身体不好。", "primary_collocate": null, "pronunciation": "zhòng jīn shǔ", "ipa": "ʈʂʊŋ˥˩ tɕin˥ ʂu˨˩˦", "syllable_count": 3, "sentences": [{"text": "铅是一种重金属。", "target_word": "重金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水里有重金属，我们不能喝。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧电池里有重金属。", "target_word": "重金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汞是重金属，很危险。", "target_word": "重金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "重金属进了身体，人会生病。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个厂的水有重金属。", "target_word": "重金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说重金属对孩子不好。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要少接触重金属。", "target_word": "重金属", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鱼吃了带重金属的水，也会生病。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在实验室里研究重金属。", "target_word": "重金属", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "重金属：铅、汞这类很重、对身体不好的金属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4173360d-5258-4945-b596-63a93b4b335e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重金属", "is_correct": true, "explanation": "正确。“铅是一种重金属”，铅属于铅、汞这类很重、对身体不好的金属。"}, {"text": "水果", "is_correct": false, "explanation": "语义：铅是金属元素，不是水果，“铅是一种水果”不成立。"}, {"text": "植物", "is_correct": false, "explanation": "语义：铅是金属，不是植物，句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“一种”后面的名词要能表示事物类别，“时间”与“铅是一种”搭配不当。"}], "explanations": {"重金属": "正确。“铅是一种重金属”，铅属于铅、汞这类很重、对身体不好的金属。", "水果": "语义：铅是金属元素，不是水果，“铅是一种水果”不成立。", "植物": "语义：铅是金属，不是植物，句意不通。", "时间": "搭配：“一种”后面的名词要能表示事物类别，“时间”与“铅是一种”搭配不当。"}, "sentence_index": 0, "correct_answer": "重金属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钻石是一种重金属，很值钱。", "explanation": "这里应该用〈宝石〉。钻石是碳的单质，不是金属；重金属指铅、汞这类对身体有害的金属。"}, {"text": "蛇毒是一种重金属，很危险。", "explanation": "这里应该用〈毒素〉。蛇毒是蛋白质类毒素，不是金属；重金属专指铅、汞这类金属。"}, {"text": "这袋大米很重，所以它是重金属。", "explanation": "大米不是金属，“很重”只说明分量，不能因此说它是重金属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重金属", "is_correct": true, "explanation": "正确。“老师说重金属对孩子不好”，重金属是对身体有害的金属，与句意相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会对孩子造成伤害，“月亮对孩子不好”句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是会危害孩子的事物，与“对孩子不好”不搭。"}, {"text": "白天", "is_correct": false, "explanation": "搭配：“白天”是时间，不能作“对孩子不好”的主语，搭配不当。"}], "explanations": {"重金属": "正确。“老师说重金属对孩子不好”，重金属是对身体有害的金属，与句意相符。", "月亮": "语义：月亮不会对孩子造成伤害，“月亮对孩子不好”句意不通。", "天空": "语义：天空不是会危害孩子的事物，与“对孩子不好”不搭。", "白天": "搭配：“白天”是时间，不能作“对孩子不好”的主语，搭配不当。"}, "sentence_index": 6, "correct_answer": "重金属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铝是一种重金属，很轻，可以用来做飞机。", "explanation": "这里应该用〈轻金属〉。铝密度小，属于轻金属；重金属指密度大、常有毒性的金属，铝不属于此类。"}, {"text": "医生给病人开了重金属，让他每天服用。", "explanation": "这里应该用〈维生素〉。重金属有毒，不能当作药物开给病人服用；给病人开药应说维生素。"}, {"text": "我们在花园里种了很多重金属。", "explanation": "这里应该用〈花草〉。重金属是金属元素，不能栽种；“种”只用于花草等植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "镉也是一个重金属，要小心。", "corrected_sentence": "镉也是一种重金属，要小心。", "error_description": "量词错误：「一个重金属」应为「一种重金属」。重金属是一类金属，计量类别用“种”，“个”不能用于这类名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只重金属很危险，要小心。", "corrected_sentence": "这种重金属很危险，要小心。", "error_description": "量词错误：「重金属」是一类物质，不能用「只」计量，应用「种」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26252, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无毒", "is_correct": true, "explanation": "与“有毒”相对，指不含对生命有害的物质，是这一义项的反义词。"}, {"text": "精致", "is_correct": false, "explanation": "“精致”与“粗糙”相对，与“有毒”无反义关系。"}, {"text": "清澈", "is_correct": false, "explanation": "“清澈”与“浑浊”相对，与“有毒”无反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "“灵活”与“呆板”相对，与“有毒”无反义关系。"}], "correct_answer": "无毒", "explanations": {"无毒": "与“有毒”相对，指不含对生命有害的物质，是这一义项的反义词。", "精致": "“精致”与“粗糙”相对，与“有毒”无反义关系。", "清澈": "“清澈”与“浑浊”相对，与“有毒”无反义关系。", "灵活": "“灵活”与“呆板”相对，与“有毒”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26252, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无毒", "is_correct": true, "explanation": "与“有毒”相对，指不含对生命有害的物质，是这一义项的反义词。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”与“光滑”相对，与“有毒”无反义关系。"}, {"text": "浑浊", "is_correct": false, "explanation": "“浑浊”与“清澈”相对，与“有毒”无反义关系。"}, {"text": "呆板", "is_correct": false, "explanation": "“呆板”与“灵活”相对，与“有毒”无反义关系。"}], "correct_answer": "无毒", "explanations": {"无毒": "与“有毒”相对，指不含对生命有害的物质，是这一义项的反义词。", "粗糙": "“粗糙”与“光滑”相对，与“有毒”无反义关系。", "浑浊": "“浑浊”与“清澈”相对，与“有毒”无反义关系。", "呆板": "“呆板”与“灵活”相对，与“有毒”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26252, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有毒的东西会让人生病或死掉。", "primary_collocate": null, "pronunciation": "yǒu dú", "ipa": "joʊ̯²¹⁴ tu³⁵", "syllable_count": 2, "sentences": [{"text": "这种果子有毒，吃了会生病。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条红色的蛇有毒。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉我们，有毒的草不能碰。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶药有毒，别让小狗喝。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有毒的蘑菇长得很漂亮，但千万别吃。", "target_word": "有毒", "complexity_tier": "T3", "furigana": "yǒu dú de mó gu zhǎng de hěn piào liang, dàn qiān wàn bié chī", "sentence_source": "generated"}, {"text": "他吃了有毒的鱼，住进了医院。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说有毒的东西不要放进嘴里。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花很美，可是有毒。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有毒的虫子很多。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的气体有毒，我们快出去。", "target_word": "有毒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有毒物质", "label": "复合"}, {"form": "有毒气体", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西含毒，会让人生病或死亡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edafe57e-8182-4ddf-9c5d-57d2a9d9dbda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有毒", "is_correct": true, "explanation": "“有毒”说明果子含毒，吃了会生病，与句意一致。"}, {"text": "无毒", "is_correct": false, "explanation": "语义：果子无毒，吃了不会生病，与后半句矛盾。"}, {"text": "有效", "is_correct": false, "explanation": "搭配：“有效”多用于药物、方法，不说果子有效。"}, {"text": "健康", "is_correct": false, "explanation": "语义：健康的果子吃了会生病，句意说不通。"}], "explanations": {"有毒": "“有毒”说明果子含毒，吃了会生病，与句意一致。", "无毒": "语义：果子无毒，吃了不会生病，与后半句矛盾。", "有效": "搭配：“有效”多用于药物、方法，不说果子有效。", "健康": "语义：健康的果子吃了会生病，句意说不通。"}, "sentence_index": 0, "correct_answer": "有毒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的书包很有毒，每天都压得我肩膀疼。", "explanation": "这里应该用〈沉〉。有毒指物质含毒素，书包的重量要说沉。"}, {"text": "他误吃了药，有毒住院了。", "explanation": "这里应该用〈中毒〉。有毒形容物质，说人误食后的状态要用中毒。"}, {"text": "这条小路晚上很有毒，最好别走。", "explanation": "这里应该用〈危险〉。有毒指物质含毒，小路不是毒物，说路况不安全要用危险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有毒", "is_correct": true, "explanation": "“有毒的东西不要放进嘴里”是合理的提醒，“有毒”正确。"}, {"text": "有益", "is_correct": false, "explanation": "语义：有益的东西不该禁止放进嘴里，这样说前后矛盾。"}, {"text": "有营养", "is_correct": false, "explanation": "语义：有营养的东西一般可以吃，不必禁止，这样说不通。"}, {"text": "动听", "is_correct": false, "explanation": "搭配：“动听”多形容声音、话语，不说“动听的东西”。"}], "explanations": {"有毒": "“有毒的东西不要放进嘴里”是合理的提醒，“有毒”正确。", "有益": "语义：有益的东西不该禁止放进嘴里，这样说前后矛盾。", "有营养": "语义：有营养的东西一般可以吃，不必禁止，这样说不通。", "动听": "搭配：“动听”多形容声音、话语，不说“动听的东西”。"}, "sentence_index": 6, "correct_answer": "有毒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她发烧好几天，医生说她有毒了。", "explanation": "这里应该用〈有病〉。有毒用来形容物质，说人身体不好要用有病或生病。"}, {"text": "这把剪刀很有毒，剪纸很好用。", "explanation": "这里应该用〈锋利〉。“有毒”形容含毒素的东西，剪刀不含毒；形容剪刀好使要说锋利。"}, {"text": "他的头发很有毒，又多又密。", "explanation": "这里应该用〈浓密〉。有毒指含毒素，头发多要说浓密，不是毒性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条蛇不有毒，别靠近它。", "corrected_sentence": "这条蛇有毒，别靠近它。", "error_description": "错误：“不有毒”。正确：“有毒”（肯定）或“没有毒”（否定）。“有”的否定要用“没有”，不能在“有”前面加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那种草有毒，他误吃后有毒了。", "corrected_sentence": "那种草有毒，他误吃后中毒了。", "error_description": "错误：“有毒了”（指人）。正确：“中毒了”。“有毒”只用来形容物质，人误食后受害要说“中毒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
