INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "加入其他材料中，用来改善其性能的物质。", "primary_collocate": null, "pronunciation": "zhù jì", "ipa": "ʈʂu˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "给橡胶加一点助剂，它就不容易老化。", "target_word": "助剂", "complexity_tier": "T3", "furigana": "gěi xiàng jiāo jiā yì diǎn zhù jì, tā jiù bù róng yì lǎo huà", "sentence_source": "generated"}, {"text": "这种助剂可以让油漆干得更快。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人往水泥里放了一些助剂。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶助剂能让塑料变得更软。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在面粉里没有加任何助剂。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里买来一批新助剂，价格不便宜。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种助剂用得越多，成本就越高。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把助剂慢慢倒进桶里搅一搅。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用了这种助剂，纸变得更白了。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书上写着助剂的用法。", "target_word": "助剂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "化学助剂", "label": "复合"}], "register": "书面", "sense_fingerprint": "加入后能让别的东西变好的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edafe57e-8182-4ddf-9c5d-57d2a9d9dbda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "助剂", "is_correct": true, "explanation": "“助剂”是加入后能让别的东西变好的物质，“给橡胶加一点助剂”通顺。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖加入橡胶后不能防止老化，句子说不通。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，加入橡胶不能使其不易老化，句子说不通。"}, {"text": "辣椒", "is_correct": false, "explanation": "语义：辣椒不能使橡胶不容易老化，与句意不合。"}], "explanations": {"助剂": "“助剂”是加入后能让别的东西变好的物质，“给橡胶加一点助剂”通顺。", "糖": "语义：糖加入橡胶后不能防止老化，句子说不通。", "汽油": "语义：汽油是燃料，加入橡胶不能使其不易老化，句子说不通。", "辣椒": "语义：辣椒不能使橡胶不容易老化，与句意不合。"}, "sentence_index": 0, "correct_answer": "助剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶助剂能让虫子死掉，效果很好。", "explanation": "这里应该用〈杀虫剂〉。助剂用来改善材料性能，不能杀虫，杀虫要说杀虫剂。"}, {"text": "这瓶助剂颜色很深，写字很清楚。", "explanation": "这里应该用〈墨水〉。助剂是加入材料里的物质，本身不用来写字，颜色深、写字清楚要说墨水。"}, {"text": "这瓶助剂能让墙变蓝，很好看。", "explanation": "这里应该用〈颜料〉。助剂本身不是颜色，能让墙变蓝要说颜料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "助剂", "is_correct": true, "explanation": "“助剂”指用于改善性能的物质，“用得越多，成本就越高”说的是材料，相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能“用得越多，成本就越高”，句子说不通。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“用”后面一般接物品或方法，不说“用口音”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是消耗的材料，说“用得越多成本越高”不合理。"}], "explanations": {"助剂": "“助剂”指用于改善性能的物质，“用得越多，成本就越高”说的是材料，相符。", "空气": "语义：空气不能“用得越多，成本就越高”，句子说不通。", "口音": "搭配：“用”后面一般接物品或方法，不说“用口音”。", "歌曲": "语义：歌曲不是消耗的材料，说“用得越多成本越高”不合理。"}, "sentence_index": 6, "correct_answer": "助剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仓库是用助剂盖的。", "explanation": "这里应该用〈水泥〉。助剂是加入主要材料里起辅助作用的物质，盖房子的材料要说水泥。"}, {"text": "他是我们组的助剂，大家都很依赖他。", "explanation": "“助剂”在这里指人是误用。助剂只指加入材料中的物质，不能用来称人。"}, {"text": "这瓶助剂很趁手，用来修理自行车最好。", "explanation": "“助剂”指加入材料中的物质，不指工具，这里说的是修车的工具，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把助剂们倒进桶里了。", "corrected_sentence": "我把助剂倒进桶里了。", "error_description": "错误：“们”用错了。“助剂”是物质名词，不能加“们”表示复数，“们”只用于指人或有生命的名词。正确：“我把助剂倒进桶里了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂里进了一只助剂，很快就用完了。", "corrected_sentence": "厂里进了一包助剂，很快就用完了。", "error_description": "错误：量词“只”。正确：“包”。“助剂”的量词用“包”，“只”多用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
