INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "事情比正常时间慢。", "primary_collocate": null, "pronunciation": "zhì hòu", "ipa": "ʈʂʅ⁵¹ xoʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "今天的会议开始时间滞后了一个小时。", "target_word": "滞后", "complexity_tier": "T3", "furigana": "jīn tiān de huì yì kāi shǐ shí jiān zhì hòu le yí gè xiǎo shí", "sentence_source": "generated"}, {"text": "由于设备故障，这批产品的交付时间滞后了一周。", "target_word": "滞后", "complexity_tier": "T3", "furigana": "yóu yú shè bèi gù zhàng, zhè pī chǎn pǐn de jiāo fù shí jiān zhì hòu le yí zhōu", "sentence_source": "generated"}, {"text": "这份报告的完成时间滞后了好几天。", "target_word": "滞后", "complexity_tier": "T3", "furigana": "zhè fèn bào gào de wán chéng shí jiān zhì hòu le hǎo jǐ tiān", "sentence_source": "generated"}, {"text": "因为大雪，这次的物资运输滞后了一天。", "target_word": "滞后", "complexity_tier": "T3", "furigana": "yīn wèi dà xuě, zhè cì de wù zī yùn shū zhì hòu le yì tiān", "sentence_source": "generated"}, {"text": "这次考试成绩的公布滞后了。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付款滞后会影响我们的合作。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的反应有点儿滞后，没听懂笑话。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络不好，视频的声音总是滞后。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作滞后了，我只好今晚加班。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说孩子的发育有些滞后。", "target_word": "滞后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滞后了", "label": "体标"}, {"form": "滯後", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事情进行得比正常时间慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edafe57e-8182-4ddf-9c5d-57d2a9d9dbda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。滞后（zhì hòu）指事情进行得比正常时间慢。"}, {"text": "之后", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，“之后”意思是某件事以后。"}, {"text": "事后", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），“事后”意思是事情发生以后。"}, {"text": "日后", "is_correct": false, "explanation": "rì 与 zhì 声母不同（r 与 zh），“日后”意思是将来的某个时候。"}], "explanations": {"滞后": "正确。滞后（zhì hòu）指事情进行得比正常时间慢。", "之后": "zhī（第一声）与 zhì（第四声）声调不同，“之后”意思是某件事以后。", "事后": "shì 与 zhì 声母不同（sh 与 zh），“事后”意思是事情发生以后。", "日后": "rì 与 zhì 声母不同（r 与 zh），“日后”意思是将来的某个时候。"}, "sentence_index": null, "correct_answer": "滞后"}, "level_3": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。“滞后了一个小时”说明会议开始得比原定时间晚，符合句意。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”的主体是人，“时间”不能讨论，句子不通。"}, {"text": "等待", "is_correct": false, "explanation": "配价：“等待”需要有人作主语，“会议开始时间”不能等待。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“检查”指查看事物，开始时间不能被检查一个小时。"}], "explanations": {"滞后": "正确。“滞后了一个小时”说明会议开始得比原定时间晚，符合句意。", "讨论": "语义：“讨论”的主体是人，“时间”不能讨论，句子不通。", "等待": "配价：“等待”需要有人作主语，“会议开始时间”不能等待。", "检查": "语义：“检查”指查看事物，开始时间不能被检查一个小时。"}, "sentence_index": 0, "correct_answer": "滞后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告，他滞后了三天才交。", "explanation": "这里应该用〈拖延〉。滞后说的是事情的进程比正常时间慢，不用来说人故意拖延。"}, {"text": "孩子又滞后了十分钟才到学校。", "explanation": "这里应该用〈迟到〉。滞后描述事情的进程，不用于描述人到达得晚。"}, {"text": "他在机场滞后了一晚上。", "explanation": "这里应该用〈滞留〉。滞后指事情比正常时间慢，表示人被困在某处要用“滞留”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滞后", "is_correct": true, "explanation": "正确。“反应有点儿滞后”说明反应比平时慢，所以没听懂笑话，符合句意。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量，不能说“反应有点儿增加”。"}, {"text": "发布", "is_correct": false, "explanation": "语义：“发布”是公开宣布，反应不能发布，句子不通。"}, {"text": "坚持", "is_correct": false, "explanation": "配价：“坚持”要带动作宾语，“反应有点儿坚持”不成立。"}], "explanations": {"滞后": "正确。“反应有点儿滞后”说明反应比平时慢，所以没听懂笑话，符合句意。", "增加": "搭配：“增加”说数量，不能说“反应有点儿增加”。", "发布": "语义：“发布”是公开宣布，反应不能发布，句子不通。", "坚持": "配价：“坚持”要带动作宾语，“反应有点儿坚持”不成立。"}, "sentence_index": 6, "correct_answer": "滞后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的颜色滞后了。", "explanation": "这里应该用〈变深〉或〈变淡〉。滞后用于发展和进程，颜色没有“滞后”的说法。"}, {"text": "他走在队伍最后面，滞后得很远。", "explanation": "这里应该用〈落后〉。滞后说的是事情的进程比正常时间慢，人在队伍中落在后面要说“落后”。"}, {"text": "他在教室里滞后了一个小时。", "explanation": "这里应该用〈逗留〉。滞后指进程比正常时间慢，不表示人停在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这趟列车的发车时间滞后得二十分钟。", "corrected_sentence": "这趟列车的发车时间滞后了二十分钟。", "error_description": "错误：“滞后”后面用了“得”。正确：“滞后了二十分钟”。“得”后面要接表示程度的成分，如“滞后得厉害”；说已经发生的时间量要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批货物的到达时间滞后了了好几天。", "corrected_sentence": "这批货物的到达时间滞后了好几天。", "error_description": "错误：“了”重复了。正确：“滞后了好几天”。“了”只用一次，表示时间的变化已经发生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
