INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用来给衣服染颜色的东西。", "primary_collocate": null, "pronunciation": "ǒu dàn rǎn liào", "ipa": "oʊ̯²¹⁴ tan⁵¹ ʐan²¹⁴ liɑʊ̯⁵¹", "syllable_count": 4, "sentences": [{"text": "妈妈说这种偶氮染料不太安全。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用偶氮染料把白衬衫染成了蓝色。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶偶氮染料是红色的。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有很多种偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染衣服要先买偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶氮染料不能放在孩子手边。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐用偶氮染料染了一条黄裙子。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偶氮染料很便宜，颜色也很亮。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把偶氮染料倒进热水里。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一包绿色的偶氮染料。", "target_word": "偶氮染料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "瓶", "label": "量词"}], "register": "专业", "sense_fingerprint": "给衣服染色用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edafe57e-8182-4ddf-9c5d-57d2a9d9dbda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶氮染料", "is_correct": true, "explanation": "正确。“妈妈说这种偶氮染料不太安全”，说的是一种染色用品，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“安全”说的是物品或环境是否有危险，月亮不能说不安全。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天不是产品，说它不安全没有意义。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“安全”多用于物品、食品、环境，不和“天空”搭配。"}], "explanations": {"偶氮染料": "正确。“妈妈说这种偶氮染料不太安全”，说的是一种染色用品，符合句意。", "月亮": "语义：“安全”说的是物品或环境是否有危险，月亮不能说不安全。", "春天": "语义：春天不是产品，说它不安全没有意义。", "天空": "搭配：“安全”多用于物品、食品、环境，不和“天空”搭配。"}, "sentence_index": 0, "correct_answer": "偶氮染料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子用偶氮染料刷牙。", "explanation": "这里应该用〈牙膏〉。偶氮染料是染衣服的染料，不能用来刷牙，刷牙要用牙膏。"}, {"text": "学生用偶氮染料写字。", "explanation": "这里应该用〈墨汁〉。偶氮染料用于染色，写字要用墨汁。"}, {"text": "他用偶氮染料擦干了头发。", "explanation": "这里应该用〈毛巾〉。偶氮染料用于染色，擦干头发要用毛巾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶氮染料", "is_correct": true, "explanation": "正确。“姐姐用偶氮染料染了一条黄裙子”，说明她用染料给裙子染了色，符合句意。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是清洁用品，不能用来给裙子染色。"}, {"text": "针线", "is_correct": false, "explanation": "语义：针线用于缝纫，不能用来染布。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“染”需要用染料或颜料作工具，阳光不能作为染色的工具。"}], "explanations": {"偶氮染料": "正确。“姐姐用偶氮染料染了一条黄裙子”，说明她用染料给裙子染了色，符合句意。", "牙刷": "语义：牙刷是清洁用品，不能用来给裙子染色。", "针线": "语义：针线用于缝纫，不能用来染布。", "阳光": "搭配：“染”需要用染料或颜料作工具，阳光不能作为染色的工具。"}, "sentence_index": 6, "correct_answer": "偶氮染料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈吃了一些偶氮染料，所以生病了。", "explanation": "这里应该用〈药片〉。偶氮染料是染衣服的化学品，不能吃，吃的东西要用药片。"}, {"text": "我在厨房里用偶氮染料煮饭。", "explanation": "这里应该用〈大米〉。偶氮染料是染衣服的化学品，不能用来煮饭，煮饭要用大米。"}, {"text": "冬天我把偶氮染料盖在身上当被子。", "explanation": "这里应该用〈毛毯〉。偶氮染料是染衣服的化学品，不能拿来当被子，保暖要用毛毯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只偶氮染料是绿色的。", "corrected_sentence": "这包偶氮染料是绿色的。", "error_description": "错误：量词“只”用错了。正确：“这包偶氮染料”。偶氮染料按包、瓶计量，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些偶氮染料们卖得很便宜。", "corrected_sentence": "这些偶氮染料卖得很便宜。", "error_description": "错误：名词“偶氮染料”后面加了“们”。正确：“这些偶氮染料”。“们”只用于指人的名词，不能用于物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26264, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：数量达不到需要，与“充分”的数量义相反，是反义词。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭：形容坡面很陡，与“充分”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：形容质地软，与“充分”没有反义关系。"}, {"text": "诚实", "is_correct": false, "explanation": "诚实：形容人说实话，与“充分”没有反义关系。"}], "correct_answer": "不足", "explanations": {"不足": "不足：数量达不到需要，与“充分”的数量义相反，是反义词。", "陡峭": "陡峭：形容坡面很陡，与“充分”没有反义关系。", "柔软": "柔软：形容质地软，与“充分”没有反义关系。", "诚实": "诚实：形容人说实话，与“充分”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26264, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧张", "is_correct": true, "explanation": "紧张：指时间不宽裕，与“时间充分”相反，是反义词。"}, {"text": "陈旧", "is_correct": false, "explanation": "陈旧：指东西旧、过时，与“充分”没有反义关系。"}, {"text": "高明", "is_correct": false, "explanation": "高明：指水平高、有见识，与“充分”没有反义关系。"}, {"text": "柔和", "is_correct": false, "explanation": "柔和：指光线、声音等温和，与“充分”没有反义关系。"}], "correct_answer": "紧张", "explanations": {"紧张": "紧张：指时间不宽裕，与“时间充分”相反，是反义词。", "陈旧": "陈旧：指东西旧、过时，与“充分”没有反义关系。", "高明": "高明：指水平高、有见识，与“充分”没有反义关系。", "柔和": "柔和：指光线、声音等温和，与“充分”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26264, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示某个东西很多，完全够用了。", "primary_collocate": null, "pronunciation": "chōng fèn", "ipa": "tʂʰʊŋ˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "这个学校的图书资料很充分，学生可以随便借阅。", "target_word": "充分", "complexity_tier": "T3", "furigana": "zhè ge xué xiào de tú shū zī liào hěn chōng fèn, xué shēng kě yǐ suí biàn jiè yuè", "sentence_source": "generated"}, {"text": "昨晚睡眠充分，我一点儿也不累。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的食物很充分，够吃一个星期。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物需要充分的阳光和水。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的经费很充分，可以多买些书。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区雨水充分，粮食长得很好。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的营养很充分，身体很好。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水电都很充分，你们放心住吧。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里睡得充分，早上特别有精神。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行时间充分，我们可以慢慢玩。", "target_word": "充分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容光线、睡眠、食物、时间等数量多，完全够用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884de977-ec2d-4491-87db-758e8e0f7dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分（chōng fèn）此处指数量多、完全够用，是本题的目标词。"}, {"text": "春分", "is_correct": false, "explanation": "春分（chūn fèn）与充分（chōng fèn）第一音节韵母不同（ūn 对 ōng），意思是春天的节气。"}, {"text": "中分", "is_correct": false, "explanation": "中分（zhōng fèn）与充分（chōng fèn）声母不同（zh 对 ch），意思是从中间分开。"}, {"text": "冲犯", "is_correct": false, "explanation": "冲犯（chōng fàn）与充分（chōng fèn）第二音节韵母不同（a 对 en），声调相同，意思是冒犯。"}, {"text": "成分", "is_correct": false, "explanation": "成分（chéng fèn）与充分（chōng fèn）第一音节韵母与声调不同，意思是组成部分。"}, {"text": "冲锋", "is_correct": false, "explanation": "冲锋（chōng fēng）与充分（chōng fèn）第二音节韵母与声调不同，意思是向前猛冲。"}], "explanations": {"充分": "充分（chōng fèn）此处指数量多、完全够用，是本题的目标词。", "春分": "春分（chūn fèn）与充分（chōng fèn）第一音节韵母不同（ūn 对 ōng），意思是春天的节气。", "中分": "中分（zhōng fèn）与充分（chōng fèn）声母不同（zh 对 ch），意思是从中间分开。", "冲犯": "冲犯（chōng fàn）与充分（chōng fèn）第二音节韵母不同（a 对 en），声调相同，意思是冒犯。", "成分": "成分（chéng fèn）与充分（chōng fèn）第一音节韵母与声调不同，意思是组成部分。", "冲锋": "冲锋（chōng fēng）与充分（chōng fèn）第二音节韵母与声调不同，意思是向前猛冲。"}, "sentence_index": null, "correct_answer": "充分"}, "level_3": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分：图书资料数量多、完全够用，符合句意。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”指数量很少，与“学生可以随便借阅”矛盾。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格高，不能用来说图书资料的数量。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材外形，不能用来形容图书资料。"}], "explanations": {"充分": "充分：图书资料数量多、完全够用，符合句意。", "稀少": "语义：“稀少”指数量很少，与“学生可以随便借阅”矛盾。", "昂贵": "搭配：“昂贵”说价格高，不能用来说图书资料的数量。", "高大": "体貌：“高大”形容身材外形，不能用来形容图书资料。"}, "sentence_index": 0, "correct_answer": "充分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对客人很充分。", "explanation": "这里应该用〈热情〉。热情说待人友好、主动；充分说东西多或条件够用，不用来形容对人的态度。"}, {"text": "他的个子很充分，站在人群里很显眼。", "explanation": "这里应该用〈高〉。“高”形容身材或位置在上方；“充分”说数量或条件够用，不用来形容个子。"}, {"text": "这里的雾很充分，几乎看不清路。", "explanation": "这里应该用〈浓〉。浓形容雾的程度深；充分说数量或条件够用，不用来形容雾的浓淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充分", "is_correct": true, "explanation": "充分：营养供应足够，符合句意，与“身体很好”一致。"}, {"text": "低劣", "is_correct": false, "explanation": "语义：“低劣”指质量差，与后面“身体很好”矛盾。"}, {"text": "陈旧", "is_correct": false, "explanation": "搭配：“陈旧”形容东西旧、过时，不能用来形容营养。"}, {"text": "壮实", "is_correct": false, "explanation": "体貌：“壮实”形容人的身材结实，不能用来形容营养。"}], "explanations": {"充分": "充分：营养供应足够，符合句意，与“身体很好”一致。", "低劣": "语义：“低劣”指质量差，与后面“身体很好”矛盾。", "陈旧": "搭配：“陈旧”形容东西旧、过时，不能用来形容营养。", "壮实": "体貌：“壮实”形容人的身材结实，不能用来形容营养。"}, "sentence_index": 6, "correct_answer": "充分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼睛很充分，看东西很清楚。", "explanation": "这里应该用〈明亮〉。“明亮”形容光线强或眼神有光彩；“充分”说数量或条件够用，不用来形容眼睛。"}, {"text": "他的脾气很充分，大家都不敢惹他。", "explanation": "这里应该用〈大〉。“大”说程度高；“充分”说数量或条件够用，不用来形容脾气。"}, {"text": "他是个很充分的人，大家都喜欢他。", "explanation": "这里应该用〈和气〉。和气说待人友善；充分说数量或条件够用，不用来形容人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个商场的停车位很更充分，你可以放心开车去。", "corrected_sentence": "这个商场的停车位很充分，你可以放心开车去。", "error_description": "程度副词叠用：“很”与“更”不能同时修饰“充分”，应删去“更”，说“很充分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的雨水没充分，庄稼长得很好。", "corrected_sentence": "今年的雨水很充分，庄稼长得很好。", "error_description": "否定词误用：“没”不能直接修饰形容词“充分”；此句前后句意为雨水足够，应说“很充分”，与“庄稼长得很好”相符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
