INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26266, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "没有经过", "primary_collocate": null, "pronunciation": "wèi jīng", "ipa": "ueɪ˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "未经许可，请不要拍照。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果未经清洗，不要直接吃。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经医生同意，不能自己吃药。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他未经通知就来到了公司。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经主人允许，别动他的东西。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息未经证实，大家别相信。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经同意，公司不能用你的照片。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路未经修理，车很难走。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未经学校批准，学生不能办活动。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服未经试穿，我不敢买。", "target_word": "未经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示事先没有经过某种手续、同意或过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edafe57e-8182-4ddf-9c5d-57d2a9d9dbda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未经", "is_correct": true, "explanation": "正确。“未经许可”表示没有取得许可，与“请不要拍照”的要求相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经许可”说明许可已取得，与“请不要拍照”的前提矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是许可”与“请不要拍照”相矛盾，句意不通。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即许可”表示马上批准，与“未经许可”的前提相反，不搭配。"}], "explanations": {"未经": "正确。“未经许可”表示没有取得许可，与“请不要拍照”的要求相符。", "已经": "语义：“已经许可”说明许可已取得，与“请不要拍照”的前提矛盾。", "总是": "语义：“总是许可”与“请不要拍照”相矛盾，句意不通。", "立即": "搭配：“立即许可”表示马上批准，与“未经许可”的前提相反，不搭配。"}, "sentence_index": 0, "correct_answer": "未经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他未经来过公司。", "explanation": "这里应该用〈已经〉。描述已经发生的经历要说“已经来过公司”，“未经”不能这样用。"}, {"text": "我未经吃饭就出门了。", "explanation": "这里应该用〈没有〉。“未经”后面接的是需要先经过的手续，表示没做某事时应说“没有吃饭”。"}, {"text": "他未经在这家公司工作过。", "explanation": "这里应该用〈曾经〉。描述经历要说“曾经在这家公司工作过”，“未经”不能接经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未经", "is_correct": true, "explanation": "正确。“未经同意”表示没有得到许可，与“公司不能用你的照片”相符。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意同意”与“公司不能用你的照片”的结论相矛盾，句子不通。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终同意”与“公司不能用”的结论相矛盾。"}, {"text": "早已", "is_correct": false, "explanation": "语义：“早已同意”说明许可已经取得，与“公司不能用”的结论矛盾。"}], "explanations": {"未经": "正确。“未经同意”表示没有得到许可，与“公司不能用你的照片”相符。", "随意": "语义：“随意同意”与“公司不能用你的照片”的结论相矛盾，句子不通。", "始终": "语义：“始终同意”与“公司不能用”的结论相矛盾。", "早已": "语义：“早已同意”说明许可已经取得，与“公司不能用”的结论矛盾。"}, "sentence_index": 6, "correct_answer": "未经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他未经通过考试。", "explanation": "这里应该用〈未能〉。“未经”表示没有经过某个手续，说明没有达到结果时应说“未能通过考试”。"}, {"text": "比赛未经结束。", "explanation": "这里应该用〈尚未〉。“未经”不能用来说明过程还没完成，应说“比赛尚未结束”。"}, {"text": "我未经见过他。", "explanation": "这里应该用〈未曾〉。描述没有见过的经历要说“未曾见过他”，“未经”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他未经通知过就进了办公室。", "corrected_sentence": "他未经通知就进了办公室。", "error_description": "体标错误：“未经”后面接的动词“通知”不能带“过”，应说“未经通知就进了办公室”，不说“未经通知过就进了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份合同未经了律师审查，不能签字。", "corrected_sentence": "这份合同未经律师审查，不能签字。", "error_description": "体标错误：“未经”是介词，本身不带“了”，后面直接接需要先经过的手续。应说“这份合同未经律师审查，不能签字。”，不说“未经了律师审查”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4a54ea-29e5-4ee6-af16-766d995ab41f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
