INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水体就是很多水在一起的地方，比如河、湖、海。", "primary_collocate": null, "pronunciation": "shuǐ tǐ", "ipa": "ʂweɪ˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "湖是一个很大的水体。", "target_word": "水体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，河和海都是水体。", "target_word": "水体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个水体很干净，里面有很多鱼。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "未经许可，不得在该水体中捕捞或游泳。", "target_word": "水体", "complexity_tier": "T3", "furigana": "wèi jīng xǔ kě, bù dé zài gāi shuǐ tǐ zhōng bǔ lāo huò yóu yǒng.", "sentence_source": "generated"}, {"text": "水体太脏了，我们不能喝。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天水体的温度比较高。", "target_word": "水体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地球上有很多不同的水体。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要往水体里扔垃圾。", "target_word": "水体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这片水体不大，但是很深。", "target_word": "水体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水体变脏了，鱼就会生病。", "target_word": "水体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "水體", "label": "繁体"}, {"form": "水体污染", "label": "复合"}], "register": "书面语", "sense_fingerprint": "水体：河、湖、海等很多水聚在一起的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884de977-ec2d-4491-87db-758e8e0f7dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水体", "is_correct": true, "explanation": "正确答案。水体指河、湖、海等很多水聚在一起的地方。"}, {"text": "水底", "is_correct": false, "explanation": "dǐ（第三声）与 tǐ（第三声）声母不同（d 与 t），意思是水的底部，与“水体”不同。"}, {"text": "水洗", "is_correct": false, "explanation": "xǐ（第三声）与 tǐ（第三声）声母不同（x 与 t），意思是用水清洗。"}, {"text": "水里", "is_correct": false, "explanation": "lǐ（第三声）与 tǐ（第三声）声母不同（l 与 t），意思是在水中。"}], "explanations": {"水体": "正确答案。水体指河、湖、海等很多水聚在一起的地方。", "水底": "dǐ（第三声）与 tǐ（第三声）声母不同（d 与 t），意思是水的底部，与“水体”不同。", "水洗": "xǐ（第三声）与 tǐ（第三声）声母不同（x 与 t），意思是用水清洗。", "水里": "lǐ（第三声）与 tǐ（第三声）声母不同（l 与 t），意思是在水中。"}, "sentence_index": null, "correct_answer": "水体"}, "level_3": {"options": [{"text": "水体", "is_correct": true, "explanation": "正确。“水体”指河、湖、海等水聚集的地方，可以用“很大”来形容。"}, {"text": "水费", "is_correct": false, "explanation": "搭配：“很大”修饰的是体积或范围，“水费”是价钱，不能用来形容湖。"}, {"text": "水质", "is_correct": false, "explanation": "搭配：“水质”说的是水的好坏，不能说“很大的水质”来形容湖。"}, {"text": "水族", "is_correct": false, "explanation": "语义：“水族”指水中的生物，不指湖这样的水域，句子意思不通。"}], "explanations": {"水体": "正确。“水体”指河、湖、海等水聚集的地方，可以用“很大”来形容。", "水费": "搭配：“很大”修饰的是体积或范围，“水费”是价钱，不能用来形容湖。", "水质": "搭配：“水质”说的是水的好坏，不能说“很大的水质”来形容湖。", "水族": "语义：“水族”指水中的生物，不指湖这样的水域，句子意思不通。"}, "sentence_index": 0, "correct_answer": "水体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山上的水体很急，孩子不能靠近。", "explanation": "这里应该用〈水流〉。水流说的是流动的速度，水体指水的聚集处，不能说“很急”。"}, {"text": "夜里传来清脆的水体。", "explanation": "这里应该用〈水声〉。水声指水流发出的声音，水体是水的聚集处，不能用来指声音。"}, {"text": "窗上挂着几滴水体。", "explanation": "这里应该用〈水滴〉。水滴是一小颗水，水体是大片水的聚集处，不能用“滴”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水体", "is_correct": true, "explanation": "正确。“水体”指地球上河、湖、海等水聚集的地方，与“很多不同的”搭配自然。"}, {"text": "水花", "is_correct": false, "explanation": "语义：“水花”指水被溅起来的浪花，不指水聚集的地方，不能用于“地球上有很多不同的”。"}, {"text": "水洗", "is_correct": false, "explanation": "搭配：“水洗”是一种洗涤方式，不指地球上的水域，与“很多不同的”搭配不通。"}, {"text": "水蒸气", "is_correct": false, "explanation": "语义：水蒸气是气态的水，不是河、湖、海那样聚集的水域，与“地球上有很多不同的”搭配也不自然。"}], "explanations": {"水体": "正确。“水体”指地球上河、湖、海等水聚集的地方，与“很多不同的”搭配自然。", "水花": "语义：“水花”指水被溅起来的浪花，不指水聚集的地方，不能用于“地球上有很多不同的”。", "水洗": "搭配：“水洗”是一种洗涤方式，不指地球上的水域，与“很多不同的”搭配不通。", "水蒸气": "语义：水蒸气是气态的水，不是河、湖、海那样聚集的水域，与“地球上有很多不同的”搭配也不自然。"}, "sentence_index": 6, "correct_answer": "水体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖边有一只很大的水体。", "explanation": "这里应该用〈片〉。“只”用于小动物等，不能用来数水体。"}, {"text": "那把水体很深，很危险。", "explanation": "这里应该用〈片〉。“把”用于有柄的器具，不能用来数水体。"}, {"text": "一本很干净的水体，鱼很多。", "explanation": "这里应该用〈片〉。“本”用于书册，不能用来数水体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们不能水体里玩耍。", "corrected_sentence": "孩子们不能在水体里玩耍。", "error_description": "错误在于缺少“在”。表示在某个场所做某事，要用“在……里”，应说“在水体里玩耍”，不能说“水体里玩耍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很深水体。", "corrected_sentence": "这是一个很深的水体。", "error_description": "错误在“很深”和“水体”之间缺少“的”。“很深”修饰名词时要加“的”，应说“很深的水体”，不能说“很深水体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
