INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "时尚品牌就是很流行、很多人喜欢的牌子。", "primary_collocate": null, "pronunciation": "shí shàng pǐn pái", "ipa": "ʂɻ̩˧˥ ʂaŋ˥˩ pʰin˨˩˦ pʰaɪ˧˥", "syllable_count": 4, "sentences": [{"text": "她的衣柜里有很多时尚品牌的衣服。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时尚品牌很流行，年轻人都喜欢。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买不起贵的时尚品牌，只买便宜的。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个时尚品牌的运动鞋最近最流行？", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店只卖时尚品牌的衣服和包。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个时尚品牌的老客户。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时尚品牌的标志很好认。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐想去一家时尚品牌的店当售货员。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多明星穿这个时尚品牌的衣服。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个时尚品牌的广告到处都是。", "target_word": "时尚品牌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "時尚品牌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很流行、很多人喜欢的牌子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18d875c5-7ca1-4d87-b422-a099d3a3d100') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时尚品牌", "is_correct": true, "explanation": "正确。时尚品牌指很流行、很多人喜欢的牌子，句中衣柜里的衣服正是这类品牌的衣服。"}, {"text": "时令水果", "is_correct": false, "explanation": "搭配：“……的衣服”前应是服装的品牌或种类，“时令水果”不能修饰衣服，搭配不当。"}, {"text": "中药材", "is_correct": false, "explanation": "语义：中药材是药材，与“衣柜里的衣服”不属于同一类事物。"}, {"text": "农业机械", "is_correct": false, "explanation": "搭配：“农业机械”不能修饰“衣服”，二者搭配不当。"}], "explanations": {"时尚品牌": "正确。时尚品牌指很流行、很多人喜欢的牌子，句中衣柜里的衣服正是这类品牌的衣服。", "时令水果": "搭配：“……的衣服”前应是服装的品牌或种类，“时令水果”不能修饰衣服，搭配不当。", "中药材": "语义：中药材是药材，与“衣柜里的衣服”不属于同一类事物。", "农业机械": "搭配：“农业机械”不能修饰“衣服”，二者搭配不当。"}, "sentence_index": 0, "correct_answer": "时尚品牌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最佩服的时尚品牌是她。", "explanation": "这里应该用〈时尚达人〉。时尚品牌指很流行的牌子，不指人，不能说某人是时尚品牌。"}, {"text": "那个时尚品牌很有名，大家都认识她。", "explanation": "这里应该用〈明星〉。时尚品牌是牌子，不能被“认识她”，指人才用“认识她”。"}, {"text": "那条时尚品牌很好看，我们都想买。", "explanation": "这里应该用〈个〉。品牌用量词“个”，“条”多用于细长的东西，不能用于牌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时尚品牌", "is_correct": true, "explanation": "正确。时尚品牌有自己的标志，句中说“标志很好认”，符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，没有可供辨认的品牌标志，“标志很好认”不能用于它。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，没有品牌标志，“标志很好认”不能用于它。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法是语言规则，不是实物，没有可以“很好认”的标志。"}], "explanations": {"时尚品牌": "正确。时尚品牌有自己的标志，句中说“标志很好认”，符合句意。", "数学": "语义：数学是学科，没有可供辨认的品牌标志，“标志很好认”不能用于它。", "蔬菜": "语义：蔬菜是食物，没有品牌标志，“标志很好认”不能用于它。", "语法": "语义：语法是语言规则，不是实物，没有可以“很好认”的标志。"}, "sentence_index": 6, "correct_answer": "时尚品牌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座公园是个时尚品牌，周末很多人来散步。", "explanation": "这里不能指地方。时尚品牌指很流行的牌子，公园不是牌子，不能这样用。"}, {"text": "这家医院是一个时尚品牌，很多人在那里看病。", "explanation": "这里不能指医疗机构。时尚品牌指很流行的牌子，医院不属于这类牌子。"}, {"text": "我们在时尚品牌里学了三年数学。", "explanation": "这里不能指场所。时尚品牌是牌子，不是学校，不能在里面学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈过穿时尚品牌的衣服。", "corrected_sentence": "我妈妈穿过时尚品牌的衣服。", "error_description": "错误：“过”放在了动词“穿”前面。正确：“过”应紧跟动词之后，说“穿过时尚品牌的衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一把时尚品牌，很受年轻人欢迎。", "corrected_sentence": "这是一个时尚品牌，很受年轻人欢迎。", "error_description": "错误：量词“把”用错了。“时尚品牌”应用量词“个”，“把”多用于有柄的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26272, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暴露", "is_correct": true, "explanation": "反义：“暴露”指被人看见或发现，与“隐蔽”（不让别人看见）意思相反。"}, {"text": "出发", "is_correct": false, "explanation": "无关：“出发”指动身离开，与隐藏、被发现没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "无关：“休息”指停下来歇息，与隐蔽的意思没有反义关系。"}, {"text": "游览", "is_correct": false, "explanation": "无关：“游览”指参观风景，与隐蔽的意思没有反义关系。"}], "correct_answer": "暴露", "explanations": {"暴露": "反义：“暴露”指被人看见或发现，与“隐蔽”（不让别人看见）意思相反。", "出发": "无关：“出发”指动身离开，与隐藏、被发现没有反义关系。", "休息": "无关：“休息”指停下来歇息，与隐蔽的意思没有反义关系。", "游览": "无关：“游览”指参观风景，与隐蔽的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26272, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暴露", "is_correct": true, "explanation": "反义：“暴露”指被人看见，与“隐蔽”（躲藏、不被发现）意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交换意见，与躲藏没有反义关系。"}, {"text": "起床", "is_correct": false, "explanation": "无关：“起床”指从床上起来，与隐蔽的意思没有反义关系。"}, {"text": "洗涤", "is_correct": false, "explanation": "无关：“洗涤”指清洗，与隐蔽的意思没有反义关系。"}], "correct_answer": "暴露", "explanations": {"暴露": "反义：“暴露”指被人看见，与“隐蔽”（躲藏、不被发现）意思相反。", "讨论": "无关：“讨论”指交换意见，与躲藏没有反义关系。", "起床": "无关：“起床”指从床上起来，与隐蔽的意思没有反义关系。", "洗涤": "无关：“洗涤”指清洗，与隐蔽的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不让别人看见或发现。", "primary_collocate": null, "pronunciation": "yǐn bì", "ipa": "in˨˩˦ pi˥˩", "syllable_count": 2, "sentences": [{"text": "战士们隐蔽在树林里，等着天黑。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到枪声，大家马上隐蔽起来。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侦察兵隐蔽在草丛里，等待敌人经过。", "target_word": "隐蔽", "complexity_tier": "T3", "furigana": "zhēn chá bīng yǐn bì zài cǎo cóng lǐ děng dài dí rén jīng guò", "sentence_source": "generated"}, {"text": "请大家就近隐蔽，不要乱跑。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哨兵隐蔽在岗楼里，观察四周的动静。", "target_word": "隐蔽", "complexity_tier": "T3", "furigana": "shào bīng yǐn bì zài gǎng lóu lǐ guān chá sì zhōu de dòng jìng", "sentence_source": "generated"}, {"text": "飞机来了，我们赶快隐蔽到山洞里。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人隐蔽着，静静看着前面的鹿。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察隐蔽在对面楼上，监视着那家店。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特工隐蔽在大树后面，等待接头的人出现。", "target_word": "隐蔽", "complexity_tier": "T3", "furigana": "tè gōng yǐn bì zài dà shù hòu miàn děng dài jiē tóu de rén chū xiàn", "sentence_source": "generated"}, {"text": "他们隐蔽了一整夜，天亮才出来。", "target_word": "隐蔽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隐蔽了", "label": "体标"}, {"form": "隐蔽着", "label": "体标"}, {"form": "隱蔽", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人或物躲藏起来，不让别人看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '793f12b2-1a45-4e9f-b63f-7c7c045ff77e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26272, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隐蔽", "is_correct": true, "explanation": "隐蔽（yǐn bì）：躲藏起来，不让别人看见，即本词条的动词义。"}, {"text": "银币", "is_correct": false, "explanation": "银币（yín bì）与隐蔽的第一个音节不同：yín 为第二声，yǐn 为第三声，声调不同。银币意思是银质的硬币。"}, {"text": "影壁", "is_correct": false, "explanation": "影壁（yǐng bì）与隐蔽的第一个音节韵尾不同：in 与 ing 的韵尾不同，意思是中式建筑门前的照壁。"}, {"text": "紧闭", "is_correct": false, "explanation": "紧闭（jǐn bì）与隐蔽的第一个音节声母不同：j 与 y 不同，意思是关得很紧。"}, {"text": "引力", "is_correct": false, "explanation": "引力（yǐn lì）与隐蔽的第二个音节声母不同：l 与 b 不同，意思是物体之间相互吸引的力。"}], "explanations": {"隐蔽": "隐蔽（yǐn bì）：躲藏起来，不让别人看见，即本词条的动词义。", "银币": "银币（yín bì）与隐蔽的第一个音节不同：yín 为第二声，yǐn 为第三声，声调不同。银币意思是银质的硬币。", "影壁": "影壁（yǐng bì）与隐蔽的第一个音节韵尾不同：in 与 ing 的韵尾不同，意思是中式建筑门前的照壁。", "紧闭": "紧闭（jǐn bì）与隐蔽的第一个音节声母不同：j 与 y 不同，意思是关得很紧。", "引力": "引力（yǐn lì）与隐蔽的第二个音节声母不同：l 与 b 不同，意思是物体之间相互吸引的力。"}, "sentence_index": null, "correct_answer": "隐蔽"}, "level_3": {"options": [{"text": "隐蔽", "is_correct": true, "explanation": "正确。“隐蔽”表示躲藏起来，与“等着天黑”的伏击情境相符。"}, {"text": "嬉戏", "is_correct": false, "explanation": "语义：“嬉戏”指玩耍，与战士等待天黑时的紧张处境不符。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：“歌唱”是唱歌，与战士潜伏等待的情境相矛盾。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”多指参观风景名胜，与“在树林里等着天黑”的军事处境不搭。"}], "explanations": {"隐蔽": "正确。“隐蔽”表示躲藏起来，与“等着天黑”的伏击情境相符。", "嬉戏": "语义：“嬉戏”指玩耍，与战士等待天黑时的紧张处境不符。", "歌唱": "语义：“歌唱”是唱歌，与战士潜伏等待的情境相矛盾。", "游览": "搭配：“游览”多指参观风景名胜，与“在树林里等着天黑”的军事处境不搭。"}, "sentence_index": 0, "correct_answer": "隐蔽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在老板面前隐蔽了，大声反驳了每一句。", "explanation": "这里应该用〈顶撞〉。“隐蔽”指躲起来不让人看见，与“大声反驳”的公开对抗矛盾。"}, {"text": "他把笑话隐蔽给大家听。", "explanation": "这里应该用〈讲〉。“隐蔽”指躲起来不让人看见，要把笑话讲给大家听，应说“讲”。"}, {"text": "他在大厅里隐蔽地展示了新产品。", "explanation": "这里应该用〈公开〉。“隐蔽”指不让别人看见，与“展示”让人看见的意思相反，应说“公开地展示”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐蔽", "is_correct": true, "explanation": "正确。“隐蔽着”表示躲藏着，与“静静看着前面的鹿”的伏守情境相合。"}, {"text": "喊叫", "is_correct": false, "explanation": "语义：“喊叫”声音大，与“静静看着”的安静情境相矛盾。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：“欢呼”是高兴地大声叫喊，与猎人屏息观察的情境相矛盾。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”不能直接带“着”表示持续，应说“吃着饭”，而且与“静静看着”的情境不搭。"}], "explanations": {"隐蔽": "正确。“隐蔽着”表示躲藏着，与“静静看着前面的鹿”的伏守情境相合。", "喊叫": "语义：“喊叫”声音大，与“静静看着”的安静情境相矛盾。", "欢呼": "语义：“欢呼”是高兴地大声叫喊，与猎人屏息观察的情境相矛盾。", "吃饭": "搭配：“吃饭”不能直接带“着”表示持续，应说“吃着饭”，而且与“静静看着”的情境不搭。"}, "sentence_index": 6, "correct_answer": "隐蔽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们隐蔽了一整夜，天亮才下班。", "explanation": "这里应该用〈工作〉。“隐蔽”指躲藏，不表示持续劳作，说“一整夜”的劳动要用“工作”。"}, {"text": "雨隐蔽了一整夜，天亮才停。", "explanation": "这里应该用〈下〉。“隐蔽”指躲藏、不让人看见，不能用来形容雨；应说“雨下了一整夜，天亮才停”。"}, {"text": "这座雕像很隐蔽，老远就能看到。", "explanation": "这里应该用〈显眼〉。“隐蔽”指不让人看见或发现，形容雕像老远就能看到要用“显眼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们隐蔽在树林里着。", "corrected_sentence": "他们隐蔽在树林里了。", "error_description": "表示动作已经完成的句末语气要用“了”，写作“隐蔽在树林里了”；这里误用了“着”，“着”表示持续的状态，不能放在处所短语后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猎人隐蔽草丛里，静静看着前面的鹿。", "corrected_sentence": "猎人隐蔽在草丛里，静静看着前面的鹿。", "error_description": "“隐蔽”后面接处所时要用“在”引出，应写作“隐蔽在草丛里”；漏掉“在”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6759885b-1e84-47a8-ae4a-cb1d358da159') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
