INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26274, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面以下的水。", "primary_collocate": null, "pronunciation": "dì xià shuǐ", "ipa": "ti˥˩ ɕja˥˩ ʂweɪ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这口井里的水是地下水。", "target_word": "地下水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们挖了很深的井，找到了地下水。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地下水看不见，要挖井才能用。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠里的地下水特别珍贵。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的地下水很干净，可以直接喝。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天天气热，地下水摸起来很凉。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些地方的地下水又苦又咸。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山脚下的地下水很多。", "target_word": "地下水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨以后，地下水会多一些。", "target_word": "地下水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们打算用地下水种菜。", "target_word": "地下水", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "地下水位", "label": "复合"}, {"form": "地下水资源", "label": "复合"}], "register": "中性", "sense_fingerprint": "地下水：地面以下的水，要挖井才能取用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884de977-ec2d-4491-87db-758e8e0f7dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地下水", "is_correct": true, "explanation": "正确：从井里取出的水就是地下水，符合句意。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是固态，井里取出的是液态水，与句意不符。"}, {"text": "汽水", "is_correct": false, "explanation": "搭配：“汽水”指加了气体的饮料，不是从井里取来的水。"}, {"text": "蒸汽", "is_correct": false, "explanation": "语义：蒸汽是气体，不能从井里取出，与“井里的水”不符。"}], "explanations": {"地下水": "正确：从井里取出的水就是地下水，符合句意。", "冰": "语义：冰是固态，井里取出的是液态水，与句意不符。", "汽水": "搭配：“汽水”指加了气体的饮料，不是从井里取来的水。", "蒸汽": "语义：蒸汽是气体，不能从井里取出，与“井里的水”不符。"}, "sentence_index": 0, "correct_answer": "地下水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们吃了一碗地下水。", "explanation": "这里应该用〈喝〉。水是用来喝的，不能说“吃”。"}, {"text": "我们喝了一根地下水。", "explanation": "这里应该用〈杯〉。水用杯、碗、瓶等计量，“根”用于细长的东西，不用于水。"}, {"text": "地下水会从天上落下来。", "explanation": "这里应该用〈雨水〉。从天上落下的是雨水，地下水埋在地下，不会从天上落下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地下水", "is_correct": true, "explanation": "正确：“有些地方的地下水又苦又咸”，指埋在地下的水带有苦咸味，符合语境。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水一般不苦不咸，与“又苦又咸”的描述不符。"}, {"text": "露水", "is_correct": false, "explanation": "搭配：“露水”多用清凉、清新来形容，不说“又苦又咸”。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是可以描述苦咸味的水，句意不通。"}], "explanations": {"地下水": "正确：“有些地方的地下水又苦又咸”，指埋在地下的水带有苦咸味，符合语境。", "雨水": "语义：雨水一般不苦不咸，与“又苦又咸”的描述不符。", "露水": "搭配：“露水”多用清凉、清新来形容，不说“又苦又咸”。", "汽油": "语义：汽油是燃料，不是可以描述苦咸味的水，句意不通。"}, "sentence_index": 6, "correct_answer": "地下水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的地下水很潮湿。", "explanation": "这里应该用〈地下室〉。“地下水”是水，不能指房间，形容房间潮湿要用“地下室”。"}, {"text": "地下水每五分钟来一班。", "explanation": "这里应该用〈地下铁〉。班次和列车属于地下铁，“地下水”不是交通工具。"}, {"text": "地下水停满了车。", "explanation": "这里应该用〈地下停车场〉。停满车的是停车场，“地下水”不能指停车场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村的人平时都喝一条地下水。", "corrected_sentence": "这个村的人平时都喝地下水。", "error_description": "“地下水”是不可数的水，不能用量词“条”，应说“喝地下水”，不说“喝一条地下水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多地方的地下水们都很苦。", "corrected_sentence": "很多地方的地下水都很苦。", "error_description": "“地下水”是不可数的水，不能加“们”表示复数，应说“地下水都很苦”，不说“地下水们都很苦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
