INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26282, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "刚刚推出的新东西。", "primary_collocate": null, "pronunciation": "xīn pǐn", "ipa": "ɕin˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个牌子每个月都有新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新品的包装很漂亮，我想买一个。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员给我们介绍了几样新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂正在做明年的新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这家店的新品很感兴趣。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新品已经到了，你要不要来看看？", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在网上免费送新品给客人试用。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的新品比去年的好用得多。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览会上有很多公司带来了新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都想早点儿试试这款新品。", "target_word": "新品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "款", "label": "量词"}, {"form": "新品发布", "label": "复合"}], "register": "中性", "sense_fingerprint": "刚刚推出的新东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18d875c5-7ca1-4d87-b422-a099d3a3d100') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新品", "is_correct": true, "explanation": "新品指刚推出的新东西，牌子每个月推出新品，语义吻合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是牌子推出的东西，不能说“每个月都有天气”。"}, {"text": "说明书", "is_correct": false, "explanation": "搭配：说明书是附在产品里的，不说牌子“每个月都有说明书”。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人是人，不是牌子推出的东西，与句子语义冲突。"}], "explanations": {"新品": "新品指刚推出的新东西，牌子每个月推出新品，语义吻合。", "天气": "语义：天气不是牌子推出的东西，不能说“每个月都有天气”。", "说明书": "搭配：说明书是附在产品里的，不说牌子“每个月都有说明书”。", "老人": "语义：老人是人，不是牌子推出的东西，与句子语义冲突。"}, "sentence_index": 0, "correct_answer": "新品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部新品的主演是一位刚出道的新人。", "explanation": "这里应该用〈新作〉。新品指商品，不能说影视作品有主演。"}, {"text": "我昨天在店里看到一只新品。", "explanation": "这里应该用〈款〉。“只”用于动物，不能用来数新品。"}, {"text": "妈妈买了一位新品。", "explanation": "这里应该用〈款〉。“位”只用于人，不能用来数商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新品", "is_correct": true, "explanation": "新品是刚推出的东西，免费送给客人试用，语义吻合。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是付款凭证，不能拿来免费给客人试用。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：合同是签订的文件，不说“送合同给客人试用”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾没有试用的价值，与“免费送给客人试用”的含义矛盾。"}], "explanations": {"新品": "新品是刚推出的东西，免费送给客人试用，语义吻合。", "账单": "语义：账单是付款凭证，不能拿来免费给客人试用。", "合同": "搭配：合同是签订的文件，不说“送合同给客人试用”。", "垃圾": "语义：垃圾没有试用的价值，与“免费送给客人试用”的含义矛盾。"}, "sentence_index": 6, "correct_answer": "新品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妹妹是我们家刚出生的新品。", "explanation": "这里应该用〈婴儿〉。“新品”指刚推出的新东西，不能用来指刚出生的人。"}, {"text": "这个池塘里游来一条新品，是条小鱼。", "explanation": "这里应该用〈幼鱼〉。“新品”指刚推出的新东西，不能指鱼。"}, {"text": "这窝新品还在吃奶，特别可爱。", "explanation": "这里应该用〈幼犬〉。“新品”指刚推出的新东西，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我买了一只新品。", "corrected_sentence": "妈妈给我买了一款新品。", "error_description": "量词错误：“新品”是商品，应用量词“款”。错误形式是“一只新品”，“只”只用于动物；正确形式是“一款新品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友们都想先买到这些新品们。", "corrected_sentence": "朋友们都想先买到这些新品。", "error_description": "词尾错误：“们”只用于指人，不能加在“新品”后。错误形式是“新品们”，正确形式是“新品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
