INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉很多人一件事。", "primary_collocate": null, "pronunciation": "fā bù", "ipa": "fa˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "他在网上发布了一个好消息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在班级群里发布了作业。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在朋友圈发布今天的照片。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在网站上发布了招聘信息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旅行的视频发布到了网上。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要随便发布别人的照片。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市发布了明天打折的消息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在群里发布了考试时间。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都会发布一条新消息。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区发布了停水的通知。", "target_word": "发布", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发布了", "label": "体标"}, {"form": "发布过", "label": "体标"}, {"form": "發布", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在网上或群里把消息告诉很多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18d875c5-7ca1-4d87-b422-a099d3a3d100') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发布", "is_correct": true, "explanation": "发布指在网上把消息告诉很多人，与“好消息”搭配通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃消息”。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”的对象是植物，不能说“种消息”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对损坏的物件，不用于消息。"}], "explanations": {"发布": "发布指在网上把消息告诉很多人，与“好消息”搭配通顺。", "吃": "搭配：“吃”的对象是食物，不能说“吃消息”。", "种": "搭配：“种”的对象是植物，不能说“种消息”。", "修理": "语义：“修理”针对损坏的物件，不用于消息。"}, "sentence_index": 0, "correct_answer": "发布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把照片发布给了妈妈。", "explanation": "这里应该用〈分享〉。发布是面向很多人公开，只给一个人看要用“分享”。"}, {"text": "他给我发布了一条消息。", "explanation": "这里应该用〈发送〉。发布是面向很多人，只发给一个人要用“发送”。"}, {"text": "他把新闻发布给了同学。", "explanation": "这里应该用〈转发〉。转发是把别人的内容再传给别人，“发布”指自己首次公开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发布", "is_correct": true, "explanation": "发布指公开告诉大家消息，与“打折的消息”搭配通顺。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌面、玻璃等，不能擦消息。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”针对场所或垃圾，不能打扫消息。"}, {"text": "调节", "is_correct": false, "explanation": "语义：“调节”用于温度、流量等，与消息无关。"}], "explanations": {"发布": "发布指公开告诉大家消息，与“打折的消息”搭配通顺。", "擦": "搭配：“擦”的对象是桌面、玻璃等，不能擦消息。", "打扫": "搭配：“打扫”针对场所或垃圾，不能打扫消息。", "调节": "语义：“调节”用于温度、流量等，与消息无关。"}, "sentence_index": 6, "correct_answer": "发布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在网上发布了一片树叶。", "explanation": "这里应该用〈展示〉。“发布”的对象应是消息、照片等信息，“树叶”是实物，不能在网上发布。"}, {"text": "我在群里发布了一碗饭。", "explanation": "这里应该用〈分享〉。“发布”的对象应是消息、照片等信息，“饭”是实物，不能在群里发布。"}, {"text": "他在班级群里发布了一座桥。", "explanation": "这里应该用〈建造〉。“发布”的对象应是消息、照片等信息，“桥”是建筑，不能在群里发布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天把视频发布。", "corrected_sentence": "他昨天把视频发布了。", "error_description": "补语缺失：“把”字句中动词“发布”后需要“了”等成分。错误形式是“把视频发布”，正确形式是“把视频发布了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区昨天发布着一则停水消息。", "corrected_sentence": "社区昨天发布了一则停水消息。", "error_description": "体标错误：“着”表示进行中，不能用于已完成的昨天事件。错误形式是“发布着”，正确形式是“发布了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
