INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以用很久不坏的东西。", "primary_collocate": null, "pronunciation": "nài yòng pǐn", "ipa": "naɪ˥˩ jʊŋ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "爷爷喜欢买耐用品，不喜欢买便宜的东西。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张木桌是耐用品，用了二十年还很好。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚时，他们买了不少耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起塑料杯，不锈钢杯是耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买耐用品，不想总是换新的。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的耐用品不容易坏，可以用很多年。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的耐用品都放在二楼。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送我的这块手表是耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店里卖的锅和碗都是耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鞋很结实，算得上是耐用品。", "target_word": "耐用品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "结实、能用很多年的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b1d809e-c850-4319-8646-b0bdde226862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耐用品", "is_correct": true, "explanation": "“耐用品”指可以用很久不坏的东西，与“爷爷喜欢买”的语境相符。"}, {"text": "便宜货", "is_correct": false, "explanation": "语义：“便宜货”与后半句“不喜欢买便宜的东西”矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“买”不能搭配“空气”，买空气不成立。"}, {"text": "廉价品", "is_correct": false, "explanation": "语义：“廉价品”与后半句“不喜欢买便宜的东西”矛盾。"}], "explanations": {"耐用品": "“耐用品”指可以用很久不坏的东西，与“爷爷喜欢买”的语境相符。", "便宜货": "语义：“便宜货”与后半句“不喜欢买便宜的东西”矛盾。", "空气": "搭配：“买”不能搭配“空气”，买空气不成立。", "廉价品": "语义：“廉价品”与后半句“不喜欢买便宜的东西”矛盾。"}, "sentence_index": 0, "correct_answer": "耐用品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都买很多耐用品，比如牛奶和面包。", "explanation": "这里应该用〈消耗品〉。牛奶和面包吃完就没了，属于消耗品；耐用品指能用很久不坏的东西。"}, {"text": "这家店的耐用品用过就扔，很方便。", "explanation": "这里应该用〈一次性用品〉。用过就扔的东西是一次性用品，与“耐用”的意思相反。"}, {"text": "墨盒和打印纸都是耐用品，要经常买。", "explanation": "这里应该用〈易耗品〉。墨盒和打印纸用得快，需要不断补充，属于易耗品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耐用品", "is_correct": true, "explanation": "“耐用品”指可以长期使用的物品，放在商店里的二楼，句意通顺。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：树木不能像商品一样“放在商店二楼”陈列，与“商店里的”搭配不当。"}, {"text": "新闻", "is_correct": false, "explanation": "语义：新闻不是可以摆放在商店楼层里的东西。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气无法摆放在商店里，与“都放在二楼”矛盾。"}], "explanations": {"耐用品": "“耐用品”指可以长期使用的物品，放在商店里的二楼，句意通顺。", "树木": "搭配：树木不能像商品一样“放在商店二楼”陈列，与“商店里的”搭配不当。", "新闻": "语义：新闻不是可以摆放在商店楼层里的东西。", "天气": "语义：天气无法摆放在商店里，与“都放在二楼”矛盾。"}, "sentence_index": 6, "correct_answer": "耐用品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店卖的耐用品都是当天新鲜的，每天进货。", "explanation": "这里应该用〈蔬菜〉。蔬菜才会当天新鲜、每天进货；“耐用品”指能长期使用、不易损坏的东西，不能用“新鲜”来形容。"}, {"text": "这些耐用品吃完就没了，要天天买。", "explanation": "这里应该用〈食品〉。食品吃完就没了，要天天买；“耐用品”指能长期使用、不易损坏的东西，不会吃完。"}, {"text": "这些耐用品都是学生用的，用得很快。", "explanation": "这里应该用〈文具〉。文具用得快，要经常买；“耐用品”指能长期使用、不易损坏的东西，两者意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子是一张耐用品，用了很多年。", "corrected_sentence": "这把椅子是一件耐用品，用了很多年。", "error_description": "量词错误：“耐用品”是泛指物品的名词，“张”用于平面的东西，应用“件”：应说“一件耐用品”，不说“一张耐用品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些耐用品们都很结实。", "corrected_sentence": "这些耐用品都很结实。", "error_description": "词尾错误：“们”不能加在“耐用品”这类物品名词后，应写作“耐用品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
