INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26292, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "卖东西并让更多人知道。", "primary_collocate": null, "pronunciation": "yíng xiāo", "ipa": "iŋ˧˥ ɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "他们用短视频营销新产品。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店在网上营销自己的茶叶。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民通过直播营销苹果。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想办法营销自己做的蛋糕。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在营销一种新牛奶。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们很会营销，东西卖得很快。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该怎么营销这本书呢？", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请了明星来营销这款手机。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在社交软件上营销这款新饮料。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她靠营销自己的画赚了不少钱。", "target_word": "营销", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "营销了", "label": "体标"}, {"form": "营销过", "label": "体标"}, {"form": "營銷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "宣传并出售东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18d875c5-7ca1-4d87-b422-a099d3a3d100') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "营销", "is_correct": true, "explanation": "正确。“用短视频……新产品”表示借短视频推广并卖出产品，符合动词义。"}, {"text": "生产", "is_correct": false, "explanation": "语义：短视频是传播手段，不能用来“生产”产品。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：“维修”针对已有故障的器械，不用于推广新产品。"}, {"text": "吸引", "is_correct": false, "explanation": "搭配：“吸引”的对象是人或注意力，不说“吸引新产品”。"}], "explanations": {"营销": "正确。“用短视频……新产品”表示借短视频推广并卖出产品，符合动词义。", "生产": "语义：短视频是传播手段，不能用来“生产”产品。", "维修": "搭配：“维修”针对已有故障的器械，不用于推广新产品。", "吸引": "搭配：“吸引”的对象是人或注意力，不说“吸引新产品”。"}, "sentence_index": 0, "correct_answer": "营销"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小王向老板营销了他的弟弟。", "explanation": "这里应该用〈推荐〉。营销的对象是商品，不能用于人；向老板推荐人才要用推荐。"}, {"text": "小王想办法营销他的成绩。", "explanation": "这里应该用〈展示〉。营销是向市场推广商品，成绩不能拿来推广；想让别人看到成绩要用展示。"}, {"text": "老师营销了那个努力的学生。", "explanation": "这里应该用〈表扬〉。营销指向市场推广商品，不能用于对学生的评价；表扬人要用表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营销", "is_correct": true, "explanation": "正确。“怎么……这本书”问如何推广、卖出这本书，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：书不能“煮”，与句意不合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能用于书。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”一般对应歌曲，不说“唱这本书”来指推广。"}], "explanations": {"营销": "正确。“怎么……这本书”问如何推广、卖出这本书，符合句意。", "煮": "语义：书不能“煮”，与句意不合。", "吃": "语义：“吃”的对象是食物，不能用于书。", "唱": "搭配：“唱”一般对应歌曲，不说“唱这本书”来指推广。"}, "sentence_index": 6, "correct_answer": "营销"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她靠营销客户赚了不少钱。", "explanation": "这里应该用〈介绍〉。营销的对象是商品，不能用于人；靠介绍客户赚钱要用介绍。"}, {"text": "她很看重营销她的感情。", "explanation": "这里应该用〈表达〉。营销是向市场推广商品，感情不能拿去推广；表达感情要用表达。"}, {"text": "她靠营销学员赚了不少钱。", "explanation": "这里应该用〈培训〉。营销的对象是商品，不能用于学员；靠培训学员赚钱要用培训。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们曾经营销着这款饮料。", "corrected_sentence": "他们曾经营销过这款饮料。", "error_description": "错误：“营销”后用了“着”，表示动作持续，与“曾经”指已完成的经历不符。正确：应说“营销过这款饮料”，“过”紧跟动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店营销了很成功。", "corrected_sentence": "这家店营销得很成功。", "error_description": "补语标记错误：引出补语应用“得”，不能用“了”，应说“营销得很成功”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
