INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "衣服等物品的统称。", "primary_collocate": null, "pronunciation": "yī wù", "ipa": "i˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们的衣物都挂在门后。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，要多带一些衣物。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣物湿了，应该马上换。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，她在箱子里放好了衣物。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧衣物还很干净，可以送人。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把我的衣物咬坏了。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家洗衣店专门洗大件的衣物。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住酒店时，别把衣物忘在房间里。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上很冷，你要穿暖和的衣物。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行李里只有几件衣物和一本书。", "target_word": "衣物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "衣物：衣服等物品的统称，可指穿用、收纳或洗涤的衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b1d809e-c850-4319-8646-b0bdde226862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26294, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "衣物", "is_correct": true, "explanation": "正确。“衣物”指衣服等物品。"}, {"text": "遗物", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是死者留下的物品。"}, {"text": "异物", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是混入其中的外来物体。"}, {"text": "义务", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是应尽的责任。"}], "explanations": {"衣物": "正确。“衣物”指衣服等物品。", "遗物": "yí（第二声）与 yī（第一声）声调不同，意思是死者留下的物品。", "异物": "yì（第四声）与 yī（第一声）声调不同，意思是混入其中的外来物体。", "义务": "yì（第四声）与 yī（第一声）声调不同，意思是应尽的责任。"}, "sentence_index": null, "correct_answer": "衣物"}, "level_3": {"options": [{"text": "衣物", "is_correct": true, "explanation": "正确。“衣物”可以挂在门后，与“挂”搭配。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“挂”用于衣物等可挂的物品，“饭菜”不能挂在门后。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是矿物，不是可以挂起来的东西，与整句情景不符。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”是食物，与“孩子们的……挂在门后”的情景不符。"}], "explanations": {"衣物": "正确。“衣物”可以挂在门后，与“挂”搭配。", "饭菜": "搭配：“挂”用于衣物等可挂的物品，“饭菜”不能挂在门后。", "石头": "语义：“石头”是矿物，不是可以挂起来的东西，与整句情景不符。", "水果": "语义：“水果”是食物，与“孩子们的……挂在门后”的情景不符。"}, "sentence_index": 0, "correct_answer": "衣物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她买了一台衣物。", "explanation": "这里应该用〈件〉。“台”用于机器、设备，衣物应用“件”或“套”。"}, {"text": "我买了一扇衣物。", "explanation": "这里应该用〈件〉。“扇”用于门窗，衣物应用“件”或“套”。"}, {"text": "我买了一条衣物。", "explanation": "这里应该用〈件〉。“条”用于细长的东西，衣物是集合性的，应用“件”或“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衣物", "is_correct": true, "explanation": "正确。“衣物”是洗衣店洗的大件织物，与“洗”相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：洗衣店洗的是衣物等织物，不洗食物。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：“洗”不用于书本，“专门洗大件的书本”搭配不当。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：“洗大件的”一般指织物等物品，“木材”不能用“洗”。"}], "explanations": {"衣物": "正确。“衣物”是洗衣店洗的大件织物，与“洗”相符。", "食物": "语义：洗衣店洗的是衣物等织物，不洗食物。", "书本": "搭配：“洗”不用于书本，“专门洗大件的书本”搭配不当。", "木材": "搭配：“洗大件的”一般指织物等物品，“木材”不能用“洗”。"}, "sentence_index": 6, "correct_answer": "衣物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一头衣物。", "explanation": "这里应该用〈件〉。“头”用于牲畜，衣物应用“件”或“套”。"}, {"text": "她买了一面衣物。", "explanation": "这里应该用〈件〉。“面”用于平面的东西，衣物应用“件”或“套”。"}, {"text": "他买了一支衣物。", "explanation": "这里应该用〈件〉。“支”用于细长的棍状物，衣物应用“件”或“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一件新衣物们。", "corrected_sentence": "我买了一件新衣物。", "error_description": "“们”只加在指人的名词或代词后表示复数，“衣物”指物品，不能说“新衣物们”。应为“新衣物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她买了两只衣物。", "corrected_sentence": "她买了两件衣物。", "error_description": "量词“只”不能计量“衣物”，“两只衣物”错，应为“两件衣物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c7bd07-3c06-4956-82a8-f1c7774b7cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26296, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昂贵", "is_correct": true, "explanation": "反义：“昂贵”与“低廉”在价格上相对。"}, {"text": "灵活", "is_correct": false, "explanation": "无反义关系：“灵活”说变化自如，与“低廉”的价格义没有相对的关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "无反义关系：“辽阔”说面积大，与“低廉”没有相对的关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "无反义关系：“陈旧”说东西过时，与“低廉”的价格义不相对。"}], "correct_answer": "昂贵", "explanations": {"昂贵": "反义：“昂贵”与“低廉”在价格上相对。", "灵活": "无反义关系：“灵活”说变化自如，与“低廉”的价格义没有相对的关系。", "辽阔": "无反义关系：“辽阔”说面积大，与“低廉”没有相对的关系。", "陈旧": "无反义关系：“陈旧”说东西过时，与“低廉”的价格义不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26296, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昂贵", "is_correct": true, "explanation": "反义：“昂贵”与“低廉”在价格上相对。"}, {"text": "清脆", "is_correct": false, "explanation": "无反义关系：“清脆”形容声音或口感，与“低廉”没有相对的关系。"}, {"text": "丰盛", "is_correct": false, "explanation": "无反义关系：“丰盛”说数量多、菜式全，与“低廉”的价格义没有相对的关系。"}, {"text": "粗犷", "is_correct": false, "explanation": "无反义关系：“粗犷”形容风格豪放，与“低廉”没有相对的关系。"}], "correct_answer": "昂贵", "explanations": {"昂贵": "反义：“昂贵”与“低廉”在价格上相对。", "清脆": "无反义关系：“清脆”形容声音或口感，与“低廉”没有相对的关系。", "丰盛": "无反义关系：“丰盛”说数量多、菜式全，与“低廉”的价格义没有相对的关系。", "粗犷": "无反义关系：“粗犷”形容风格豪放，与“低廉”没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26296, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "价格低，很便宜。", "primary_collocate": null, "pronunciation": "dī lián", "ipa": "ti˥ lian˧˥", "syllable_count": 2, "sentences": [{"text": "这里的蔬菜价格低廉，每天都有人来买。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开了一家小店，卖低廉的日用品。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在郊区的房租低廉，但上班比较远。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机价格低廉，老人和孩子都能用。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的水果价格特别低廉，我一次买了很多。", "target_word": "低廉", "complexity_tier": "T3", "furigana": "xià tiān de shuǐ guǒ jià gé tè bié dī lián, wǒ yí cì mǎi le hěn duō.", "sentence_source": "generated"}, {"text": "这条街上的饭菜价格低廉又好吃。", "target_word": "低廉", "complexity_tier": "T3", "furigana": "zhè tiáo jiē shàng de fàn cài jià gé dī lián yòu hǎo chī.", "sentence_source": "generated"}, {"text": "低廉的机票让更多人有机会去旅行。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生食堂的饭菜价格低廉，味道也不错。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为人工低廉，这家工厂的产品很有竞争力。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家商店的价格低廉，每天都挤满了人。", "target_word": "低廉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "低廉：东西的价格低，花钱少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23eec3b-6256-4fda-81a7-c349d8b21264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低廉", "is_correct": true, "explanation": "低廉：价格低，与“每天都有人来买”相合。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”形容工艺或物品做得细巧，不能修饰“价格”。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间大，不能说价格宽敞。"}, {"text": "低劣", "is_correct": false, "explanation": "语义：“低劣”指质量差，与“每天都有人来买”的价格义不合。"}], "explanations": {"低廉": "低廉：价格低，与“每天都有人来买”相合。", "精致": "搭配：“精致”形容工艺或物品做得细巧，不能修饰“价格”。", "宽敞": "搭配：“宽敞”形容空间大，不能说价格宽敞。", "低劣": "语义：“低劣”指质量差，与“每天都有人来买”的价格义不合。"}, "sentence_index": 0, "correct_answer": "低廉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电视剧的内容很低廉，孩子不宜观看。", "explanation": "这里应该用〈低俗〉。低廉只说价格，形容内容品位差要用低俗。"}, {"text": "他的品格很低廉，从不贪小利。", "explanation": "这里应该用〈高尚〉。低廉只用于价格、费用，形容人的品格要用高尚。"}, {"text": "他对爱情的态度很低廉，说换就换。", "explanation": "这里应该用〈廉价〉。低廉只说价格，形容感情、态度的廉价要用廉价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低廉", "is_correct": true, "explanation": "低廉：价格低，与“让更多人有机会去旅行”的结果相合。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”说价格高，与“让更多人有机会去旅行”的结果相反。"}, {"text": "迟缓", "is_correct": false, "explanation": "搭配：“迟缓”形容动作或反应慢，不能修饰“机票”。"}, {"text": "凌乱", "is_correct": false, "explanation": "搭配：“凌乱”形容东西杂乱，不能用来修饰“机票”。"}], "explanations": {"低廉": "低廉：价格低，与“让更多人有机会去旅行”的结果相合。", "昂贵": "语义：“昂贵”说价格高，与“让更多人有机会去旅行”的结果相反。", "迟缓": "搭配：“迟缓”形容动作或反应慢，不能修饰“机票”。", "凌乱": "搭配：“凌乱”形容东西杂乱，不能用来修饰“机票”。"}, "sentence_index": 6, "correct_answer": "低廉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月的收入很低廉，只够付房租。", "explanation": "这里应该用〈微薄〉。低廉说价格、费用，说收入少要用微薄。"}, {"text": "这批玩具质量很低廉，孩子玩两天就坏了。", "explanation": "这里应该用〈低劣〉。低廉只说价格，说质量差要用低劣。"}, {"text": "他们家境很低廉，供不起孩子上学。", "explanation": "这里应该用〈清贫〉。低廉说价格，说家里经济拮据要用清贫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一件低廉地雨衣，天气不好时穿。", "corrected_sentence": "他买了一件低廉的雨衣，天气不好时穿。", "error_description": "错误：“低廉”修饰名词“雨衣”时应用“的”，写成“地”是错的。正确：“低廉的雨衣”。“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种面包的价格低廉很，学生们经常买。", "corrected_sentence": "这种面包的价格低廉得很，学生们经常买。", "error_description": "错误：程度补语前漏掉了“得”，“低廉很”不成立。正确：“低廉得很”，“得”紧跟在形容词后面，引出程度补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
