INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26298, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "让人感觉突然、强烈。", "primary_collocate": null, "pronunciation": "cì jī", "ipa": "tsʰɨ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "坐过山车真刺激。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场足球比赛非常刺激。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢玩刺激的游戏。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影太刺激了，我不敢看。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳伞是一项很刺激的运动。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛最后一分钟特别刺激。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上一个人走山路，感觉很刺激。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一份更刺激的工作。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们觉得这个故事很刺激。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天看了一部很刺激的电影。", "target_word": "刺激", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刺激性", "label": "复合"}], "register": "口语", "sense_fingerprint": "让人觉得突然、强烈、很兴奋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18d875c5-7ca1-4d87-b422-a099d3a3d100') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刺激", "is_correct": true, "explanation": "正确。“真刺激”形容坐过山车的感受强烈、突然，符合句意。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容平和、没有声响，与坐过山车的强烈感受相反。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情或动作柔和，不能形容坐过山车的体验。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人的身形，不能用来形容坐过山车的感觉。"}], "explanations": {"刺激": "正确。“真刺激”形容坐过山车的感受强烈、突然，符合句意。", "安静": "语义：“安静”形容平和、没有声响，与坐过山车的强烈感受相反。", "温柔": "语义：“温柔”形容性情或动作柔和，不能形容坐过山车的体验。", "瘦": "体貌：“瘦”形容人的身形，不能用来形容坐过山车的感觉。"}, "sentence_index": 0, "correct_answer": "刺激"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张床很刺激，我很喜欢。", "explanation": "这里应该用〈舒适〉。刺激形容让人感到突然、强烈的事物，不能用来形容床；形容床舒服要用舒适。"}, {"text": "这盆花很刺激地开了。", "explanation": "这里应该用〈鲜艳〉。刺激形容让人感到突然强烈的事，不用来形容花；形容花颜色鲜明要用鲜艳。"}, {"text": "这间屋子很刺激，大家都很安静。", "explanation": "这里应该用〈安静〉。刺激形容让人感到突然强烈的事，不用来形容屋子；形容屋子环境安静要用安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刺激", "is_correct": true, "explanation": "正确。“感觉很刺激”形容走夜路时的紧张、兴奋感，符合句意。"}, {"text": "红", "is_correct": false, "explanation": "体貌：“红”形容颜色，不能用来描述“感觉”。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能用来形容走山路的感受。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味，“感觉很香”不能指走山路时的体验。"}], "explanations": {"刺激": "正确。“感觉很刺激”形容走夜路时的紧张、兴奋感，符合句意。", "红": "体貌：“红”形容颜色，不能用来描述“感觉”。", "甜": "语义：“甜”指味道，不能用来形容走山路的感受。", "香": "搭配：“香”形容气味，“感觉很香”不能指走山路时的体验。"}, "sentence_index": 6, "correct_answer": "刺激"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆里很刺激，同学们都在读书。", "explanation": "这里应该用〈安静〉。刺激形容让人兴奋或紧张的事，不用于描述图书馆的环境；说环境安静要用安静。"}, {"text": "她的性格很刺激。", "explanation": "这里应该用〈温柔〉。刺激形容事物让人感到强烈的兴奋，不用来描述性格；说性格柔和要用温柔。"}, {"text": "他很刺激地走进了教室。", "explanation": "这里应该用〈快步〉。刺激形容让人感到突然强烈的事，不用来形容走路的样子；形容走得快要用快步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一次很刺激旅行。", "corrected_sentence": "这是一次很刺激的旅行。", "error_description": "错误：漏掉“的”。形容词“刺激”前有“很”修饰、后接名词时，中间要加“的”，应说“很刺激的旅行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很刺激游戏。", "corrected_sentence": "这是一个很刺激的游戏。", "error_description": "漏掉“的”：形容词修饰名词时，中间要加“的”，应说“很刺激的游戏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47c372c-bd0c-4461-804d-876163476ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
