INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西看起来比原来更大。", "primary_collocate": null, "pronunciation": "fàng dà", "ipa": "fɑŋ˥˩ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "这张小照片放大以后，细节看得更清楚。", "target_word": "放大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把地图放大，就能看见小街道。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这页文件放大到两倍再打印。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶眼睛不好，我把书上的字放大了。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个镜头能把远处的鸟放大，看得很清楚。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用电脑把小图放大做海报，结果变模糊了。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "透过水杯看，手指好像放大了。", "target_word": "放大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "设计师把标志放大后，贴在了墙上。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把画放大，挂在了房间里。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请你把投影放大一点，后排看不清。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放大了", "label": "体标"}, {"form": "放大过", "label": "体标"}, {"form": "放大器", "label": "复合"}, {"form": "放大镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "让东西看起来更大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7675ad-35c8-42da-8525-b50edf4a9d77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放大", "is_correct": true, "explanation": "放大：照片放大后，细节便能看得更清楚，符合“让东西看起来更大”的意思。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：照片缩小后细节会变小，“缩小以后细节看得更清楚”与常识不合。"}, {"text": "粘贴", "is_correct": false, "explanation": "搭配：“粘贴”不会使细节变得更清楚，“粘贴以后细节看得更清楚”不成立。"}, {"text": "涂改", "is_correct": false, "explanation": "语义：“涂改”会让内容模糊，与“细节看得更清楚”的语义相反。"}], "explanations": {"放大": "放大：照片放大后，细节便能看得更清楚，符合“让东西看起来更大”的意思。", "缩小": "语义：照片缩小后细节会变小，“缩小以后细节看得更清楚”与常识不合。", "粘贴": "搭配：“粘贴”不会使细节变得更清楚，“粘贴以后细节看得更清楚”不成立。", "涂改": "语义：“涂改”会让内容模糊，与“细节看得更清楚”的语义相反。"}, "sentence_index": 0, "correct_answer": "放大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重放大了三公斤。", "explanation": "这里应该用〈增加〉。放大指使东西看起来更大，体重是数量，应说“增加”。"}, {"text": "我的妹妹最近放大了不少。", "explanation": "这里应该用〈长高〉。放大用于让事物看起来更大，不用于描述人的身体变化。"}, {"text": "这笔钱能让我的生活放大三个月。", "explanation": "这里应该用〈延长〉。放大不表示时间的延续，应说“延长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放大", "is_correct": true, "explanation": "放大：透过水杯看，物体会显得比原来大，所以手指看起来放大了。"}, {"text": "消失", "is_correct": false, "explanation": "语义：手指不会“消失”，透过水杯看到的只是视觉上的变化，与“消失”无关。"}, {"text": "碎", "is_correct": false, "explanation": "搭配：“碎”多用于易碎的物件，不说手指碎了。"}, {"text": "熬", "is_correct": false, "explanation": "搭配：“熬”不能描述手指的外观变化，“手指好像熬了”没有意义。"}], "explanations": {"放大": "放大：透过水杯看，物体会显得比原来大，所以手指看起来放大了。", "消失": "语义：手指不会“消失”，透过水杯看到的只是视觉上的变化，与“消失”无关。", "碎": "搭配：“碎”多用于易碎的物件，不说手指碎了。", "熬": "搭配：“熬”不能描述手指的外观变化，“手指好像熬了”没有意义。"}, "sentence_index": 6, "correct_answer": "放大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期他的成绩放大了不少，老师都很惊讶。", "explanation": "这里应该用〈提高〉。放大用于让东西看起来更大，成绩的进步应说“提高”。"}, {"text": "这个城市的人口放大了一倍，交通越来越挤。", "explanation": "这里应该用〈增长〉。放大用于让东西看起来更大，人口的增加应说“增长”。"}, {"text": "这台机器的运转速度放大了两倍。", "explanation": "这里应该用〈加快〉。放大用于让东西看起来更大，速度的变化应说“加快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张老照片放大很清楚，连人脸都能看见。", "corrected_sentence": "这张老照片放大得很清楚，连人脸都能看见。", "error_description": "“放大”后作程度补语时需用“得”，“放大很清楚”缺少“得”，是错误的，应为“放大得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把这张海报放大得一点，后排的人也能看清。", "corrected_sentence": "把这张海报放大一点，后排的人也能看清。", "error_description": "“放大一点”中，“一点”作数量补语直接接在动词后，不用“得”；“放大得一点”错误，应为“放大一点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
