INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一层又一层，很多层叠在一起。", "primary_collocate": null, "pronunciation": "céng céng", "ipa": "tsʰɤŋ˧˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她把礼物用纸层层包着。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "层层树叶挡住了阳光。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶上飘着层层白云。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上是层层梯田。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着层层厚衣服，还是觉得冷。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "层层海浪拍向岸边。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把饼干用纸层层包好。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口围着层层人群。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点落在层层屋顶上。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剥开洋葱，里面是层层薄皮。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "单字"}, {"form": "層層", "label": "繁体"}, {"form": "层层叠叠", "label": "复合"}], "register": "中性", "sense_fingerprint": "实物一层叠一层，如层层包装、层层梯田、层层海浪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7675ad-35c8-42da-8525-b50edf4a9d77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”描写温度或态度，不能说明把礼物用纸包着的方式。"}, {"text": "层层", "is_correct": true, "explanation": "正确：“层层包着”描述纸一层一层地裹在礼物上，只有“层层”符合。"}, {"text": "高高", "is_correct": false, "explanation": "语义：“高高”指位置很高，不能描述把礼物用纸包着的方式。"}, {"text": "空空", "is_correct": false, "explanation": "搭配：“空空”形容空的样子，不与“包着”搭配。"}], "explanations": {"冰冷": "语义：“冰冷”描写温度或态度，不能说明把礼物用纸包着的方式。", "层层": "正确：“层层包着”描述纸一层一层地裹在礼物上，只有“层层”符合。", "高高": "语义：“高高”指位置很高，不能描述把礼物用纸包着的方式。", "空空": "搭配：“空空”形容空的样子，不与“包着”搭配。"}, "sentence_index": 0, "correct_answer": "层层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "操场上铺着层层跑道。", "explanation": "这里应该用〈平铺〉。层层指一层叠一层的东西，跑道是平面，不能用“层层”。"}, {"text": "我们班有层层同学。", "explanation": "这里应该用〈很多〉。层层强调一层层叠在一起，描述同学人数多时不自然，应说“很多同学”。"}, {"text": "他把玩具层层扔掉了。", "explanation": "这里应该用〈一个一个〉。层层指层叠的样子，不用于一件件扔掉的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”描写温度，饼干不会因此被用纸包好，句意不通。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“包好”的方式。"}, {"text": "层层", "is_correct": true, "explanation": "正确：“层层包好”描述纸一层一层地包裹饼干，只有“层层”符合。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”描写颜色，与“用纸包好”的动作不相关。"}], "explanations": {"滚烫": "语义：“滚烫”描写温度，饼干不会因此被用纸包好，句意不通。", "清脆": "搭配：“清脆”形容声音，不能修饰“包好”的方式。", "层层": "正确：“层层包好”描述纸一层一层地包裹饼干，只有“层层”符合。", "漆黑": "语义：“漆黑”描写颜色，与“用纸包好”的动作不相关。"}, "sentence_index": 6, "correct_answer": "层层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他层层吃了三个包子。", "explanation": "这里应该用〈接连〉。层层描述层叠的形态，不能用来修饰连续吃的动作。"}, {"text": "这块蛋糕有层层甜味。", "explanation": "这里应该用〈浓浓〉。层层描述层叠的形态，不能修饰“甜味”这种味道。"}, {"text": "他层层地笑了起来。", "explanation": "这里应该用〈哈哈〉。“层层”不能描述笑的声音或状态，应说“哈哈地笑了起来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷把红薯用布层裹好。", "corrected_sentence": "爷爷把红薯用布层层裹好。", "error_description": "副词“层层”是重叠形式，修饰动词时不能只用单个“层”，应说“层层裹好”，不能说“层裹好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在山坡上看见层梯田。", "corrected_sentence": "我们在山坡上看见层层梯田。", "error_description": "作定语修饰名词时要说“层层梯田”，不能只用单个“层”直接修饰“梯田”，“层梯田”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26312, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
