INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26318, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把应该自己做的事，说成是别人的事。", "primary_collocate": null, "pronunciation": "tuī wěi", "ipa": "tʰweɪ̯˥ weɪ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他明明负责这件事，却推诿说是同事的工作。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总推诿说不归她管，让别人去做。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板问谁来做报告，小王马上推诿给小李。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是你的任务，别再推诿了。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他明明有时间，却推诿说这件事应该由别人去做。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的事，他总是推诿给妻子。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "轮到他值日，他却推诿说今天不是他。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你负责的工作，不要推诿给别人。", "target_word": "推诿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都推诿着，谁也不愿意先开口。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都别想推诿，名单上写着你的名字。", "target_word": "推诿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推诿了", "label": "体标"}, {"form": "推诿过", "label": "体标"}, {"form": "推诿着", "label": "体标"}, {"form": "推諉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "推诿：动词，把自己该做的事说成别人的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63014f8-71d4-4556-8cb1-49b555969f79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推诿", "is_correct": true, "explanation": "推诿：把自己该做的事说成别人的事，句中指他把负责的事说成同事的。"}, {"text": "承诺", "is_correct": false, "explanation": "语义：“承诺”是答应做某事，与“说是同事的工作”的意思相矛盾。"}, {"text": "赞扬", "is_correct": false, "explanation": "搭配：“赞扬”后不能接“说是……的工作”这类陈述。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是对人的情感，无法引出“说是同事的工作”。"}], "explanations": {"推诿": "推诿：把自己该做的事说成别人的事，句中指他把负责的事说成同事的。", "承诺": "语义：“承诺”是答应做某事，与“说是同事的工作”的意思相矛盾。", "赞扬": "搭配：“赞扬”后不能接“说是……的工作”这类陈述。", "感谢": "语义：“感谢”是对人的情感，无法引出“说是同事的工作”。"}, "sentence_index": 0, "correct_answer": "推诿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他推诿了老板的好意，说自己要陪家人。", "explanation": "这里应该用〈推辞〉。推诿指把该做的事说成别人的，拒绝好意要用推辞。"}, {"text": "我推诿你去试试这家餐厅。", "explanation": "这里应该用〈推荐〉。推诿指把该做的事说成别人的，向别人介绍好去处要用推荐。"}, {"text": "这项改革正在稳步推诿。", "explanation": "这里应该用〈推进〉。推诿指把该做的事说成别人的，事情逐步前进要用推进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推诿", "is_correct": true, "explanation": "推诿：把自己该做的事说成别人的事，句中指他把值日推给别人。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：“欢呼”是高兴地喊叫，不能引出“说今天不是他”这样的陈述。"}, {"text": "答应", "is_correct": false, "explanation": "语义：“答应”是应承做某事，与“说今天不是他”的意思相矛盾。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”不能引出“说今天不是他”这类陈述。"}], "explanations": {"推诿": "推诿：把自己该做的事说成别人的事，句中指他把值日推给别人。", "欢呼": "语义：“欢呼”是高兴地喊叫，不能引出“说今天不是他”这样的陈述。", "答应": "语义：“答应”是应承做某事，与“说今天不是他”的意思相矛盾。", "祝贺": "搭配：“祝贺”不能引出“说今天不是他”这类陈述。"}, "sentence_index": 6, "correct_answer": "推诿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在认真推诿这首诗的用词。", "explanation": "这里应该用〈推敲〉。推诿指把该做的事说成别人的，推敲文字要用推敲。"}, {"text": "他在街上向路人推诿一种新的牛奶。", "explanation": "这里应该用〈推销〉。推诿指把该做的事说成别人的，向路人卖商品要用推销。"}, {"text": "他一把推诿开了挡路的人。", "explanation": "这里应该用〈推开〉。推诿指把该做的事说成别人的，不能指用力推人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告是我负责的，我不会推诿别人。", "corrected_sentence": "这份报告是我负责的，我不会推诿给别人。", "error_description": "漏掉了“给”：“推诿”后面要接“给”，说“推诿给别人”，不能直接说“推诿别人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常把难题推诿了给同事。", "corrected_sentence": "他常把难题推诿给了同事。", "error_description": "“了”的位置错误：“了”应放在“给”后面，说“推诿给了同事”，不说“推诿了给同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
