INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把锁着的东西打开。", "primary_collocate": null, "pronunciation": "pò jiě", "ipa": "pʰwo˥˩ tɕje˨˩˦", "syllable_count": 2, "sentences": [{"text": "小偷破解了门锁，进了屋。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锁很旧，一分钟就破解了。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察破解保险柜的锁，拿出了文件。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想破解自行车锁，可是没有成功。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用铁丝破解了箱子上的锁。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门锁很新，小偷破解不了。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅正在破解老保险箱的锁。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把旧挂锁生锈了，他花了半小时才破解。", "target_word": "破解", "complexity_tier": "T3", "furigana": "zhè bǎ jiù guàsuǒ shēngxiù le, tā huā le bàn xiǎoshí cái pòjiě.", "sentence_source": "generated"}, {"text": "他破解过很多种锁。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用工具破解了仓库的锁。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破解了", "label": "完成体"}, {"form": "破解过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不用钥匙把锁打开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0f4af5-86fa-4104-a89d-57a274fcc82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "破解", "is_correct": true, "explanation": "“破解”表示不用钥匙打开锁，与“进了屋”的结果相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指把坏的东西修好，与“进了屋”的结果不符，句意不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏美好的事物，不能用来描写小偷对门锁的行为。"}, {"text": "照料", "is_correct": false, "explanation": "语义：“照料”指照顾人或植物，不能用于门锁，句意不通。"}], "explanations": {"破解": "“破解”表示不用钥匙打开锁，与“进了屋”的结果相符。", "修理": "语义：“修理”指把坏的东西修好，与“进了屋”的结果不符，句意不通。", "欣赏": "语义：“欣赏”指赞赏美好的事物，不能用来描写小偷对门锁的行为。", "照料": "语义：“照料”指照顾人或植物，不能用于门锁，句意不通。"}, "sentence_index": 0, "correct_answer": "破解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用钥匙破解了大门。", "explanation": "这里应该用〈打开〉。“破解”指不用钥匙、用非正常方式打开锁，既然有钥匙，就应说“打开”。"}, {"text": "消防员破解了被困的孩子。", "explanation": "这里应该用〈解救〉。“破解”的对象是锁或谜题，不能用于人，救人应说“解救”。"}, {"text": "他花了十分钟才破解了那个绳结。", "explanation": "这里应该用〈解开〉。“解开”用于绳结、扣子等打结或缠绕的东西，“破解”用于锁和谜题，不能用于绳结。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破解", "is_correct": true, "explanation": "“破解”表示打开被锁住的东西，与“老保险箱的锁”搭配，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱锁”。"}, {"text": "支持", "is_correct": false, "explanation": "配价：“支持”需要以人、观点等为对象，不能以保险箱的锁为对象。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆贺别人的喜事，与保险箱的锁无关，句意不通。"}], "explanations": {"破解": "“破解”表示打开被锁住的东西，与“老保险箱的锁”搭配，符合句意。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱锁”。", "支持": "配价：“支持”需要以人、观点等为对象，不能以保险箱的锁为对象。", "祝贺": "语义：“祝贺”表示庆贺别人的喜事，与保险箱的锁无关，句意不通。"}, "sentence_index": 6, "correct_answer": "破解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵终于破解了这座城池。", "explanation": "这里应该用〈攻克〉。“攻克”指攻下城池、堡垒，“破解”用于需要打开或解开的锁、谜题。"}, {"text": "他用力破解了瓶盖。", "explanation": "这里应该用〈拧开〉。“拧开”指转动后打开瓶盖等，“破解”指用非正常方式打开锁或解开谜题。"}, {"text": "工人破解了这堵旧围墙。", "explanation": "这里应该用〈拆除〉。“拆除”指拆掉建筑物，“破解”用于锁或谜题，不能用于墙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小偷半夜把旧锁破解。", "corrected_sentence": "小偷半夜把旧锁破解了。", "error_description": "体标记缺失：“把”字句中动词后须带“了”、补语等成分，“小偷半夜把旧锁破解”缺少“了”，句子不完整。正确说法是“小偷半夜把旧锁破解了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人曾经破解了过这把旧锁。", "corrected_sentence": "工人曾经破解过这把旧锁。", "error_description": "体貌错误：“过”表示经历，不能与“了”同时用在同一个动词后。正确应为“破解过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26328, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "亏损与利润相对，指卖东西时收入抵不上成本、亏了钱。"}, {"text": "租金", "is_correct": false, "explanation": "租金是租用场地或物品付的钱，与利润没有反义关系。"}, {"text": "书桌", "is_correct": false, "explanation": "书桌是家具，与利润没有任何反义或近义关系。"}, {"text": "水杯", "is_correct": false, "explanation": "水杯是盛水的器具，与利润没有任何反义或近义关系。"}], "correct_answer": "亏损", "explanations": {"亏损": "亏损与利润相对，指卖东西时收入抵不上成本、亏了钱。", "租金": "租金是租用场地或物品付的钱，与利润没有反义关系。", "书桌": "书桌是家具，与利润没有任何反义或近义关系。", "水杯": "水杯是盛水的器具，与利润没有任何反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26328, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏损", "is_correct": true, "explanation": "亏损与利润相对，指经营收入抵不上成本、亏了钱。"}, {"text": "包裹", "is_correct": false, "explanation": "包裹是包扎好的物品，与利润没有任何反义或近义关系。"}, {"text": "钥匙", "is_correct": false, "explanation": "钥匙是开锁的工具，与利润没有任何反义或近义关系。"}, {"text": "课本", "is_correct": false, "explanation": "课本是学习用的书，与利润没有任何反义或近义关系。"}], "correct_answer": "亏损", "explanations": {"亏损": "亏损与利润相对，指经营收入抵不上成本、亏了钱。", "包裹": "包裹是包扎好的物品，与利润没有任何反义或近义关系。", "钥匙": "钥匙是开锁的工具，与利润没有任何反义或近义关系。", "课本": "课本是学习用的书，与利润没有任何反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公司卖掉东西后，去掉花的钱，剩下的就是利润。", "primary_collocate": null, "pronunciation": "lì rùn", "ipa": "li˥˩ ʐwən˥˩", "syllable_count": 2, "sentences": [{"text": "小店卖一杯茶，利润只有两块钱。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这个月的利润不错。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖东西不只看价格，也要看利润。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成本太高，我们几乎没有利润。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔生意的利润很小。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把赚到的利润都存进了银行。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包店每天的利润大约有三百元。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东西卖得多，利润就会多一些。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想用今年的利润开一家新店。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折以后，我们的利润变少了。", "target_word": "利润", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "净利润", "label": "复合"}, {"form": "利潤", "label": "繁体"}], "register": "通用", "sense_fingerprint": "卖掉东西后去掉花的钱剩下的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63014f8-71d4-4556-8cb1-49b555969f79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "利润", "is_correct": true, "explanation": "利润是卖东西后扣除花费剩下的钱，“只有两块钱”搭配利润语义通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：茶的卖价与年龄无关，“年龄只有两块钱”说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：一杯茶的利润不可能指手机，整句语义不通。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“只有……块钱”搭配价格、利润、成本，不搭配“口味”。"}], "explanations": {"利润": "利润是卖东西后扣除花费剩下的钱，“只有两块钱”搭配利润语义通顺。", "年龄": "语义：茶的卖价与年龄无关，“年龄只有两块钱”说不通。", "手机": "语义：一杯茶的利润不可能指手机，整句语义不通。", "口味": "搭配：“只有……块钱”搭配价格、利润、成本，不搭配“口味”。"}, "sentence_index": 0, "correct_answer": "利润"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他按时向银行归还了利润。", "explanation": "这里应该用〈贷款〉。归还的是借来的钱，利润是卖东西后剩下的钱，不能拿来还银行。"}, {"text": "老板给员工涨了一次利润。", "explanation": "这里应该用〈薪水〉。涨的是薪水，利润不能用来涨给员工。"}, {"text": "这家店赚了一根利润。", "explanation": "这里应该用〈笔〉。利润用“笔”计量，“根”用于细长的东西，如绳子、棍子，不能用于利润。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利润", "is_correct": true, "explanation": "利润是经营后剩下的钱，面包店每天的利润大约三百元，语义通顺。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人的身体状况，不能说“大约有三百元”。"}, {"text": "门口", "is_correct": false, "explanation": "语义：门口是地点，不能用“大约有三百元”来描述。"}, {"text": "工号", "is_correct": false, "explanation": "搭配：“大约有……元”搭配金额类名词，不搭配“工号”。"}], "explanations": {"利润": "利润是经营后剩下的钱，面包店每天的利润大约三百元，语义通顺。", "体温": "语义：体温是人的身体状况，不能说“大约有三百元”。", "门口": "语义：门口是地点，不能用“大约有三百元”来描述。", "工号": "搭配：“大约有……元”搭配金额类名词，不搭配“工号”。"}, "sentence_index": 6, "correct_answer": "利润"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们店每个月要向房东交利润。", "explanation": "这里应该用〈房租〉。交给房东的是房租，利润是卖东西后剩下的钱，不能交给房东。"}, {"text": "店家要求顾客先交利润。", "explanation": "这里应该用〈押金〉。顾客先交的是押金，利润是卖完后剩下的钱，不能预先交。"}, {"text": "这次事故，我们要赔偿利润。", "explanation": "这里应该用〈损失〉。赔偿的是损失，利润是剩下的钱，不能拿来赔偿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我们赚了一只利润。", "corrected_sentence": "这个月我们赚了一笔利润。", "error_description": "量词错误：利润用“笔”计量。“只”多用于动物，写成“只”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店每个月都有一条稳定的利润。", "corrected_sentence": "这家店每个月都有一笔稳定的利润。", "error_description": "量词错误：利润用“笔”计量。“条”用于细长的东西，不能用于利润。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
