INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府定下的保护环境的规则。", "primary_collocate": null, "pronunciation": "huán jìng biāo zhǔn", "ipa": "xwan˧˥ tɕiŋ˥˩ pjɑʊ˥ ʈʂwən˨˩˦", "syllable_count": 4, "sentences": [{"text": "政府给工厂定了新的环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂要按环境标准处理脏水。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个环境标准是去年定下来的。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的垃圾处理符合环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气不好，是因为没有遵守环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境标准越严，空气就越干净。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座新工厂达到了环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了国家的环境标准。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境标准太低，河水就容易变脏。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的环境标准比我们的高。", "target_word": "环境标准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "環境標準", "label": "繁体"}], "register": "通用", "sense_fingerprint": "政府定下的保护环境的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63014f8-71d4-4556-8cb1-49b555969f79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境标准", "is_correct": true, "explanation": "环境标准是政府为保护环境定下的规则，放在“定了新的”之后语义通顺。"}, {"text": "球鞋", "is_correct": false, "explanation": "语义：政府不会给工厂定球鞋，整句说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“定”能搭配规则、价格，不能搭配“天气”。"}, {"text": "家规", "is_correct": false, "explanation": "语义：家规是家庭内部的规矩，与政府给工厂定规则的语境不符。"}], "explanations": {"环境标准": "环境标准是政府为保护环境定下的规则，放在“定了新的”之后语义通顺。", "球鞋": "语义：政府不会给工厂定球鞋，整句说不通。", "天气": "搭配：“定”能搭配规则、价格，不能搭配“天气”。", "家规": "语义：家规是家庭内部的规矩，与政府给工厂定规则的语境不符。"}, "sentence_index": 0, "correct_answer": "环境标准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府出台了一把新的环境标准。", "explanation": "这里应该用〈项〉。环境标准是一条条规定，“把”用于有柄的器具，不用于规定。"}, {"text": "这场事故造成了严重的环境标准。", "explanation": "这里应该用〈环境损害〉。事故造成的是损害，环境标准是规定，不能被“造成”。"}, {"text": "这里的环境标准被污染了。", "explanation": "这里应该用〈环境质量〉。被污染的是环境的状况，环境标准是规定，不会被污染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境标准", "is_correct": true, "explanation": "环境标准是可以被工厂达到的指标，放在“达到了”之后语义通顺。"}, {"text": "宠物", "is_correct": false, "explanation": "搭配：“达到”搭配标准、水平、目的，不能说“达到宠物”。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“达到”不搭配人或物的名字，句中应是工厂能达到的要求。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：工厂不能“达到”礼物，整句说不通。"}], "explanations": {"环境标准": "环境标准是可以被工厂达到的指标，放在“达到了”之后语义通顺。", "宠物": "搭配：“达到”搭配标准、水平、目的，不能说“达到宠物”。", "名字": "搭配：“达到”不搭配人或物的名字，句中应是工厂能达到的要求。", "礼物": "语义：工厂不能“达到”礼物，整句说不通。"}, "sentence_index": 6, "correct_answer": "环境标准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的环境标准超标了。", "explanation": "这里应该用〈排放量〉。“超标”指数量超过标准，环境标准本身是标准，不能“超标”。"}, {"text": "工厂每天向河里排放大量环境标准。", "explanation": "这里应该用〈污染物〉。排放的是污染物这类实际物质，环境标准是规定，不能被排放。"}, {"text": "这家工厂的环境标准被罚了款。", "explanation": "这里应该用〈企业〉。被罚款的是违规的企业，环境标准是规定，不能被罚款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府要求企业遵守一只新的环境标准。", "corrected_sentence": "政府要求企业遵守一项新的环境标准。", "error_description": "量词错误：环境标准是规定条文，应用“项”计量。写成“只”是错误，“只”多用于动物。正确说法是“一项新的环境标准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂每天都要遵守一只环境标准。", "corrected_sentence": "这家工厂每天都要遵守一项环境标准。", "error_description": "量词错误：环境标准是规定，应用“项”计量。写成“只”是错误，“只”用于动物等，不用于规定。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
