INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26336, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个东西，把别的东西装在里面。", "primary_collocate": null, "pronunciation": "bāo", "ipa": "pɑʊ̯˥", "syllable_count": 1, "sentences": [{"text": "我的包里有一本书和一瓶水。", "target_word": "包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把手机放进包里，就出门了。", "target_word": "包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包太重，我背不动。", "target_word": "包", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的包被小偷偷走了，里面有钱包和钥匙。", "target_word": "包", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "她买了一个红色的包，很好看。", "target_word": "包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，请检查一下你的包。", "target_word": "包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈的包很大，能装下三本杂志。", "target_word": "包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包是布做的，可以直接放进洗衣机洗。", "target_word": "包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背着一个黑色的包，站在车站门口等朋友。", "target_word": "包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把包放在椅子上，去前台拿了钥匙。", "target_word": "包", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "背包", "label": "复合"}, {"form": "书包", "label": "复合"}, {"form": "包包", "label": "重叠"}], "register": "中性", "sense_fingerprint": "包：名词，用来装东西的袋子，如背的包", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63014f8-71d4-4556-8cb1-49b555969f79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26336, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "包", "is_correct": true, "explanation": "包：装东西的袋子，正确答案。"}, {"text": "保", "is_correct": false, "explanation": "保 bǎo（第三声）与 bāo（第一声）声调不同，意思是保护，不是装东西的袋子。"}, {"text": "报", "is_correct": false, "explanation": "报 bào（第四声）与 bāo（第一声）声调不同，意思是报告或报纸。"}, {"text": "宝", "is_correct": false, "explanation": "宝 bǎo（第三声）与 bāo（第一声）声调不同，意思是宝贝。"}, {"text": "饱", "is_correct": false, "explanation": "饱 bǎo（第三声）与 bāo（第一声）声调不同，意思是吃饱了。"}, {"text": "帮", "is_correct": false, "explanation": "帮 bāng 与 bāo 韵尾不同（ng 与 o），意思是帮助。"}], "explanations": {"包": "包：装东西的袋子，正确答案。", "保": "保 bǎo（第三声）与 bāo（第一声）声调不同，意思是保护，不是装东西的袋子。", "报": "报 bào（第四声）与 bāo（第一声）声调不同，意思是报告或报纸。", "宝": "宝 bǎo（第三声）与 bāo（第一声）声调不同，意思是宝贝。", "饱": "饱 bǎo（第三声）与 bāo（第一声）声调不同，意思是吃饱了。", "帮": "帮 bāng 与 bāo 韵尾不同（ng 与 o），意思是帮助。"}, "sentence_index": null, "correct_answer": "包"}, "level_3": {"options": [{"text": "包", "is_correct": true, "explanation": "包：装东西的袋子，句中指“我的包”，可以装书和水。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：一本书放不进杯子里，与“一本书和一瓶水”不合。"}, {"text": "戒指盒", "is_correct": false, "explanation": "体貌：戒指盒太小，装不下一本书和一瓶水。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶用来插花，装不下一本书，与句中的物品不合。"}], "explanations": {"包": "包：装东西的袋子，句中指“我的包”，可以装书和水。", "杯子": "语义：一本书放不进杯子里，与“一本书和一瓶水”不合。", "戒指盒": "体貌：戒指盒太小，装不下一本书和一瓶水。", "花瓶": "语义：花瓶用来插花，装不下一本书，与句中的物品不合。"}, "sentence_index": 0, "correct_answer": "包"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她背了一块黑色的包去上班。", "explanation": "这里应该用量词〈个〉。包用“个”计量，“块”用于成块的东西，如蛋糕、布，不用于包。"}, {"text": "她买了一盒新包，颜色很漂亮。", "explanation": "这里应该用量词〈个〉。包用“个”计量，“盒”用于盒装的东西，如饼干、巧克力，不用于包。"}, {"text": "我昨天买了一条新包。", "explanation": "这里应该用量词〈个〉。包用“个”计量，“条”用于细长的东西，如裤子、绳子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26336, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "包", "is_correct": true, "explanation": "包：装东西的袋子，正确答案。"}, {"text": "抱", "is_correct": false, "explanation": "抱 bào（第四声）与 bāo（第一声）声调不同，意思是用手臂抱住。"}, {"text": "饱", "is_correct": false, "explanation": "饱 bǎo（第三声）与 bāo（第一声）声调不同，意思是吃饱了。"}, {"text": "棒", "is_correct": false, "explanation": "棒 bàng 与 bāo 韵母不同（ang 与 ao），声调也不同，意思是棒子或很好。"}, {"text": "暴", "is_correct": false, "explanation": "暴 bào（第四声）与 bāo（第一声）声调不同，意思是暴力或暴风。"}, {"text": "爆", "is_correct": false, "explanation": "爆 bào（第四声）与 bāo（第一声）声调不同，意思是爆炸或爆发。"}], "explanations": {"包": "包：装东西的袋子，正确答案。", "抱": "抱 bào（第四声）与 bāo（第一声）声调不同，意思是用手臂抱住。", "饱": "饱 bǎo（第三声）与 bāo（第一声）声调不同，意思是吃饱了。", "棒": "棒 bàng 与 bāo 韵母不同（ang 与 ao），声调也不同，意思是棒子或很好。", "暴": "暴 bào（第四声）与 bāo（第一声）声调不同，意思是暴力或暴风。", "爆": "爆 bào（第四声）与 bāo（第一声）声调不同，意思是爆炸或爆发。"}, "sentence_index": null, "correct_answer": "包"}, "level_3": {"options": [{"text": "包", "is_correct": true, "explanation": "包：装东西的袋子，句中指妈妈的包，能装三本杂志。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套装不下三本杂志，与“能装下三本杂志”矛盾。"}, {"text": "钱夹", "is_correct": false, "explanation": "体貌：钱夹太小，装不下三本杂志。"}, {"text": "瓶子", "is_correct": false, "explanation": "语义：瓶子口窄，装不下三本杂志，与句中的容量不合。"}], "explanations": {"包": "包：装东西的袋子，句中指妈妈的包，能装三本杂志。", "手套": "语义：手套装不下三本杂志，与“能装下三本杂志”矛盾。", "钱夹": "体貌：钱夹太小，装不下三本杂志。", "瓶子": "语义：瓶子口窄，装不下三本杂志，与句中的容量不合。"}, "sentence_index": 6, "correct_answer": "包"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙放进了一片新包里。", "explanation": "这里应该用量词〈个〉。包用“个”计量，“片”用于薄薄的东西，如叶子、纸，不用于包。"}, {"text": "妈妈给我买了一张新包，很结实。", "explanation": "这里应该用量词〈个〉。包不用“张”计量，“张”用于纸、桌子等平面的东西。"}, {"text": "他在超市买了一颗新包，颜色很深。", "explanation": "这里应该用量词〈个〉。包用“个”计量，“颗”用于圆形的小东西，如豆子、珠子，不用于包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐买了两本包，一个红的，一个黑的。", "corrected_sentence": "我姐姐买了两个包，一个红的，一个黑的。", "error_description": "量词错误：“包”的量词是“个”，“本”用于书册，不能用于包。应说“两个包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌子上的里包装着一本词典。", "corrected_sentence": "桌子上的包里装着一本词典。", "error_description": "方位词位置错误：“里”要紧跟在“包”后面，说“包里”，不能说“里包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b9a59a5-5e5d-4043-8fde-6b265ca52f0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
