INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放进水里或颜料里，让东西变成别的颜色。", "primary_collocate": null, "pronunciation": "rǎn sè", "ipa": "ʐan˨˩˦ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "她把白布放进蓝色颜料里染色。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用红茶给纸染色。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把白T恤放进蓝色染缸里染色。", "target_word": "染色", "complexity_tier": "T3", "furigana": "rǎn sè", "sentence_source": "generated"}, {"text": "奶奶用植物给布染色，颜色很自然。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把旧衣服放进黑色颜料里染色，就像新的。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染色前，要先把布洗干净。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复活节时，孩子们喜欢给鸡蛋染色。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块白布染色后变成了绿色。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么给围巾染色。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用蓝色颜料给白衬衫染色。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把东西放进颜料里使它变色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e6b670f-7507-4a9d-adc5-f33d2a882a9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "染色", "is_correct": true, "explanation": "“放进蓝色颜料里染色”指把白布放进颜料中使其变色，语义与句子吻合。"}, {"text": "洗涤", "is_correct": false, "explanation": "语义：洗涤是去除污垢，与放进蓝色颜料使布变色的意思相反。"}, {"text": "漂白", "is_correct": false, "explanation": "语义：漂白是去掉颜色使东西变白，与“蓝色颜料”的上色方向相反。"}, {"text": "烘干", "is_correct": false, "explanation": "配价：“烘干”不需要“放进颜料里”这样的处所结构，搭配不当。"}], "explanations": {"染色": "“放进蓝色颜料里染色”指把白布放进颜料中使其变色，语义与句子吻合。", "洗涤": "语义：洗涤是去除污垢，与放进蓝色颜料使布变色的意思相反。", "漂白": "语义：漂白是去掉颜色使东西变白，与“蓝色颜料”的上色方向相反。", "烘干": "配价：“烘干”不需要“放进颜料里”这样的处所结构，搭配不当。"}, "sentence_index": 0, "correct_answer": "染色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶用颜料给画染色，颜色很自然。", "explanation": "这里应该用〈上色〉。给画作涂颜料要说“上色”，染色是把布料等放进染料中着色。"}, {"text": "奶奶用漂白剂把旧布染色了。", "explanation": "这里应该用〈漂白〉。漂白是去掉颜色、使东西变白，与染色的上色方向正好相反。"}, {"text": "这种病菌容易通过伤口染色身体。", "explanation": "这里应该用〈感染〉。病菌侵入身体致病要说“感染”；染色指给材料着色，与此无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "染色", "is_correct": true, "explanation": "“给鸡蛋染色”指复活节给鸡蛋上色的活动，语义吻合。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻是降温保存，与复活节给鸡蛋上色的活动无关。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：打碎会破坏鸡蛋，与复活节孩子们喜欢做的活动相矛盾。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要接受者，“给鸡蛋送”配价不当，句子无法成立。"}], "explanations": {"染色": "“给鸡蛋染色”指复活节给鸡蛋上色的活动，语义吻合。", "冷冻": "语义：冷冻是降温保存，与复活节给鸡蛋上色的活动无关。", "打碎": "语义：打碎会破坏鸡蛋，与复活节孩子们喜欢做的活动相矛盾。", "送": "配价：“送”需要接受者，“给鸡蛋送”配价不当，句子无法成立。"}, "sentence_index": 6, "correct_answer": "染色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用刷子给白墙染色。", "explanation": "这里应该用〈涂色〉。染色要把东西放进染料中着色，给墙面刷颜色要说“涂色”。"}, {"text": "他用熨斗把白衬衫染色了。", "explanation": "这里应该用〈烫平〉。熨斗是用来把衣服烫平的，不是给衣服着色，所以不说“染色”。"}, {"text": "他用洗衣液给白衬衫染色。", "explanation": "这里应该用〈洗涤〉。洗衣液是用来去污的，而“染色”是为了让衣服变色，这里不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把布染色了红色。", "corrected_sentence": "妈妈把布染成了红色。", "error_description": "补语错误：表示把布变成某种颜色时，应说“染成”，不能说“染色了红色”；“染色”后面不能直接接结果颜色。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把衬衫被染色了。", "corrected_sentence": "他把衬衫染色了。", "error_description": "错误形式：把……被……同用；正确形式：去掉“被”。“把”字句和“被”字句不能同时使用，二者只能择一。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
