INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "问责制就是有人做错事，大家会问这是谁的责任。", "primary_collocate": null, "pronunciation": "wèn zé zhì", "ipa": "wən˥˩ tsɤ˧˥ ʈʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "我们班有问责制，谁弄坏东西，大家就问谁负责。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司有问责制，工作出错时要查清是谁的责任。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问责制让大家知道，做错事要有人负责。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有问责制，没人敢乱做决定。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队有问责制，输球后教练要说明原因。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里也可以有问责制，谁打破杯子谁来说明。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板用问责制管理，每个错误都要找到负责人。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问责制不是骂人，只是问清楚谁的责任。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的问责制很清楚，出错就问负责的人。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得问责制对团队很重要。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问责制度", "label": "复合"}], "register": "中性", "sense_fingerprint": "出错时追问是谁的责任的规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e6b670f-7507-4a9d-adc5-f33d2a882a9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问责制", "is_correct": true, "explanation": "正确：问责制指出错后追问谁负责的规矩，与“大家就问谁负责”一致。"}, {"text": "免责制", "is_correct": false, "explanation": "语义：“免责制”指不追究责任，与“大家就问谁负责”的意思相反。"}, {"text": "匿名制", "is_correct": false, "explanation": "语义：“匿名制”指隐去身份，无法“问谁负责”，与句意矛盾。"}, {"text": "保密制", "is_correct": false, "explanation": "搭配：“保密制”多用于信息、档案的保密，不用来管理“弄坏东西”后的追责，搭配不当。"}], "explanations": {"问责制": "正确：问责制指出错后追问谁负责的规矩，与“大家就问谁负责”一致。", "免责制": "语义：“免责制”指不追究责任，与“大家就问谁负责”的意思相反。", "匿名制": "语义：“匿名制”指隐去身份，无法“问谁负责”，与句意矛盾。", "保密制": "搭配：“保密制”多用于信息、档案的保密，不用来管理“弄坏东西”后的追责，搭配不当。"}, "sentence_index": 0, "correct_answer": "问责制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很有问责制，做事从来不推卸。", "explanation": "这里应该用〈责任心〉。问责制是追责的制度，不能说人“有”问责制；形容人的态度要说有责任心。"}, {"text": "我们班有一位问责制，谁弄坏东西大家就找谁。", "explanation": "量词“位”只用于人，问责制是制度，应说“一套”或“一项”问责制。"}, {"text": "他经常参加问责制，每次都能拿到第一名。", "explanation": "这里应该用〈比赛〉。问责制是追责的制度，不是可以参加的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问责制", "is_correct": true, "explanation": "正确：问责制是追责的制度，与“每个错误都要找到负责人”一致。"}, {"text": "人情", "is_correct": false, "explanation": "语义：“人情”指照顾情面，与“每个错误都要找到负责人”的追责要求相反。"}, {"text": "恩惠", "is_correct": false, "explanation": "语义：“恩惠”指好处或施舍，不能用来管理错误追责，与句意矛盾。"}, {"text": "随意性", "is_correct": false, "explanation": "搭配：“用…管理”的宾语应是制度或方法，“随意性”是性质，不能作管理手段。"}], "explanations": {"问责制": "正确：问责制是追责的制度，与“每个错误都要找到负责人”一致。", "人情": "语义：“人情”指照顾情面，与“每个错误都要找到负责人”的追责要求相反。", "恩惠": "语义：“恩惠”指好处或施舍，不能用来管理错误追责，与句意矛盾。", "随意性": "搭配：“用…管理”的宾语应是制度或方法，“随意性”是性质，不能作管理手段。"}, "sentence_index": 6, "correct_answer": "问责制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察把问责制逮捕了，案子就结了。", "explanation": "这里应该用〈责任人〉。“逮捕”只用于人，问责制是制度，不能被逮捕；应抓的是责任人。"}, {"text": "我们班新定了一张问责制，违反的人要罚站。", "explanation": "这里应该用〈一套〉。量词“张”用于纸张、桌子等平面物，问责制是制度，应说“一套”或“一项”。"}, {"text": "他主动承担了问责制，大家都很佩服。", "explanation": "这里应该用〈责任〉。问责制是制度，不能被“承担”，应说“承担责任”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班是问责制，谁把东西弄坏，大家就找谁负责。", "corrected_sentence": "我们班有问责制，谁把东西弄坏，大家就找谁负责。", "error_description": "动词误用：错误形式为“是问责制”，正确形式为“有问责制”。“是”表示判断，不能说班级“是”一种制度；表示拥有某种制度要用“有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有一只问责制，谁弄坏东西大家就找谁负责。", "corrected_sentence": "我们班有一套问责制，谁弄坏东西大家就找谁负责。", "error_description": "量词错误：错误形式为“一只问责制”，正确形式为“一套问责制”。“只”用于动物或单个物品，问责制是制度，应用“套”或“项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
