INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26348, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人看到本来不想让人看到的东西。", "primary_collocate": null, "pronunciation": "bào lù chū", "ipa": "pau̯˥˩ lu˥˩ ʈʂʰu˥", "syllable_count": 3, "sentences": [{"text": "他一说话，就暴露出自己是外地人。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑了一下，暴露出心里的紧张。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的脚印暴露出小偷藏身的地方。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光暴露出了他躲藏的位置。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口音暴露出他不是本地人。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的响声暴露出我们的位置。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话暴露出他的真实想法。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子脸红了，暴露出他在说谎。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别说太多，会暴露出你的秘密。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拼命地笑，还是暴露出内心的难过。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暴露", "label": "基本形式"}, {"form": "暴露出来", "label": "方向补语形式"}, {"form": "暴露出了", "label": "体标"}], "register": "中性", "sense_fingerprint": "言行或迹象无意中让别人看到想隐藏的身份、位置、想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7675ad-35c8-42da-8525-b50edf4a9d77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暴露出", "is_correct": true, "explanation": "正确。“一说话，就暴露出自己是外地人”，“暴露出”指无意中让人看到想隐藏的身份，语境相合。"}, {"text": "生产出", "is_correct": false, "explanation": "搭配：“生产出”搭配的是产品，不能说生产出“自己是外地人”这样的身份。"}, {"text": "冲出", "is_correct": false, "explanation": "搭配：“冲出”指向外猛冲，不能用来说明说话时暴露身份。"}, {"text": "藏起", "is_correct": false, "explanation": "语义：“藏起”表示隐藏，与“一说话就……”的因果关系矛盾，句意不通。"}], "explanations": {"暴露出": "正确。“一说话，就暴露出自己是外地人”，“暴露出”指无意中让人看到想隐藏的身份，语境相合。", "生产出": "搭配：“生产出”搭配的是产品，不能说生产出“自己是外地人”这样的身份。", "冲出": "搭配：“冲出”指向外猛冲，不能用来说明说话时暴露身份。", "藏起": "语义：“藏起”表示隐藏，与“一说话就……”的因果关系矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "暴露出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个结果暴露出他的方法有效。", "explanation": "这里应该用〈表明〉。暴露出指想隐藏的东西被看到，方法有效这类结论要用“表明”。"}, {"text": "这次比赛暴露出了他的冠军。", "explanation": "这里应该用〈赢得〉。暴露出指想隐藏的东西被看到，获得冠军要说赢得。"}, {"text": "这组数据暴露出了增长的趋势。", "explanation": "这里应该用〈显示出〉。暴露出指原本隐藏的东西被看到，客观的数据变化要说显示出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴露出", "is_correct": true, "explanation": "正确。“这句话暴露出他的真实想法”，“暴露出”指无意中让人看到想隐藏的想法，语境相合。"}, {"text": "煮出", "is_correct": false, "explanation": "语义：“煮出”指用火加热做出食物，与想法无关，句意不通。"}, {"text": "擦掉", "is_correct": false, "explanation": "语义：“擦掉”是除去痕迹，与“想法被看到”的语境正好相反。"}, {"text": "蒸出", "is_correct": false, "explanation": "语义：“蒸出”指用蒸汽加热做出，与想法无关，句意不通。"}], "explanations": {"暴露出": "正确。“这句话暴露出他的真实想法”，“暴露出”指无意中让人看到想隐藏的想法，语境相合。", "煮出": "语义：“煮出”指用火加热做出食物，与想法无关，句意不通。", "擦掉": "语义：“擦掉”是除去痕迹，与“想法被看到”的语境正好相反。", "蒸出": "语义：“蒸出”指用蒸汽加热做出，与想法无关，句意不通。"}, "sentence_index": 6, "correct_answer": "暴露出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次努力暴露出了好成绩。", "explanation": "这里应该用〈收获〉。暴露出指想隐藏的东西被看到，取得好成绩要说收获。"}, {"text": "工程师暴露出了一张图纸。", "explanation": "这里应该用〈绘制出〉。暴露出指想隐藏的东西被看到，画出图纸要说绘制出。"}, {"text": "作家暴露出了一部小说。", "explanation": "这里应该用〈写出〉。暴露出指想隐藏的东西被看到，创作小说要说写出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一开口，就暴露了出自己的身份。", "corrected_sentence": "他一开口，就暴露出了自己的身份。", "error_description": "错误：“暴露了出”；正确：“暴露出了”。“暴露出”是“暴露”加趋向补语“出”的固定结构，“了”应放在“出”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一慌张，就暴露来出心里的害怕。", "corrected_sentence": "她一慌张，就暴露出心里的害怕。", "error_description": "错误：“暴露来出”；正确：“暴露出”。趋向补语“出”紧跟动词，中间不能插入“来”，写成“暴露来出”语序不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5b85587-eb7c-433a-aff6-83caa2061758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
