INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做东西的方法和本领。", "primary_collocate": null, "pronunciation": "gōng yì", "ipa": "kʊŋ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他的木雕工艺非常精细。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师傅的工艺在村里最有名。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她学会了一门做银器的工艺。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件花瓶的工艺很细致。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷的竹编工艺是向父亲学的。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些漂亮的灯笼体现了他高超的工艺。", "target_word": "工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景德镇的瓷器以精美的工艺闻名。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人愿意学习传统工艺。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店的刺绣工艺让我很喜欢。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子的工艺很好，用了二十年。", "target_word": "工艺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "工艺品", "label": "复合"}, {"form": "工藝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "手工制作东西的技艺和本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e6b670f-7507-4a9d-adc5-f33d2a882a9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工艺", "is_correct": true, "explanation": "“他的木雕工艺非常精细”说的是木雕技艺精细，语义吻合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与木雕的技艺无关，“木雕天气”说不通。"}, {"text": "工钱", "is_correct": false, "explanation": "语义：工钱是报酬，不能用“精细”来描述，与木雕技艺的语境不符。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“精细”不能用来修饰嗓音，“嗓音非常精细”搭配不当。"}], "explanations": {"工艺": "“他的木雕工艺非常精细”说的是木雕技艺精细，语义吻合。", "天气": "语义：天气与木雕的技艺无关，“木雕天气”说不通。", "工钱": "语义：工钱是报酬，不能用“精细”来描述，与木雕技艺的语境不符。", "嗓音": "搭配：“精细”不能用来修饰嗓音，“嗓音非常精细”搭配不当。"}, "sentence_index": 0, "correct_answer": "工艺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件花瓶的工艺很鲜艳。", "explanation": "这里应该用〈颜色〉。工艺指做东西的本领，不能用来形容色彩是否鲜艳。"}, {"text": "她学会了一只做银器的工艺。", "explanation": "这里应该用〈门〉。工艺作为技艺，量词用“门”；“只”多用于动物，不能用于工艺。"}, {"text": "这位工艺的手很巧。", "explanation": "这里应该用〈工匠〉。工艺指技艺本身，不能指做工艺的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工艺", "is_correct": true, "explanation": "“以精美的工艺闻名”指瓷器的制作技艺精美，语义吻合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“精美”修饰的是技艺或作品，不能修饰“价格”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能用来描述瓷器的特色。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与瓷器以何闻名无关，“以精美的年龄闻名”说不通。"}], "explanations": {"工艺": "“以精美的工艺闻名”指瓷器的制作技艺精美，语义吻合。", "价格": "搭配：“精美”修饰的是技艺或作品，不能修饰“价格”。", "身高": "体貌：身高是人的体貌特征，不能用来描述瓷器的特色。", "年龄": "语义：年龄与瓷器以何闻名无关，“以精美的年龄闻名”说不通。"}, "sentence_index": 6, "correct_answer": "工艺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的工艺只有五公斤。", "explanation": "这里应该用〈重量〉。工艺指做东西的本领，不能用来表示重量。"}, {"text": "这位老师傅吃掉了很多工艺。", "explanation": "这里应该用〈饭〉。工艺是技艺，不能被吃，“吃”的对象应是食物。"}, {"text": "这家工艺每天营业十小时。", "explanation": "这里应该用〈店铺〉。工艺指做东西的本领，不能指店铺，也不能营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了两块竹编工艺。", "corrected_sentence": "他学了两门竹编工艺。", "error_description": "量词错误：“工艺”作为技艺，应用量词“门”；“块”多用于片状物，不能用于工艺，应说“两门竹编工艺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想学这门精美地工艺。", "corrected_sentence": "他想学这门精美的工艺。", "error_description": "结构助词错误：“精美”修饰名词“工艺”时应用“的”，说“精美的工艺”；“地”只用于修饰动词、形容词，不能用于名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
