INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不再有用的旧东西。", "primary_collocate": null, "pronunciation": "fèi jiù", "ipa": "feɪ˥˩ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老人每天出门收废旧东西。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "lǎo rén měi tiān chū mén shōu fèi jiù dōng xi.", "sentence_source": "generated"}, {"text": "院子里堆满了废旧东西。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "yuàn zi lǐ duī mǎn le fèi jiù dōng xi.", "sentence_source": "generated"}, {"text": "他靠卖废旧家电赚了一点钱。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "tā kào mài fèi jiù jiā diàn zhuàn le yì diǎn qián.", "sentence_source": "generated"}, {"text": "请把家里的废旧物品送到回收点。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "qǐng bǎ jiā lǐ de fèi jiù wù pǐn sòng dào huí shōu diǎn.", "sentence_source": "generated"}, {"text": "这个社区每周回收一次废旧电器。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "zhè ge shè qū měi zhōu huí shōu yí cì fèi jiù diàn qì.", "sentence_source": "generated"}, {"text": "小李用废旧材料做了很多玩具。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "xiǎo lǐ yòng fèi jiù cái liào zuò le hěn duō wán jù.", "sentence_source": "generated"}, {"text": "车库里的废旧物品要尽快清理。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "chē kù lǐ de fèi jiù wù pǐn yào jǐn kuài qīng lǐ.", "sentence_source": "generated"}, {"text": "那些废旧东西堆在墙角，很占地方。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "nà xiē fèi jiù dōng xi duī zài qiáng jiǎo, hěn zhàn dì fang.", "sentence_source": "generated"}, {"text": "废旧物品不要乱扔，要分类放好。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "fèi jiù wù pǐn bú yào luàn rēng, yào fēn lèi fàng hǎo.", "sentence_source": "generated"}, {"text": "他的小店专门买卖废旧家电。", "target_word": "废旧", "complexity_tier": "T3", "furigana": "tā de xiǎo diàn zhuān mén mǎi mài fèi jiù jiā diàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "废旧物资", "label": "复合"}, {"form": "废旧物品", "label": "复合"}, {"form": "廢舊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不再有用的旧东西（作名词，如收废旧）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e6b670f-7507-4a9d-adc5-f33d2a882a9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废旧", "is_correct": true, "explanation": "废旧：不再有用的旧东西，修饰“东西”，符合“收”的语境。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”描述温度或感觉，与“收废旧东西”的语境不合。"}, {"text": "魁梧", "is_correct": false, "explanation": "体貌：“魁梧”形容人的身材，不能用来修饰“东西”。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”形容事情或人，与“收废旧东西”的语境不合。"}], "explanations": {"废旧": "废旧：不再有用的旧东西，修饰“东西”，符合“收”的语境。", "冰冷": "语义：“冰冷”描述温度或感觉，与“收废旧东西”的语境不合。", "魁梧": "体貌：“魁梧”形容人的身材，不能用来修饰“东西”。", "有趣": "语义：“有趣”形容事情或人，与“收废旧东西”的语境不合。"}, "sentence_index": 0, "correct_answer": "废旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件老物件是一堆废旧东西，很有价值。", "explanation": "这里应该用〈文物〉。废旧东西指不再有用的旧物，有价值的老物件应称文物，不能说“废旧东西”。"}, {"text": "我很爱我的小猫，它是家里最重要的废旧东西。", "explanation": "这里应该用〈宝贝〉。废旧东西指不再有用的旧物，不能用来形容心爱的小猫。"}, {"text": "他的想法很废旧，早就该淘汰了。", "explanation": "这里应该用〈过时〉。废旧东西指不再有用的旧物，用于形容想法已落后时应说〈过时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废旧", "is_correct": true, "explanation": "废旧：不再有用的旧物品，修饰“物品”，符合“清理”的语境。"}, {"text": "珍贵", "is_correct": false, "explanation": "语义：“珍贵”的物品应妥善保存，与“尽快清理”的语境相反。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”的物品无需清理，与“尽快清理”的语境矛盾。"}, {"text": "精致", "is_correct": false, "explanation": "体貌：“精致”形容外形的细巧，与“尽快清理”的语境不合。"}], "explanations": {"废旧": "废旧：不再有用的旧物品，修饰“物品”，符合“清理”的语境。", "珍贵": "语义：“珍贵”的物品应妥善保存，与“尽快清理”的语境相反。", "干净": "语义：“干净”的物品无需清理，与“尽快清理”的语境矛盾。", "精致": "体貌：“精致”形容外形的细巧，与“尽快清理”的语境不合。"}, "sentence_index": 6, "correct_answer": "废旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些废旧东西都是新买的，还没用过。", "explanation": "这里应该用〈崭新〉。废旧东西指不再有用的旧物，新买未用的东西不能称为废旧东西。"}, {"text": "这些废旧东西煮一煮就能当饭吃。", "explanation": "这里应该用〈食物〉。废旧东西是不再有用的旧物，不能煮来当饭吃。"}, {"text": "他的婚纱是废旧东西，穿起来特别漂亮。", "explanation": "这里应该用〈礼服〉。废旧东西指不再有用的旧物，精心制作的婚纱不能这样称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把攒下的一张废旧东西都卖了。", "corrected_sentence": "她把攒下的一堆废旧东西都卖了。", "error_description": "错误形式：一张废旧东西；正确形式：一堆废旧东西。“张”用于纸张、桌子等平面的东西，成堆的杂物应用“堆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些东西还能用，没是废旧东西。", "corrected_sentence": "这些东西还能用，不是废旧东西。", "error_description": "错误形式：没是；正确形式：不是。判断句的否定要用“不是”，“没”不能用来否定“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c9c648-3d8d-470e-895e-4c8610e1c578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
