INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府为了让社会更好，定下的规则和办法。", "primary_collocate": null, "pronunciation": "gōng gòng zhèng cè", "ipa": "kʊŋ˥ kʊŋ˥˩ ʈʂɤŋ˥˩ tsʰɤ˥˩", "syllable_count": 4, "sentences": [{"text": "政府出了新的公共政策，帮助穷人看病。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共政策要让每个人都过得更好。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项公共政策对年轻人买房有帮助。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护环境，政府定了新的公共政策。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的公共政策不会只帮助一小部分人。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请我们讨论一项公共政策好不好。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的公共政策让孩子上学更方便。", "target_word": "公共政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写了很多关于公共政策的新闻。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共政策变了，大家的生活也会不同。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民可以对公共政策提出自己的想法。", "target_word": "公共政策", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "公共政策：政府为让社会更好而定下的规则和办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共利益", "is_correct": false, "explanation": "搭配：“出”不能与“利益”搭配，说“出了新的公共利益”不通。"}, {"text": "公共政策", "is_correct": true, "explanation": "正确。“公共政策”指政府为社会定下的规则和办法，与“出了新的……，帮助穷人看病”的语境相合。"}, {"text": "公共厕所", "is_correct": false, "explanation": "语义：厕所不能“帮助穷人看病”，句子的意思不通。"}, {"text": "公共场所", "is_correct": false, "explanation": "搭配：“出”用于政策、产品等，不说“出了新的公共场所”。"}], "explanations": {"公共利益": "搭配：“出”不能与“利益”搭配，说“出了新的公共利益”不通。", "公共政策": "正确。“公共政策”指政府为社会定下的规则和办法，与“出了新的……，帮助穷人看病”的语境相合。", "公共厕所": "语义：厕所不能“帮助穷人看病”，句子的意思不通。", "公共场所": "搭配：“出”用于政策、产品等，不说“出了新的公共场所”。"}, "sentence_index": 0, "correct_answer": "公共政策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家图书馆是一个很安静的公共政策。", "explanation": "这里应该用〈公共场所〉。“安静”形容地方，公共政策指政府定下的规则，不能用来形容一个地方；安静的地方应说“公共场所”。"}, {"text": "我每天坐公共政策上班。", "explanation": "这里应该用〈地铁〉。“坐”后面接的是交通工具，公共政策指政府定下的规则和办法，不能乘坐。"}, {"text": "公园和体育场都是重要的公共政策。", "explanation": "这里应该用〈公共设施〉。公园和体育场是具体的场所，应说“公共设施”；公共政策指规则和办法，不能指具体的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共假期", "is_correct": false, "explanation": "语义：假期意味着不用上学，与“让孩子上学更方便”的意思矛盾。"}, {"text": "公共政策", "is_correct": true, "explanation": "正确。“公共政策”作主语，指政府定下的规则，与“让孩子上学更方便”的意思相合。"}, {"text": "公共雕塑", "is_correct": false, "explanation": "语义：雕塑不能让孩子上学更方便，句子的意思不通。"}, {"text": "公共广场", "is_correct": false, "explanation": "搭配：“让……方便”的主语应是措施或制度，不能说广场让孩子上学更方便。"}], "explanations": {"公共假期": "语义：假期意味着不用上学，与“让孩子上学更方便”的意思矛盾。", "公共政策": "正确。“公共政策”作主语，指政府定下的规则，与“让孩子上学更方便”的意思相合。", "公共雕塑": "语义：雕塑不能让孩子上学更方便，句子的意思不通。", "公共广场": "搭配：“让……方便”的主语应是措施或制度，不能说广场让孩子上学更方便。"}, "sentence_index": 6, "correct_answer": "公共政策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公共政策上有很多人跳舞。", "explanation": "这里应该用〈公共广场〉。跳舞的人需要在具体的场地活动，公共政策是抽象的规则，不能作为场地。"}, {"text": "公共政策很脏，没人愿意去。", "explanation": "这里应该用〈公共厕所〉。公共政策是规则和办法，不是场所，“很脏”“没人愿意去”说的是具体的地方，应说“公共厕所”。"}, {"text": "公共政策每十分钟来一趟。", "explanation": "这里应该用〈公共汽车〉。政策是规则，不会“来”；说车辆每隔一段时间到站，要用“公共汽车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府今年出台了一张公共政策，帮助年轻人租房。", "corrected_sentence": "政府今年出台了一项公共政策，帮助年轻人租房。", "error_description": "量词错误：“政策”应该用量词“项”，“张”用于平面的东西，不能用于政策。应说“一项公共政策”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府这块公共政策让年轻人买得起房子。", "corrected_sentence": "政府这项公共政策让年轻人买得起房子。", "error_description": "量词错误：“政策”应该用量词“项”，“块”用于块状的东西，不能用于政策。应说“这项公共政策”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
