INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不买某个东西，或者不去做某件事。", "primary_collocate": null, "pronunciation": "dǐ zhì", "ipa": "ti˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我们抵制这个品牌，不再买它的鞋。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多网友抵制那部电影，没有人去看。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客抵制涨价的饮料，一瓶也不买。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抵制甜食，已经三个月没吃蛋糕了。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们抵制这家店，因为东西太贵。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家抵制过那家商店的假货。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抵制网购，只去商店买东西。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民抵制这场比赛，没人买票。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友抵制快餐，每天在家做饭。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费者抵制着这种产品，商店卖不出去。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵制了", "label": "体标"}, {"form": "抵制着", "label": "体标"}, {"form": "抵制过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不买某物或不做某事，以示反对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵制", "is_correct": true, "explanation": "本词，读作 dǐ zhì，表示不买某物或不做某事，以示反对。"}, {"text": "地质", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是地质。"}, {"text": "体制", "is_correct": false, "explanation": "tǐ 与 dǐ 声母不同（t 与 d），意思是体制。"}, {"text": "地支", "is_correct": false, "explanation": "dì 与 dǐ 声调不同，zhī 与 zhì 声调也不同，意思是地支。"}], "explanations": {"抵制": "本词，读作 dǐ zhì，表示不买某物或不做某事，以示反对。", "地质": "dì（第四声）与 dǐ（第三声）声调不同，意思是地质。", "体制": "tǐ 与 dǐ 声母不同（t 与 d），意思是体制。", "地支": "dì 与 dǐ 声调不同，zhī 与 zhì 声调也不同，意思是地支。"}, "sentence_index": null, "correct_answer": "抵制"}, "level_3": {"options": [{"text": "抵制", "is_correct": true, "explanation": "原句中的词，表示不再买这个品牌的东西，以示反对。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”与“不再买它的鞋”矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”与“不再买”矛盾。"}, {"text": "拥护", "is_correct": false, "explanation": "语域：“拥护”偏书面，与句子的口语语境不协调，且与“不再买”矛盾。"}], "explanations": {"抵制": "原句中的词，表示不再买这个品牌的东西，以示反对。", "支持": "语义：“支持”与“不再买它的鞋”矛盾。", "享受": "语义：“享受”与“不再买”矛盾。", "拥护": "语域：“拥护”偏书面，与句子的口语语境不协调，且与“不再买”矛盾。"}, "sentence_index": 0, "correct_answer": "抵制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞能抵制雨水，很好用。", "explanation": "这里应该用〈抵挡〉。“抵制”指不买、不做以示反对，雨水这类自然力量应说“抵挡”。"}, {"text": "为了安全，我们要抵制火灾。", "explanation": "这里应该用〈防止〉。“抵制”指不买、不做以示反对，火灾这类事故应说“防止”。"}, {"text": "这家店的新品很受欢迎，大家都抵制它，天天排队去买。", "explanation": "这里应该用〈光顾〉。“抵制”指不买、不做以示反对，此处写成排队购买，与本义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抵制", "is_correct": true, "explanation": "本词，读作 dǐ zhì，表示不买某物或不做某事，以示反对。"}, {"text": "地址", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，zhǐ 与 zhì 声调也不同，意思是地址。"}, {"text": "体质", "is_correct": false, "explanation": "tǐ 与 dǐ 声母不同（t 与 d），意思是人的身体素质，即体质。"}, {"text": "低值", "is_correct": false, "explanation": "dī 与 dǐ 声调不同，zhí 与 zhì 声调也不同，意思是价值低，即低值。"}], "explanations": {"抵制": "本词，读作 dǐ zhì，表示不买某物或不做某事，以示反对。", "地址": "dì（第四声）与 dǐ（第三声）声调不同，zhǐ 与 zhì 声调也不同，意思是地址。", "体质": "tǐ 与 dǐ 声母不同（t 与 d），意思是人的身体素质，即体质。", "低值": "dī 与 dǐ 声调不同，zhí 与 zhì 声调也不同，意思是价值低，即低值。"}, "sentence_index": null, "correct_answer": "抵制"}, "level_3": {"options": [{"text": "抵制", "is_correct": true, "explanation": "原句中的词，表示不买网购的东西、只去商店买，与句子的意思一致。"}, {"text": "参与", "is_correct": false, "explanation": "语义：“参与”与“只去商店买东西”矛盾。"}, {"text": "依赖", "is_correct": false, "explanation": "语义：“依赖”与“只去商店买东西”矛盾。"}, {"text": "热衷", "is_correct": false, "explanation": "语域：“热衷”偏书面，与口语化的句子不协调，且与“只去商店”矛盾。"}], "explanations": {"抵制": "原句中的词，表示不买网购的东西、只去商店买，与句子的意思一致。", "参与": "语义：“参与”与“只去商店买东西”矛盾。", "依赖": "语义：“依赖”与“只去商店买东西”矛盾。", "热衷": "语域：“热衷”偏书面，与口语化的句子不协调，且与“只去商店”矛盾。"}, "sentence_index": 6, "correct_answer": "抵制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影很精彩，大家都抵制它，纷纷去电影院看。", "explanation": "这里误把“抵制”当成了“支持、追捧”的意思，但它表示不买、不去做以示反对，与“纷纷去电影院看”相反。"}, {"text": "这种药可以抵制感冒的发作。", "explanation": "这里应该用〈预防〉。“抵制”指不买、不做以示反对，疾病的发作应说“预防”。"}, {"text": "老师要求我们抵制困难，勇敢向前。", "explanation": "这里应该用〈克服〉。“抵制”指不买、不做以示反对，困难要说“克服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们抵制于这家店的假货，不去买东西。", "corrected_sentence": "我们抵制这家店的假货，不去买东西。", "error_description": "错误形式：多加介词“于”。正确形式：“抵制”直接接宾语，不说“抵制于……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "观众抵制得那家剧场，没有人去看演出。", "corrected_sentence": "观众抵制了那家剧场，没有人去看演出。", "error_description": "错误形式：“得”。正确形式：“了”。“得”后面要接补语，如“抵制得很厉害”；这里表示动作已完成，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让小东西长大，比如种花或教小孩。", "primary_collocate": null, "pronunciation": "péi yù", "ipa": "pʰeɪ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈在阳台上培育了很多花。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷培育的小树已经长高了。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用心培育着家里的几盆兰花。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，我想培育一些青菜。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈辛苦培育孩子长大。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把种子放进土里，慢慢培育它们。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小花园里培育玫瑰。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师耐心培育每一个小朋友。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我培育的小花终于开了。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在温室里培育小苗，天暖了再种到地里。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "培育了", "label": "体标"}, {"form": "培育过", "label": "体标"}, {"form": "培育着", "label": "体标"}], "register": "中性", "sense_fingerprint": "照顾花草小苗或孩子，让他们慢慢长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "培育", "is_correct": true, "explanation": "妈妈在阳台上照料花草，使其生长，“培育”与句意吻合。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“摧毁”与“阳台上养花”的照料之意相反。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”多用于地下资源、文物或潜力，与阳台上养花的语境不合。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，不能带“花”作宾语。"}], "explanations": {"培育": "妈妈在阳台上照料花草，使其生长，“培育”与句意吻合。", "摧毁": "语义：“摧毁”与“阳台上养花”的照料之意相反。", "挖掘": "搭配：“挖掘”多用于地下资源、文物或潜力，与阳台上养花的语境不合。", "消失": "配价：“消失”是不及物动词，不能带“花”作宾语。"}, "sentence_index": 0, "correct_answer": "培育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在工地上培育了一座大桥。", "explanation": "这里应该用〈修建〉。培育指让小东西长大，大桥不会生长，不能这样用。"}, {"text": "他在阳台上培育了一张桌子。", "explanation": "语义：“培育”指让小东西长大，此处误用为“制作、摆放”的意思，家具不会生长，不能这样用。"}, {"text": "我的书包培育得很好。", "explanation": "语义：“培育”指让小东西长大，此处误用为“照料、保管”的意思，物品不会生长，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培育", "is_correct": true, "explanation": "在小花园里照料玫瑰使其生长，“培育”与句意吻合。"}, {"text": "掩埋", "is_correct": false, "explanation": "语义：“掩埋”指埋进土里，与让玫瑰生长发育的“培育”不符。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”的对象不能是植物，句中玫瑰无法被驱赶。"}, {"text": "扑灭", "is_correct": false, "explanation": "搭配：“扑灭”多用于火、疫情，不说扑灭“玫瑰”。"}], "explanations": {"培育": "在小花园里照料玫瑰使其生长，“培育”与句意吻合。", "掩埋": "语义：“掩埋”指埋进土里，与让玫瑰生长发育的“培育”不符。", "驱赶": "语义：“驱赶”的对象不能是植物，句中玫瑰无法被驱赶。", "扑灭": "搭配：“扑灭”多用于火、疫情，不说扑灭“玫瑰”。"}, "sentence_index": 6, "correct_answer": "培育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧衣服都培育了。", "explanation": "语义：“培育”指让小东西长大，此处误用为“处理、丢弃”的意思，织物不会生长，不能这样用。"}, {"text": "他在厨房里培育了一锅汤。", "explanation": "语义：“培育”指让小东西长大，此处误用为“熬煮、烹制”的意思，烹饪成品不会生长。"}, {"text": "这个工厂培育了很多钢材。", "explanation": "语义：此处误用为“生产、加工”的意思，“培育”只用于让小东西长大，不能用于金属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶在窗台上培育着了几盆兰花。", "corrected_sentence": "奶奶在窗台上培育了几盆兰花。", "error_description": "错误：“培育着了”。正确：“培育了”。“着”表示持续，“了”表示完成，二者叠用于“培育”这类动作动词不通，此处只保留“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们用了一个冬天培育了出一批小苗。", "corrected_sentence": "我们用了一个冬天培育出一批小苗。", "error_description": "错误：“培育了出”。正确：“培育出”。“出”作结果补语应直接接在动词之后，“培育了出”的说法不规范，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
