INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26366, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数量不多但质量很好。", "primary_collocate": null, "pronunciation": "shǎo ér jīng", "ipa": "ʂaʊ˨˩˦ aɚ˧˥ tɕiŋ˥˥", "syllable_count": 3, "sentences": [{"text": "这个小店的东西少而精，价格也合适。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的活动少而精，大家都喜欢。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友少而精，个个都很可靠。", "target_word": "少而精", "complexity_tier": "T3", "furigana": "tā de péng you shǎo ér jīng, gè gè dōu hěn kě kào。", "sentence_source": "generated"}, {"text": "妈妈买菜讲究少而精，从不浪费。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志文章少而精，读起来不累。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给的作业少而精，每道题都有用。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的水果少而精，个个新鲜。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的礼物少而精，挑一件用心的就够了。", "target_word": "少而精", "complexity_tier": "T3", "furigana": "hǎo de lǐ wù shǎo ér jīng, tiāo yí jiàn yòng xīn de jiù gòu le。", "sentence_source": "generated"}, {"text": "他的书架上的书少而精，本本都读过。", "target_word": "少而精", "complexity_tier": "T3", "furigana": "tā de shū jià shàng de shū shǎo ér jīng, běn běn dōu dú guò。", "sentence_source": "generated"}, {"text": "我家的玩具少而精，孩子玩得很开心。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西或人不多，但每一个都很好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少而精", "is_correct": true, "explanation": "原句中的词，指东西不多但每件都好，与“价格也合适”的评价一致。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”与后半句“价格也合适”矛盾。"}, {"text": "变质", "is_correct": false, "explanation": "语义：“变质”指东西坏掉，与“价格也合适”的好评矛盾。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：“发霉”指东西变坏，与“价格也合适”的好评矛盾。"}], "explanations": {"少而精": "原句中的词，指东西不多但每件都好，与“价格也合适”的评价一致。", "昂贵": "语义：“昂贵”与后半句“价格也合适”矛盾。", "变质": "语义：“变质”指东西坏掉，与“价格也合适”的好评矛盾。", "发霉": "语义：“发霉”指东西变坏，与“价格也合适”的好评矛盾。"}, "sentence_index": 0, "correct_answer": "少而精"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的东西少而精，件件都是残次品。", "explanation": "这里把“少而精”当成了只说数量少的意思，但它的“精”指质量好，这家店的东西质量很差，与之相反。"}, {"text": "这家店的货架上东西少而精，堆得满满当当。", "explanation": "这里误把“少而精”只当成了数量少的“少”，但堆得很满与“少”相矛盾。"}, {"text": "这次讲座少而精，大家都听睡着了。", "explanation": "这里误把“少而精”当成了“内容少”的意思，但它要求质量高，大家都听睡着说明讲座质量不高，不能用“少而精”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少而精", "is_correct": true, "explanation": "原句中的词，指水果不多但每个都好，与“个个新鲜”一致。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”与“个个新鲜”矛盾。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：“腐烂”与“个个新鲜”矛盾。"}, {"text": "残次", "is_correct": false, "explanation": "语义：“残次”指有瑕疵的次品，与“个个新鲜”矛盾。"}], "explanations": {"少而精": "原句中的词，指水果不多但每个都好，与“个个新鲜”一致。", "陈旧": "语义：“陈旧”与“个个新鲜”矛盾。", "腐烂": "语义：“腐烂”与“个个新鲜”矛盾。", "残次": "语义：“残次”指有瑕疵的次品，与“个个新鲜”矛盾。"}, "sentence_index": 6, "correct_answer": "少而精"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班这次考试成绩少而精，全班都不及格。", "explanation": "这里把“少而精”用在考试成绩上，误当成只说“数量少”，但“精”指质量好，全班不及格显然不符合。"}, {"text": "我们这次旅行只去了两个城市，走马观花，真是少而精。", "explanation": "这里误把“少而精”当成了只看“去的地方少”的意思，但“精”指质量高，走马观花式的旅行显然不符合。"}, {"text": "这家公司的亏损少而精，去年一年亏了两亿。", "explanation": "这里把“少”理解成“亏得少”，但“精”指质量高，亏损两亿是负面结果，不能用“少而精”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家的厨具比少而精，锅碗都很好用。", "corrected_sentence": "我家的厨具少而精，锅碗都很好用。", "error_description": "错误形式：多加“比”。正确形式：去掉“比”。“少而精”是形容词，可直接作谓语，单独用“比”引出的句子缺少比较对象，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家花店的花比少而精，每束都很漂亮。", "corrected_sentence": "这家花店的花少而精，每束都很漂亮。", "error_description": "错误形式：多加“比”。正确形式：去掉“比”。“少而精”可直接作谓语，“比”引出的句子缺少比较对象，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
