INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是“才”或“才能”，表示有了某个条件后，才能做另一件事。", "primary_collocate": null, "pronunciation": "fāng néng", "ipa": "fɑŋ˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "必须先买票，方能进入公园。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了十八岁，方能参加这个比赛。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设备通过安全检测后，方能投入使用。", "target_word": "方能", "complexity_tier": "T3", "furigana": "shè bèi tōng guò ān quán jiǎn cè hòu, fāng néng tóu rù shǐ yòng.", "sentence_source": "generated"}, {"text": "申请材料全部提交后，方能进入审核流程。", "target_word": "方能", "complexity_tier": "T3", "furigana": "shēn qǐng cái liào quán bù tí jiāo hòu, fāng néng jìn rù shěn hé liú chéng.", "sentence_source": "generated"}, {"text": "要有耐心，方能做好这件事。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验器材彻底消毒后，方能用于样本检测。", "target_word": "方能", "complexity_tier": "T3", "furigana": "shí yàn qì cái chè dǐ xiāo dú hòu, fāng néng yòng yú yàng běn jiǎn cè.", "sentence_source": "generated"}, {"text": "天气暖和了，花儿方能盛开。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了钥匙，方能打开这扇门。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过老师同意，方能离开教室。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站得高，方能看得远。", "target_word": "方能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面副词，相当于“才”“才能”，强调先有条件、后做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc48de5a-e0a4-461a-9d2c-5287d6870dbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方能", "is_correct": true, "explanation": "正确：「方能」表示只有先买票这一条件满足，才能进入公园。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与「必须先买票」这种规定语境不合。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：「已经」表示已经发生，与「必须先……」这种尚未发生的前提不搭配。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，而此句前后是顺承的条件关系，没有转折。"}], "explanations": {"方能": "正确：「方能」表示只有先买票这一条件满足，才能进入公园。", "竟然": "语义：「竟然」表示出乎意料，与「必须先买票」这种规定语境不合。", "已经": "搭配：「已经」表示已经发生，与「必须先……」这种尚未发生的前提不搭配。", "却": "语义：「却」表示转折，而此句前后是顺承的条件关系，没有转折。"}, "sentence_index": 0, "correct_answer": "方能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题他一看就方能明白。", "explanation": "这里应删去〈方能〉，直接说「一看就明白」。「一……就……」表示紧接着发生，与「方能」表示的条件关系冲突。"}, {"text": "每当下雨，我们方能待在家。", "explanation": "这里应该用〈就〉。「每当……就……」表示每次都会发生的结果，「方能」表示只有满足条件才能，语义不合。"}, {"text": "他方能准时到达。", "explanation": "这里应该用〈一定〉。「方能」表示只有满足条件才能实现结果，句中没有条件，表示确定会发生应当用「一定」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方能", "is_correct": true, "explanation": "正确：「方能」表示天气暖和这一条件满足后，花儿才能盛开。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：「偏偏」表示有意与常理相反，与「天气暖和了」这种顺理成章的原因不合。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示事理上的要求，花儿不能被要求盛开，句意不通。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，而此句前后是因果关系，没有转折。"}], "explanations": {"方能": "正确：「方能」表示天气暖和这一条件满足后，花儿才能盛开。", "偏偏": "语义：「偏偏」表示有意与常理相反，与「天气暖和了」这种顺理成章的原因不合。", "必须": "语义：「必须」表示事理上的要求，花儿不能被要求盛开，句意不通。", "却": "语义：「却」表示转折，而此句前后是因果关系，没有转折。"}, "sentence_index": 6, "correct_answer": "方能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没复习，方能考好。", "explanation": "这里应该用〈却〉。「方能」要求先满足某个条件才能实现结果，此句条件并未满足，表示转折应用「却」。"}, {"text": "她每天方能喝茶。", "explanation": "这里应该用〈总是〉。「方能」表示只有满足条件才能实现结果，不能表示经常性的习惯。"}, {"text": "这种做法方能失败。", "explanation": "这里应该用〈必然〉。「方能」表示条件，不能表示必然会发生的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "必须先签字，才方能办理手续。", "corrected_sentence": "必须先签字，方能办理手续。", "error_description": "错误：「方能」前又加了「才」，两者都表示“只有……才……”，叠用多余。正确：「必须先签字，方能办理手续。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早睡早起，方能能身体健康。", "corrected_sentence": "早睡早起，方能身体健康。", "error_description": "错误：「方能」本身已含“能”的意思，后面不能再加「能」，「方能能」重复。正确：「早睡早起，方能身体健康。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使某物（如图片背景、图层）变得透明，能透过它看到后面的内容。", "primary_collocate": null, "pronunciation": "tòu míng huà", "ipa": "tʰoʊ˥˩ miŋ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "我把照片的背景透明化了。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "设计师先把图层透明化，再放到图片上。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "修图时，先把白色底色透明化。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "这张图标的背景可以透明化。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "这张图片的边框已经透明化了。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "他用软件把水印透明化了。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "这个素材的背景透明化后，可以放在任何图片上。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "经过透明化处理，这张图片的背景看不见了。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "把图片的背景透明化后，文字看得更清楚。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}, {"text": "老师教我们怎样把图层透明化。", "target_word": "透明化", "complexity_tier": "T3", "furigana": "tòu míng huà", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "让物体变得透明，能看清里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0f4af5-86fa-4104-a89d-57a274fcc82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明化", "is_correct": true, "explanation": "动词，表示使照片背景变得透明，与“我把……了”的结构相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用来处理照片背景。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与修图无关，句子不成立。"}, {"text": "发酵", "is_correct": false, "explanation": "配价：“发酵”是不及物动词，不能带“把”字宾语。"}], "explanations": {"透明化": "动词，表示使照片背景变得透明，与“我把……了”的结构相符。", "煮": "搭配：“煮”的对象是食物，不能用来处理照片背景。", "唱": "语义：“唱”指发声演唱，与修图无关，句子不成立。", "发酵": "配价：“发酵”是不及物动词，不能带“把”字宾语。"}, "sentence_index": 0, "correct_answer": "透明化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这首歌透明化了。", "explanation": "这里应该用〈删除〉。「删除」指去掉某项内容；「透明化」只用于图像或图层的显示效果，不能用于歌曲。"}, {"text": "摄影师把这张照片透明化成了方形。", "explanation": "这里应该用〈裁剪〉。「裁剪」指去掉图片的多余部分、改变形状；「透明化」只改变透明效果，不能改变形状。"}, {"text": "他把这杯牛奶透明化了。", "explanation": "这里应该用〈加热〉。「加热」指升高温度；「透明化」只用于图像或图层的显示效果，不能用于液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明化", "is_correct": true, "explanation": "动词，表示使素材背景透明，之后可以叠放在其他图片上，句意通顺。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：背景是图像元素，不能被冷冻，句子不成立。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指破坏实物，与素材背景的处理无关，后文也无法接续。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是农作物，不能用于图像背景。"}], "explanations": {"透明化": "动词，表示使素材背景透明，之后可以叠放在其他图片上，句意通顺。", "冷冻": "语义：背景是图像元素，不能被冷冻，句子不成立。", "打碎": "语义：“打碎”指破坏实物，与素材背景的处理无关，后文也无法接续。", "收割": "搭配：“收割”的对象是农作物，不能用于图像背景。"}, "sentence_index": 6, "correct_answer": "透明化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师教我们怎样透明化鸡蛋。", "explanation": "这里应该用〈煮〉。「煮」指用水加热食物；「透明化」只用于图像或图层的显示效果，不能用于食物。"}, {"text": "老师教我们怎样透明化文件。", "explanation": "这里应该用〈压缩〉。「压缩」指减小文件体积；「透明化」只能用于图像或图层的显示效果。"}, {"text": "老师教我们怎样透明化打印的文档。", "explanation": "这里应该用〈复印〉。「复印」指把文档复制一份；「透明化」只用于图像或图层的显示效果，不能用于纸质文档。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把图标的背景把透明化了。", "corrected_sentence": "他把图标的背景透明化了。", "error_description": "“把”字重复：一个“把”字句只能用一次“把”，“把图标的背景”后不应再加“把”。应说“他把图标的背景透明化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这个图层很透明化。", "corrected_sentence": "请把这个图层透明化。", "error_description": "错误在于“很”：“很”是程度副词，不能直接修饰动词“透明化”。删去“很”，应说“请把这个图层透明化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b49bcd84-e272-4083-8df6-9c755c7d11bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
