INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26374, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让小朋友或学生少做一些作业或任务，让他们不那么累。", "primary_collocate": null, "pronunciation": "jiǎn fù", "ipa": "tɕjɛn˨˩˦ fu˥˩", "syllable_count": 2, "sentences": [{"text": "今年我们学校开始减负了。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减负后，我每天作业少多了。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想给我减负，不让我上太多课。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天给大家减负，不留作业。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让小朋友开心，学校决定减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减负以后，孩子们有时间玩了。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不再让我上补习班，这就是减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校减负，同学们都很高兴。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业太多会很累，所以要减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班这周减负，只写一点作业。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减负了", "label": "体标"}, {"form": "减负增效", "label": "复合"}], "register": "中性", "sense_fingerprint": "让孩子或学生少做作业、少上课，不那么累", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc48de5a-e0a4-461a-9d2c-5287d6870dbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减负", "is_correct": true, "explanation": "正确：「减负」指让学生少做作业、不那么累，与「今年学校开始……」的语境一致。"}, {"text": "加班", "is_correct": false, "explanation": "语义：「加班」是员工额外工作，与「学校」和“减负”的语境不合。"}, {"text": "降温", "is_correct": false, "explanation": "语义：「降温」指气温下降，不能用于学校的做法，句意不通。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：「失踪」指人或物下落不明，与学校的做法无关，句意不通。"}], "explanations": {"减负": "正确：「减负」指让学生少做作业、不那么累，与「今年学校开始……」的语境一致。", "加班": "语义：「加班」是员工额外工作，与「学校」和“减负”的语境不合。", "降温": "语义：「降温」指气温下降，不能用于学校的做法，句意不通。", "失踪": "语义：「失踪」指人或物下落不明，与学校的做法无关，句意不通。"}, "sentence_index": 0, "correct_answer": "减负"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂因为订单少而减负。", "explanation": "这里应该用〈减产〉。「减负」指减轻人或学生的负担，不指产量减少，产量下降要用「减产」。"}, {"text": "他每天跑步减负。", "explanation": "这里应该用〈减肥〉。「减负」指减轻课业或工作的负担，不指减轻体重，减肥要用「减肥」。"}, {"text": "他一个月给自己减负了三公斤。", "explanation": "这里应该用〈减重〉。「减负」指减轻课业或任务的负担，不指体重，减轻体重要用「减重」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减负", "is_correct": true, "explanation": "正确：「减负」指减轻负担，与「不再让我上补习班」的做法一致。"}, {"text": "补课", "is_correct": false, "explanation": "语义：「补课」是额外加课，与「不再让我上补习班」的意思相反。"}, {"text": "加码", "is_correct": false, "explanation": "搭配：「加码」指提高指标或数量，不能用于指代「不再让我上补习班」这种做法。"}, {"text": "加重", "is_correct": false, "explanation": "语义：「加重」表示加重负担，与「不再让我上补习班」的意思相反。"}], "explanations": {"减负": "正确：「减负」指减轻负担，与「不再让我上补习班」的做法一致。", "补课": "语义：「补课」是额外加课，与「不再让我上补习班」的意思相反。", "加码": "搭配：「加码」指提高指标或数量，不能用于指代「不再让我上补习班」这种做法。", "加重": "语义：「加重」表示加重负担，与「不再让我上补习班」的意思相反。"}, "sentence_index": 6, "correct_answer": "减负"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商店为了促销减负。", "explanation": "这里应该用〈降价〉。「减负」指减轻负担，价格下降要用「降价」。"}, {"text": "这家工厂今年每天减负一吨二氧化碳。", "explanation": "这里应该用〈减排〉。「减负」指减轻负担，不指排放量，减少二氧化碳排放要用「减排」。"}, {"text": "火车进站时减负。", "explanation": "这里应该用〈减速〉。「减负」不能用于速度，火车放慢要用「减速」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师为同学减负负担，少留作业。", "corrected_sentence": "老师为同学减负，少留作业。", "error_description": "错误：「减负」已含“减轻负担”的意思，后面不能再加宾语「负担」，多余。正确：「老师为同学减负，少留作业。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校这周给学生减负负担。", "corrected_sentence": "学校这周给学生减负。", "error_description": "错误：「减负」已含“减轻负担”的意思，后面不能再加「负担」，多余。正确：「学校这周给学生减负。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '485ce32d-03fb-4189-99af-07f203f47bf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26376, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷静", "is_correct": true, "explanation": "正确。“冷静”指遇事沉着、不轻率行事，与形容词“冲动”在词义上相对。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有污垢，与“冲动”的任何义项都没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足或颜色鲜明，与“冲动”没有反义关系。"}, {"text": "宽大", "is_correct": false, "explanation": "“宽大”指面积或范围大，与“冲动”没有反义关系。"}], "correct_answer": "冷静", "explanations": {"冷静": "正确。“冷静”指遇事沉着、不轻率行事，与形容词“冲动”在词义上相对。", "干净": "“干净”指没有污垢，与“冲动”的任何义项都没有反义关系。", "明亮": "“明亮”指光线充足或颜色鲜明，与“冲动”没有反义关系。", "宽大": "“宽大”指面积或范围大，与“冲动”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26376, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理智", "is_correct": true, "explanation": "正确。“理智”指理性、不冲动的状态，与形容词“冲动”在词义上相对。"}, {"text": "精美", "is_correct": false, "explanation": "“精美”形容制作精细、好看，与“冲动”没有反义关系。"}, {"text": "硬朗", "is_correct": false, "explanation": "“硬朗”形容身体结实或物品坚硬，与“冲动”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“冲动”没有反义关系。"}], "correct_answer": "理智", "explanations": {"理智": "正确。“理智”指理性、不冲动的状态，与形容词“冲动”在词义上相对。", "精美": "“精美”形容制作精细、好看，与“冲动”没有反义关系。", "硬朗": "“硬朗”形容身体结实或物品坚硬，与“冲动”没有反义关系。", "宽敞": "“宽敞”形容空间大，与“冲动”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26376, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "想也不想就去做一件事。", "primary_collocate": null, "pronunciation": "chōng dòng", "ipa": "ʈʂʰʊŋ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你别冲动，先想一想再说。", "target_word": "冲动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他太冲动了，一生气就打了人。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冲动的人常常会后悔。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一时冲动，买了很贵的包。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人做事容易冲动。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很冲动，没问清楚就走了。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定太冲动，你再想想。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他冲动地辞掉了工作。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题不要冲动，先问问老师。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟脾气冲动，说话不经过大脑。", "target_word": "冲动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "衝動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不加思考、凭一时情绪行事的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c294d4a5-cb8b-4cb8-85ca-1526f4c5d197') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26376, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冲动", "is_correct": true, "explanation": "正确答案：冲动（chōng dòng）。"}, {"text": "冲淡", "is_correct": false, "explanation": "chōng dàn 与 chōng dòng 的第二音节韵母不同（an 与 ong），意思是使浓度降低。"}, {"text": "抽动", "is_correct": false, "explanation": "chōu dòng 与 chōng dòng 的第一音节韵母不同（ou 与 ong），意思是快速地拉动或抽搐。"}, {"text": "虫洞", "is_correct": false, "explanation": "chóng dòng 与 chōng dòng 只有第一音节声调不同，意思是连接宇宙两处的通道。"}], "explanations": {"冲动": "正确答案：冲动（chōng dòng）。", "冲淡": "chōng dàn 与 chōng dòng 的第二音节韵母不同（an 与 ong），意思是使浓度降低。", "抽动": "chōu dòng 与 chōng dòng 的第一音节韵母不同（ou 与 ong），意思是快速地拉动或抽搐。", "虫洞": "chóng dòng 与 chōng dòng 只有第一音节声调不同，意思是连接宇宙两处的通道。"}, "sentence_index": null, "correct_answer": "冲动"}, "level_3": {"options": [{"text": "冲动", "is_correct": true, "explanation": "正确。“你别冲动，先想一想再说”，形容词“冲动”指不经思考就行事。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：「你别漂亮，先想一想再说」语义不通，与“先想一想”的语境无关。"}, {"text": "大", "is_correct": false, "explanation": "体貌：“大”描写体型或大小，不能用在劝人“别…”的语境中。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”描写身高，「你别高」不成句，与此语境不合。"}], "explanations": {"冲动": "正确。“你别冲动，先想一想再说”，形容词“冲动”指不经思考就行事。", "漂亮": "语义：「你别漂亮，先想一想再说」语义不通，与“先想一想”的语境无关。", "大": "体貌：“大”描写体型或大小，不能用在劝人“别…”的语境中。", "高": "体貌：“高”描写身高，「你别高」不成句，与此语境不合。"}, "sentence_index": 0, "correct_answer": "冲动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这款游戏很冲动，已经玩了三年。", "explanation": "这里应该用〈兴趣〉。冲动形容做事不经考虑，不用来表示对事物的喜好；表示喜好应说“有兴趣”。"}, {"text": "这场雨下得很冲动，一连下了三天。", "explanation": "这里应该用〈猛烈〉。冲动只描述人的行事态度，不能用来形容雨。"}, {"text": "她对朋友很冲动，总是主动帮忙。", "explanation": "这里应该用〈热情〉。冲动指凭一时情绪行事，不用于形容对人友好的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26376, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冲动", "is_correct": true, "explanation": "正确答案：冲动（chōng dòng）。"}, {"text": "充当", "is_correct": false, "explanation": "chōng dāng 与 chōng dòng 的第二音节韵母不同（āng 与 òng），意思是担任。"}, {"text": "出动", "is_correct": false, "explanation": "chū dòng 与 chōng dòng 的第一音节韵母不同（u 与 ong），意思是派出人员或设备。"}, {"text": "冲荡", "is_correct": false, "explanation": "chōng dàng 与 chōng dòng 的第二音节韵母不同（ang 与 ong），意思是冲刷、荡涤。"}], "explanations": {"冲动": "正确答案：冲动（chōng dòng）。", "充当": "chōng dāng 与 chōng dòng 的第二音节韵母不同（āng 与 òng），意思是担任。", "出动": "chū dòng 与 chōng dòng 的第一音节韵母不同（u 与 ong），意思是派出人员或设备。", "冲荡": "chōng dàng 与 chōng dòng 的第二音节韵母不同（ang 与 ong），意思是冲刷、荡涤。"}, "sentence_index": null, "correct_answer": "冲动"}, "level_3": {"options": [{"text": "冲动", "is_correct": true, "explanation": "正确。“这个决定太冲动，你再想想”，形容词“冲动”描述决定是仓促做出的。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：“圆”描写形状，不能用来评价“决定”。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写高度，「这个决定太矮」不成句。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，用来形容“决定”语义不通。"}], "explanations": {"冲动": "正确。“这个决定太冲动，你再想想”，形容词“冲动”描述决定是仓促做出的。", "圆": "体貌：“圆”描写形状，不能用来评价“决定”。", "矮": "体貌：“矮”描写高度，「这个决定太矮」不成句。", "甜": "语义：“甜”指味道，用来形容“决定”语义不通。"}, "sentence_index": 6, "correct_answer": "冲动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很冲动，不敢跟女孩说话。", "explanation": "这里应该用〈害羞〉。冲动表示做事不经考虑、凭情绪行动，与“不敢”的意思矛盾。"}, {"text": "他教孩子做题很冲动，每次都讲三遍。", "explanation": "这里应该用〈耐心〉。冲动指不经考虑就行动，不能用来形容教学时的耐心。"}, {"text": "他做事很冲动，每一步都先想清楚。", "explanation": "这里应该用〈谨慎〉。冲动指不经考虑就行动，与“每一步都先想清楚”的做法相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他冲动的说了一句气话。", "corrected_sentence": "他冲动地说了一句气话。", "error_description": "结构助词错误：“冲动”作状语修饰动词“说”，应用“地”，不用“的”。正确形式是“冲动地说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不能冲动的做决定。", "corrected_sentence": "我们不能冲动地做决定。", "error_description": "结构助词错误：“冲动”作状语修饰动词“做”，应用“地”，不用“的”。正确形式是“冲动地做决定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a7c650e-a09f-4859-8983-f5770eaaaa81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26378, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昂贵", "is_correct": true, "explanation": "反义：廉价 与 昂贵 指东西价钱的低与高，两者相对。"}, {"text": "干净", "is_correct": false, "explanation": "形容洁净，与「廉价」的价钱意义无关，不构成反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "形容空间大，与「廉价」的价钱意义无关，不构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "形容光线充足，与「廉价」的价钱意义无关，不构成反义关系。"}], "correct_answer": "昂贵", "explanations": {"昂贵": "反义：廉价 与 昂贵 指东西价钱的低与高，两者相对。", "干净": "形容洁净，与「廉价」的价钱意义无关，不构成反义关系。", "宽敞": "形容空间大，与「廉价」的价钱意义无关，不构成反义关系。", "明亮": "形容光线充足，与「廉价」的价钱意义无关，不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26378, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昂贵", "is_correct": true, "explanation": "反义：廉价 与 昂贵 指东西价钱的低与高，两者相对。"}, {"text": "清楚", "is_correct": false, "explanation": "形容明白、不模糊，与「廉价」的价钱意义无关，不构成反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "形容温度或感觉，与「廉价」的价钱意义无关，不构成反义关系。"}, {"text": "轻便", "is_correct": false, "explanation": "形容分量轻、便于携带，与「廉价」的价钱意义无关，不构成反义关系。"}], "correct_answer": "昂贵", "explanations": {"昂贵": "反义：廉价 与 昂贵 指东西价钱的低与高，两者相对。", "清楚": "形容明白、不模糊，与「廉价」的价钱意义无关，不构成反义关系。", "温暖": "形容温度或感觉，与「廉价」的价钱意义无关，不构成反义关系。", "轻便": "形容分量轻、便于携带，与「廉价」的价钱意义无关，不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26378, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西很便宜，花很少钱就能买到。", "primary_collocate": null, "pronunciation": "lián jià", "ipa": "li̯ɛn˧˥ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这双鞋是廉价的，只要二十块。", "target_word": "廉价", "complexity_tier": "T3", "furigana": "zhè shuāng xié shì lián jià de, zhǐ yào èr shí kuài.", "sentence_source": "generated"}, {"text": "超市里有很多廉价的水果。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢在网上买廉价的衣服。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "廉价的饭馆里总是坐满了人。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的桌子是廉价的木头做的。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种廉价的伞，下雨天很多人买。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只能买得起廉价的自行车。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "廉价的书包用了半年就坏了。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小店里卖廉价的小东西。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他找了一家廉价的酒店，一晚上八十块。", "target_word": "廉价", "complexity_tier": "T3", "furigana": "tā zhǎo le yì jiā lián jià de jiǔ diàn, yì wǎn shàng bā shí kuài.", "sentence_source": "generated"}], "morphological_forms": [{"form": "廉價", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西便宜、花很少的钱就能买到，多用来形容日用品、衣物和食物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '434c0685-b138-4d57-a528-8792d79dfc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26378, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "廉价", "is_correct": true, "explanation": "正确答案。廉价 lián jià 指东西很便宜，花很少钱就能买到。"}, {"text": "年假", "is_correct": false, "explanation": "nián（n）与 lián（l）声母不同，年假 nián jià 意思是一年一度的假期，不是廉价。"}, {"text": "粮价", "is_correct": false, "explanation": "liáng 与 lián 韵母不同（ang 与 an），粮价 liáng jià 指粮食的价格。"}, {"text": "连接", "is_correct": false, "explanation": "jiē 与 jià 的韵母和声调都不同，连接 lián jiē 意思是把两者接在一起。"}], "explanations": {"廉价": "正确答案。廉价 lián jià 指东西很便宜，花很少钱就能买到。", "年假": "nián（n）与 lián（l）声母不同，年假 nián jià 意思是一年一度的假期，不是廉价。", "粮价": "liáng 与 lián 韵母不同（ang 与 an），粮价 liáng jià 指粮食的价格。", "连接": "jiē 与 jià 的韵母和声调都不同，连接 lián jiē 意思是把两者接在一起。"}, "sentence_index": null, "correct_answer": "廉价"}, "level_3": {"options": [{"text": "廉价", "is_correct": true, "explanation": "正确：廉价作谓语，说明这双鞋价钱低，只要二十块。"}, {"text": "名贵", "is_correct": false, "explanation": "语义：「名贵」指珍贵、价格高，与「只要二十块」矛盾。"}, {"text": "豪华", "is_correct": false, "explanation": "搭配：「豪华」多用于酒店、汽车等，说鞋子「豪华」不自然，也与价钱低的说明不符。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：「昂贵」指价钱高，与「只要二十块」矛盾。"}], "explanations": {"廉价": "正确：廉价作谓语，说明这双鞋价钱低，只要二十块。", "名贵": "语义：「名贵」指珍贵、价格高，与「只要二十块」矛盾。", "豪华": "搭配：「豪华」多用于酒店、汽车等，说鞋子「豪华」不自然，也与价钱低的说明不符。", "昂贵": "语义：「昂贵」指价钱高，与「只要二十块」矛盾。"}, "sentence_index": 0, "correct_answer": "廉价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的天空很廉价，一抬头就能看到大片的云。", "explanation": "这里应该用〈晴朗〉。廉价只形容价钱低的东西，不能用来形容天空。"}, {"text": "这条河很廉价，清得能看见鱼。", "explanation": "这里应该用〈清〉。廉价只形容价钱低的东西，不能用来形容河水。"}, {"text": "图书馆里很廉价，大家都在看书。", "explanation": "这里应该用〈安静〉。安静形容环境声音小；廉价只形容价钱低的东西，不能用来形容图书馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "廉价", "is_correct": true, "explanation": "正确：「只能买得起」说明自行车价钱低，修饰自行车的「廉价」最合适。"}, {"text": "高档", "is_correct": false, "explanation": "语义：「高档」指档次高、价钱贵，与「只能买得起」矛盾。"}, {"text": "巨大", "is_correct": false, "explanation": "体貌：「巨大」说体形大，不用来形容自行车的价钱或档次，与句意不符。"}, {"text": "精密", "is_correct": false, "explanation": "搭配：「精密」多用于仪器、机械的精度，说自行车「精密」不自然，且与「只能买得起」不符。"}], "explanations": {"廉价": "正确：「只能买得起」说明自行车价钱低，修饰自行车的「廉价」最合适。", "高档": "语义：「高档」指档次高、价钱贵，与「只能买得起」矛盾。", "巨大": "体貌：「巨大」说体形大，不用来形容自行车的价钱或档次，与句意不符。", "精密": "搭配：「精密」多用于仪器、机械的精度，说自行车「精密」不自然，且与「只能买得起」不符。"}, "sentence_index": 6, "correct_answer": "廉价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病情很廉价，医生说要马上住院。", "explanation": "这里应该用〈严重〉。严重形容病情、问题的程度；廉价只形容价钱低的东西，不用于病情。"}, {"text": "这座山很廉价，爬上去要两个小时。", "explanation": "这里应该用〈高〉。廉价只形容价钱低的东西，不能用来形容山的高度。"}, {"text": "书架上的书摆得很廉价，找书很麻烦。", "explanation": "这里应该用〈整齐〉。整齐形容摆放有条理；廉价只形容价钱低的东西，不能用来说书的摆放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一把廉价的鞋，只花了十五块。", "corrected_sentence": "我买了一双廉价的鞋，只花了十五块。", "error_description": "量词错误：「鞋」应搭配量词「双」，不能用「把」。正确说法是「一双廉价的鞋」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在网上廉价的买到了一台旧电脑。", "corrected_sentence": "他在网上廉价地买到了一台旧电脑。", "error_description": "错误在于「廉价」修饰动词「买到」时要用「地」，不能用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
