INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26380, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容东西非常多，一直拿也拿不完。", "primary_collocate": null, "pronunciation": "qǔ zhī bù jìn", "ipa": "tɕʰy˨˩˦ ʈʂɻ̩˥ pu˥˩ tɕin˥˩", "syllable_count": 4, "sentences": [{"text": "这个湖里的水取之不尽。", "target_word": "取之不尽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的口袋里好像有取之不尽的糖。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水多得取之不尽。", "target_word": "取之不尽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷的故事取之不尽，我听不完。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片沙滩上的沙子取之不尽。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的野果取之不尽，我们吃不完。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个仓库里的米取之不尽，不用担心不够吃。", "target_word": "取之不尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳的光取之不尽，每天都有。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的零食好像取之不尽，怎么拿都拿不完。", "target_word": "取之不尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里的鱼取之不尽，爷爷每天都能钓到很多。", "target_word": "取之不尽", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取之不尽的", "label": "定语形式"}, {"form": "取之不尽，用之不竭", "label": "固定搭配"}], "register": "中性", "sense_fingerprint": "东西多得一直拿也拿不完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取之不尽", "is_correct": true, "explanation": "正确：湖水多得一直取也取不完，符合“东西非常多”的意思。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：水不是坚硬的物质，与“湖里的水”的属性相冲突。"}, {"text": "方正", "is_correct": false, "explanation": "语义：水没有方正的形状，与“湖里的水”不合。"}, {"text": "生动", "is_correct": false, "explanation": "搭配：“生动”形容文字或描写，不能修饰“湖里的水”。"}], "explanations": {"取之不尽": "正确：湖水多得一直取也取不完，符合“东西非常多”的意思。", "坚硬": "语义：水不是坚硬的物质，与“湖里的水”的属性相冲突。", "方正": "语义：水没有方正的形状，与“湖里的水”不合。", "生动": "搭配：“生动”形容文字或描写，不能修饰“湖里的水”。"}, "sentence_index": 0, "correct_answer": "取之不尽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的怒气取之不尽。", "explanation": "这里应该用〈怒不可遏〉。取之不尽形容东西多、拿不完，不用于情绪；怒气极大应说“怒不可遏”。"}, {"text": "他的脾气取之不尽。", "explanation": "这里应该用〈暴躁〉。取之不尽只形容资源丰富，不用于形容性格或脾气。"}, {"text": "这个班的同学取之不尽。", "explanation": "这里应该用〈很多〉。取之不尽形容物资，指人数多时不说“取之不尽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取之不尽", "is_correct": true, "explanation": "正确：仓库里的米用不完，才能不担心不够吃。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：米稀少与“不用担心不够吃”相矛盾。"}, {"text": "冷淡", "is_correct": false, "explanation": "搭配：“冷淡”形容人的态度，不能修饰“米”。"}, {"text": "呆板", "is_correct": false, "explanation": "搭配：“呆板”形容风格或表情，不能修饰“米”。"}], "explanations": {"取之不尽": "正确：仓库里的米用不完，才能不担心不够吃。", "稀少": "语义：米稀少与“不用担心不够吃”相矛盾。", "冷淡": "搭配：“冷淡”形容人的态度，不能修饰“米”。", "呆板": "搭配：“呆板”形容风格或表情，不能修饰“米”。"}, "sentence_index": 6, "correct_answer": "取之不尽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的失误取之不尽。", "explanation": "这里应该用〈接连不断〉。取之不尽形容东西多、拿不完，不用于错误；错误接连出现应说“接连不断”。"}, {"text": "最近的天气取之不尽。", "explanation": "这里应该用〈阴晴不定〉。取之不尽形容东西多、拿不完，天气不是可以一直拿的东西，应说“阴晴不定”。"}, {"text": "这里的疾病取之不尽。", "explanation": "这里应该用〈比比皆是〉。取之不尽形容东西多、拿不完，不用于疾病这类负面的事；说疾病很多应说“比比皆是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山谷里有取之不尽泉水。", "corrected_sentence": "山谷里有取之不尽的泉水。", "error_description": "错误形式：“取之不尽泉水”，漏掉定语标记“的”。正确形式：“取之不尽的泉水”。取之不尽作定语修饰名词时必须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片草场的牧草很取之不尽，羊群吃不完。", "corrected_sentence": "这片草场的牧草取之不尽，羊群吃不完。", "error_description": "错误形式：“很取之不尽”，给取之不尽加了程度副词“很”。正确形式：“取之不尽”直接作谓语，不加“很”。取之不尽是四字格，一般不接“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
