INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26398, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经济学是教人们怎样用钱和东西来让生活变得更好的学问。", "primary_collocate": null, "pronunciation": "jīng jì xué", "ipa": "tɕiŋ˥ tɕi˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "经济学能帮我们想一想怎么花钱。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，经济学可以让家里过得更好。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想选一门经济学课。", "target_word": "经济学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学经济学的人会算一笔账。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济学课上，老师用苹果做例子。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爸爸教过经济学，懂很多省钱的办法。", "target_word": "经济学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学过经济学以后，她买东西不乱花钱了。", "target_word": "经济学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本经济学书用小故事讲生活里的钱。", "target_word": "经济学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学不只是数字，也是生活的学问。", "target_word": "经济学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对经济学很感兴趣，所以每天看新闻。", "target_word": "经济学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "经济学：教人合理用钱和物、让生活更好的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cad2001-2aa4-4510-ac23-f965c31811d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济学", "is_correct": true, "explanation": "“经济学”是教人合理用钱和物、让生活更好的学问，能帮人想怎么花钱。"}, {"text": "植物学", "is_correct": false, "explanation": "语义：“植物学”研究植物，与“怎么花钱”无关。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：“天文学”研究天体，与“花钱”无关，句子不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”作主语，不宜用于“能帮我们想一想怎么花钱”这类表达。"}], "explanations": {"经济学": "“经济学”是教人合理用钱和物、让生活更好的学问，能帮人想怎么花钱。", "植物学": "语义：“植物学”研究植物，与“怎么花钱”无关。", "天文学": "语义：“天文学”研究天体，与“花钱”无关，句子不通。", "烹饪": "搭配：“烹饪”作主语，不宜用于“能帮我们想一想怎么花钱”这类表达。"}, "sentence_index": 0, "correct_answer": "经济学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的经济学比较困难。", "explanation": "这里应该用〈经济〉。“经济学”是学科名，说家里的情况要用“经济”。"}, {"text": "这个村子的经济学越来越发达。", "explanation": "这里应该用〈经济〉。“经济学”是学科名，说村子的经济发展要用“经济”。"}, {"text": "他读了三块经济学。", "explanation": "这里应该用〈门〉。“经济学”作学科时量词用“门”，不用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济学", "is_correct": true, "explanation": "“学过经济学”之后“不乱花钱”，学的内容与买东西的语境直接相关。"}, {"text": "美术", "is_correct": false, "explanation": "语义：学美术与“买东西不乱花钱”的语境无关，句子的因果不成立。"}, {"text": "园艺", "is_correct": false, "explanation": "搭配：“学过园艺”之后说“买东西不乱花钱”不通顺，两者没有搭配关系。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法不涉及金钱管理，与“不乱花钱”脱节。"}], "explanations": {"经济学": "“学过经济学”之后“不乱花钱”，学的内容与买东西的语境直接相关。", "美术": "语义：学美术与“买东西不乱花钱”的语境无关，句子的因果不成立。", "园艺": "搭配：“学过园艺”之后说“买东西不乱花钱”不通顺，两者没有搭配关系。", "书法": "语义：书法不涉及金钱管理，与“不乱花钱”脱节。"}, "sentence_index": 6, "correct_answer": "经济学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位经济学很有名，经常上电视。", "explanation": "这里应该用〈经济学家〉。“经济学”是学科名，指人时要说“经济学家”。"}, {"text": "这个城市今年的经济学形势很好。", "explanation": "这里应该用〈经济〉。“经济学”是学科名，说城市的经济形势要用“经济”。"}, {"text": "老师给我们讲了一把经济学。", "explanation": "“经济学”作学科时不用“把”作量词，这里的量词与它不搭，用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学一位经济学，学会怎么省钱。", "corrected_sentence": "我想学一门经济学，学会怎么省钱。", "error_description": "量词错误：“经济学”作学科时量词应用“门”，“位”只用于人，此处应改为“一门经济学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈学过经济学过，现在家里的钱管得很好。", "corrected_sentence": "妈妈学过经济学，现在家里的钱管得很好。", "error_description": "“过”表示经历，已紧跟在动词“学”之后，宾语后又多出一个“过”，重复了，应删去，写作“学过经济学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
