INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26402, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体跟着音乐有节奏地动。", "primary_collocate": null, "pronunciation": "lǜ dòng", "ipa": "ly˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们跟着音乐律动起来。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带着小朋友一起律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到快乐的歌，大家都开始律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她闭上眼睛，随着鼓声轻轻律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上我们先律动十分钟，再上课。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宝宝一听到音乐就会律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们在教室里跟着老师律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以跟着节奏自由地律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在草地上随着音乐律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动前先跟着音乐律动一下。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "律动了", "label": "体标"}, {"form": "律动着", "label": "体标"}, {"form": "律动过", "label": "体标"}], "register": "通用", "sense_fingerprint": "身体跟着音乐的节奏动起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f3ad525-ec43-4f5b-948b-9899e9b8bc3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "律动", "is_correct": true, "explanation": "正确：“律动起来”指身体随音乐有节奏地动，与“跟着音乐”的语境吻合。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”是情绪反应，与“跟着音乐”的身体动作不相符，句子说不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”是不自主的生理反应，不能跟着音乐去做。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体的病症，与“跟着音乐”的语境不符。"}], "explanations": {"律动": "正确：“律动起来”指身体随音乐有节奏地动，与“跟着音乐”的语境吻合。", "生气": "语义：“生气”是情绪反应，与“跟着音乐”的身体动作不相符，句子说不通。", "咳嗽": "搭配：“咳嗽”是不自主的生理反应，不能跟着音乐去做。", "发烧": "语义：“发烧”是身体的病症，与“跟着音乐”的语境不符。"}, "sentence_index": 0, "correct_answer": "律动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她冷得浑身不停地律动。", "explanation": "这里应该用〈发抖〉。因寒冷而发抖是不由自主的，律动指跟着音乐有节奏地动，不用于此。"}, {"text": "他在街上律动着回家。", "explanation": "这里应该用〈走〉。律动指跟着音乐有节奏地动，不指一般的行走，不能用来形容走路回家。"}, {"text": "病人突然在床上律动起来。", "explanation": "这里应该用〈抽搐〉。病人的抽搐是不自主的，律动只用于跟随音乐的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "律动", "is_correct": true, "explanation": "正确：“跟着老师律动”指跟着老师的示范做有节奏的身体动作，与“教室里”的语境吻合。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”需要车辆，与“教室里”的场景相矛盾，句子不合理。"}, {"text": "登山", "is_correct": false, "explanation": "语义：“登山”需要到山上去，与“教室里”的场景相矛盾。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“跟着老师”后接的是可以模仿的动作，“感冒”是身体病症，不能跟着做。"}], "explanations": {"律动": "正确：“跟着老师律动”指跟着老师的示范做有节奏的身体动作，与“教室里”的语境吻合。", "驾驶": "语义：“驾驶”需要车辆，与“教室里”的场景相矛盾，句子不合理。", "登山": "语义：“登山”需要到山上去，与“教室里”的场景相矛盾。", "感冒": "搭配：“跟着老师”后接的是可以模仿的动作，“感冒”是身体病症，不能跟着做。"}, "sentence_index": 6, "correct_answer": "律动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一紧张，心脏就不停地律动。", "explanation": "这里应该用〈跳动〉。心脏跳动是不由自主的，律动指跟着音乐有意识地动，不能用于心脏。"}, {"text": "手机在桌上不停地律动。", "explanation": "这里应该用〈抖动〉。手机振动并不跟随音乐的节奏，不能用“律动”。"}, {"text": "醉汉站不稳，身体不停地律动。", "explanation": "这里应该用〈摇晃〉。醉后站不稳的摇晃与音乐无关，律动要求跟着音乐的节奏动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鼓声一响，大家就律动下来了。", "corrected_sentence": "鼓声一响，大家就律动起来了。", "error_description": "“下来”多表示由高到低、停止或安定，与“律动”的开始义不合，且与“鼓声一响”的语境矛盾；应说“律动起来”，表示身体开始随节奏动起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈抱着宝宝，在屋里轻轻律动过。", "corrected_sentence": "妈妈抱着宝宝，在屋里轻轻律动着。", "error_description": "体标错误：描述正在进行的动作应用“着”，“过”表示经历过，不用于此句的当下动作；应说“轻轻律动着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6e82d2d-4454-4c40-a134-3fa37fbde37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26404, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "持久性", "is_correct": true, "explanation": "反义：“持久性”指持续很长时间的特点，与“短暂性”的一小段时间正相反。"}, {"text": "高度", "is_correct": false, "explanation": "无关：“高度”指距离地面或基准面的高低，与时间长短无关。"}, {"text": "宽度", "is_correct": false, "explanation": "无关：“宽度”指物体横向的距离，与时间长短无关。"}, {"text": "面积", "is_correct": false, "explanation": "无关：“面积”指平面的大小，与时间长短无关。"}], "correct_answer": "持久性", "explanations": {"持久性": "反义：“持久性”指持续很长时间的特点，与“短暂性”的一小段时间正相反。", "高度": "无关：“高度”指距离地面或基准面的高低，与时间长短无关。", "宽度": "无关：“宽度”指物体横向的距离，与时间长短无关。", "面积": "无关：“面积”指平面的大小，与时间长短无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26404, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "持久性", "is_correct": true, "explanation": "反义：“持久性”指持续很长时间，与“短暂性”的时间很短正相反。"}, {"text": "密度", "is_correct": false, "explanation": "无关：“密度”指单位体积内的质量，与时间长短无关。"}, {"text": "湿度", "is_correct": false, "explanation": "无关：“湿度”指空气中水分的多少，与时间长短无关。"}, {"text": "亮度", "is_correct": false, "explanation": "无关：“亮度”指光线的明暗程度，与时间长短无关。"}], "correct_answer": "持久性", "explanations": {"持久性": "反义：“持久性”指持续很长时间，与“短暂性”的时间很短正相反。", "密度": "无关：“密度”指单位体积内的质量，与时间长短无关。", "湿度": "无关：“湿度”指空气中水分的多少，与时间长短无关。", "亮度": "无关：“亮度”指光线的明暗程度，与时间长短无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "表示事情只有一小段时间。", "primary_collocate": null, "pronunciation": "duǎn zàn xìng", "ipa": "tuan˨˩˦ tsan˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "夏日阵雨的短暂性，常让人措手不及。", "target_word": "短暂性", "complexity_tier": "T3", "furigana": "xià rì zhèn yǔ de duǎnzàn xìng, cháng ràng rén cuòshǒu bùjí.", "sentence_source": "generated"}, {"text": "假期的短暂性让我难过。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭闹的短暂性，常让大人很快释怀。", "target_word": "短暂性", "complexity_tier": "T3", "furigana": "hái zi kūnào de duǎnzàn xìng, cháng ràng dàrén hěn kuài shìhuái.", "sentence_source": "generated"}, {"text": "日出很美，但它的短暂性让人遗憾。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出的短暂性让人格外珍惜。", "target_word": "短暂性", "complexity_tier": "T3", "furigana": "yǎnchū de duǎnzàn xìng, ràng rén gé wài zhēnxī.", "sentence_source": "generated"}, {"text": "我们常常忽略聚会的短暂性。", "target_word": "短暂性", "complexity_tier": "T3", "furigana": "wǒmen cháng cháng hūlüè jùhuì de duǎnzàn xìng.", "sentence_source": "generated"}, {"text": "医生说这种药的作用具有短暂性。", "target_word": "短暂性", "complexity_tier": "T3", "furigana": "yī shēng shuō zhè zhǒng yào de zuòyòng jùyǒu duǎnzàn xìng.", "sentence_source": "generated"}, {"text": "流星飞得很快，它的短暂性很明显。", "target_word": "短暂性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛的短暂性让观众意犹未尽。", "target_word": "短暂性", "complexity_tier": "T3", "furigana": "zhè chǎng bǐsài de duǎnzàn xìng, ràng guānzhòng yì yóu wèi jìn.", "sentence_source": "generated"}, {"text": "这个游戏的特点就是短暂性，一局只要三分钟。", "target_word": "短暂性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "短暂性：事情只持续一小段时间的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cad2001-2aa4-4510-ac23-f965c31811d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短暂性", "is_correct": true, "explanation": "正确：“短暂性”指事情只持续一小段时间，与“夏日阵雨”的特点相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指物体的色调，与阵雨持续多久无关。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用于饮食，不能与天气现象搭配。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人或动物的形体，不能用来描述天气现象。"}], "explanations": {"短暂性": "正确：“短暂性”指事情只持续一小段时间，与“夏日阵雨”的特点相符。", "颜色": "语义：“颜色”指物体的色调，与阵雨持续多久无关。", "口味": "搭配：“口味”用于饮食，不能与天气现象搭配。", "身材": "体貌：“身材”指人或动物的形体，不能用来描述天气现象。"}, "sentence_index": 0, "correct_answer": "短暂性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根木头的短暂性有一米。", "explanation": "这里的“短暂性”被用来指长度，但它只指事情持续时间很短，不能描述物体的长度。"}, {"text": "我们很快就延长了这次聚会的短暂性。", "explanation": "搭配错误：“短暂性”指时间短的特点，不能被“延长”，要延长的是聚会的时间。"}, {"text": "这辆短暂性让我想起了童年。", "explanation": "量词错误：“辆”用于车辆，“短暂性”是抽象性质，应搭配“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短暂性", "is_correct": true, "explanation": "正确：“短暂性”说作用只持续一小段时间，与“具有”搭配且语义相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指口感或气味，不是药物“作用”的特点。"}, {"text": "形体", "is_correct": false, "explanation": "搭配：“形体”指物体或人的形状，不用来描述“作用”。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”只用于人或动物，不能描述药物的作用。"}], "explanations": {"短暂性": "正确：“短暂性”说作用只持续一小段时间，与“具有”搭配且语义相符。", "味道": "语义：“味道”指口感或气味，不是药物“作用”的特点。", "形体": "搭配：“形体”指物体或人的形状，不用来描述“作用”。", "性别": "语义：“性别”只用于人或动物，不能描述药物的作用。"}, "sentence_index": 6, "correct_answer": "短暂性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的短暂性是九十分钟。", "explanation": "这里应该用〈时长〉。〈短暂性〉只说持续时间短的特点，不用来报告具体的时间数量。"}, {"text": "他想把这次旅行的短暂性拉长一些。", "explanation": "搭配错误：“短暂性”是性质，不能被“拉长”，要拉长的是旅行的时间。"}, {"text": "这首短暂性让我想起了童年。", "explanation": "量词错误：“首”多用于诗歌、歌曲，“短暂性”是抽象性质，应搭配“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很珍惜这次演出短暂性。", "corrected_sentence": "我们很珍惜这次演出的短暂性。", "error_description": "“的”的错误：定语“演出”与中心语“短暂性”之间需要“的”，应说“演出的短暂性”，不说“演出短暂性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场雨很短暂性很明显。", "corrected_sentence": "这场雨的短暂性很明显。", "error_description": "副词错误：“短暂性”是名词，前面不能直接加程度副词“很”。应说“这场雨的短暂性很明显”，或用形容词说“这场雨很短暂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
