INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "极限就是不能再多、不能再大的那个点。", "primary_collocate": null, "pronunciation": "jí xiàn", "ipa": "tɕi˧˥ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个杯子最多装一升水，这就是它的极限。", "target_word": "极限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子装满了，已经到极限了。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气球再吹就会破，它到极限了。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弹簧拉到极限，就不能再长了。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一口气跑到了极限，再也跑不动了。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电梯最多坐十个人，这是极限。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包已经满了，再放一本就超过极限了。", "target_word": "极限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肚子太饱了，真的吃到极限了。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子只能挂十公斤，十公斤就是极限。", "target_word": "极限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水位升到极限，水就要流出来了。", "target_word": "极限", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不能再多、不能再大的那个界限点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07a53c-a9cf-4bf8-a96d-3c0a8dd8e503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "极限", "is_correct": true, "explanation": "正确。“这就是它的极限”指杯子能装水的最大量，与句意一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观色彩，与“能装多少水”的容量无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人或生物，不说杯子的年龄。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指重量，句中讲的是能装多少，与之不符。"}], "explanations": {"极限": "正确。“这就是它的极限”指杯子能装水的最大量，与句意一致。", "颜色": "语义：“颜色”指外观色彩，与“能装多少水”的容量无关。", "年龄": "搭配：“年龄”只用于人或生物，不说杯子的年龄。", "体重": "语义：“体重”指重量，句中讲的是能装多少，与之不符。"}, "sentence_index": 0, "correct_answer": "极限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条线是两块地的极限。", "explanation": "这里应该用〈界限〉。“极限”指能达到的最大程度，划分两块地的分界要说“界限”。"}, {"text": "这幅画的极限在中间的那棵树。", "explanation": "这里应该用〈中心〉。“极限”指不能再多、再大的那个点，不指画面的中心位置，那要说“中心”。"}, {"text": "这次旅行的极限是一张地图。", "explanation": "这里应该用〈地图〉。“极限”指不能再多、再大的那个点，不指地图这样的物品，那要说“地图”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极限", "is_correct": true, "explanation": "正确。“超过极限了”指超过了放置的最大量，与句意一致。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”不是可比较的数量，“超过脾气了”不成立。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：“脸色”指面部的颜色和神情，书包没有脸色，句中说的是装书的最大量。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高矮，与书包能装多少无关。"}], "explanations": {"极限": "正确。“超过极限了”指超过了放置的最大量，与句意一致。", "脾气": "搭配：“脾气”不是可比较的数量，“超过脾气了”不成立。", "脸色": "语义：“脸色”指面部的颜色和神情，书包没有脸色，句中说的是装书的最大量。", "身高": "语义：“身高”指身体的高矮，与书包能装多少无关。"}, "sentence_index": 6, "correct_answer": "极限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场雨的极限是清晨。", "explanation": "这里应该用〈开端〉。“极限”指不能再多、再大的那个点，不指事情开始的时候，那要说“开端”。"}, {"text": "池子的极限长着青苔。", "explanation": "这里应该用〈边缘〉。“极限”指不能再多、再大的那个点，不指物体的边缘，那要说“边缘”。"}, {"text": "这箱水的极限有一层油。", "explanation": "这里应该用〈表面〉。“极限”指不能再多的那个点，不指水的表层，那要说“表面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根绳子的承重已经到了一条极限。", "corrected_sentence": "这根绳子的承重已经到了极限。", "error_description": "错误形式：“到了一条极限”；正确形式：“到了极限”。“极限”是抽象名词，不用“条”计量，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "气球已经吹得极限了。", "corrected_sentence": "气球已经吹到极限了。", "error_description": "错误形式：“吹得极限了”；正确形式：“吹到极限了”。“到”引出动作达到的结果，“得”后面要接描述程度的词语，不能接名词“极限”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
