INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "虽然处境变了，仍然保持某种特点或状态，没有失去。", "primary_collocate": null, "pronunciation": "bù shī", "ipa": "pu˥˩ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "衣服虽然旧了，却不失整洁。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他住在小城，生活不失乐趣。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使很累，她也不失笑容。", "target_word": "不失", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法虽然简单，却不失实用。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他虽然很有名，待人却不失礼节。", "target_word": "不失", "complexity_tier": "T3", "furigana": "tā suīrán hěn yǒumíng, dàirén què bù shī lǐjié", "sentence_source": "generated"}, {"text": "这座老房子经过修理，仍然不失古朴。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大了，对父母不失孝心。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话直接，但不失分寸。", "target_word": "不失", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛很激烈，大家都不失冷静。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿着普通，却不失优雅。", "target_word": "不失", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "不失为", "label": "复合"}], "register": "书面语", "sense_fingerprint": "不失：虽然处境变了，仍然没有失去某种特点或状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cad2001-2aa4-4510-ac23-f965c31811d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26408, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不失", "is_correct": true, "explanation": "bù shī：虽然处境变了，仍然没有失去某种特点或状态，是本题的目标词。"}, {"text": "不知", "is_correct": false, "explanation": "zhī（第一声）与 shī（第一声）声母不同（zh 对 sh），意思是不晓得。"}, {"text": "不吃", "is_correct": false, "explanation": "chī（第一声）与 shī（第一声）声母不同（ch 对 sh），意思是不进食。"}, {"text": "不思", "is_correct": false, "explanation": "sī（第一声）与 shī（第一声）声母不同（s 对 sh），意思是不去想。"}, {"text": "补时", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、shí（第二声）与 shī（第一声）声调都不同，意思是补充的时间。"}, {"text": "不识", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是不认识。"}], "explanations": {"不失": "bù shī：虽然处境变了，仍然没有失去某种特点或状态，是本题的目标词。", "不知": "zhī（第一声）与 shī（第一声）声母不同（zh 对 sh），意思是不晓得。", "不吃": "chī（第一声）与 shī（第一声）声母不同（ch 对 sh），意思是不进食。", "不思": "sī（第一声）与 shī（第一声）声母不同（s 对 sh），意思是不去想。", "补时": "bǔ（第三声）与 bù（第四声）、shí（第二声）与 shī（第一声）声调都不同，意思是补充的时间。", "不识": "shí（第二声）与 shī（第一声）声调不同，意思是不认识。"}, "sentence_index": null, "correct_answer": "不失"}, "level_3": {"options": [{"text": "不失", "is_correct": true, "explanation": "“不失整洁”表示虽然旧了仍保持整洁，与“虽然…却…”相合。"}, {"text": "丢掉", "is_correct": false, "explanation": "搭配：“丢掉”一般接具体物品，不说“丢掉整洁”。"}, {"text": "沾染", "is_correct": false, "explanation": "语义：“沾染”指沾上不好的东西，与“整洁”语义相反，句子不通。"}, {"text": "增添", "is_correct": false, "explanation": "搭配：“增添”多接光彩、麻烦，不说“增添整洁”。"}], "explanations": {"不失": "“不失整洁”表示虽然旧了仍保持整洁，与“虽然…却…”相合。", "丢掉": "搭配：“丢掉”一般接具体物品，不说“丢掉整洁”。", "沾染": "语义：“沾染”指沾上不好的东西，与“整洁”语义相反，句子不通。", "增添": "搭配：“增添”多接光彩、麻烦，不说“增添整洁”。"}, "sentence_index": 0, "correct_answer": "不失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天坚持锻炼，努力不失体重。", "explanation": "这里应该用〈保持〉。“不失”只接特点、品质，体重是数量，不能说“不失体重”。"}, {"text": "会议上大家都不失沉默。", "explanation": "这里应该用〈保持〉。“不失”只接特点、品质，沉默不是特点，不能说“不失沉默”。"}, {"text": "我和同学不失一定的距离。", "explanation": "这里应该用〈保持〉。“不失”只接特点、品质，距离不是特点，不能说“不失距离”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26408, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不失", "is_correct": true, "explanation": "bù shī：虽然处境变了，仍然没有失去某种特点或状态，是本题的目标词。"}, {"text": "不时", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是常常、时常。"}, {"text": "不是", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是否定判断，并非如此。"}, {"text": "不适", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是身体或感觉不舒服。"}, {"text": "不死", "is_correct": false, "explanation": "sǐ（第三声）与 shī（第一声）声母不同（s 对 sh）、声调也不同，意思是不会死亡。"}, {"text": "不使", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，意思是不用、不让。"}], "explanations": {"不失": "bù shī：虽然处境变了，仍然没有失去某种特点或状态，是本题的目标词。", "不时": "shí（第二声）与 shī（第一声）声调不同，意思是常常、时常。", "不是": "shì（第四声）与 shī（第一声）声调不同，意思是否定判断，并非如此。", "不适": "shì（第四声）与 shī（第一声）声调不同，意思是身体或感觉不舒服。", "不死": "sǐ（第三声）与 shī（第一声）声母不同（s 对 sh）、声调也不同，意思是不会死亡。", "不使": "shǐ（第三声）与 shī（第一声）声调不同，意思是不用、不让。"}, "sentence_index": null, "correct_answer": "不失"}, "level_3": {"options": [{"text": "不失", "is_correct": true, "explanation": "“不失孝心”表示孝心仍然保持，与语境中的正面评价相合。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”多接努力、希望，不说“放弃孝心”。"}, {"text": "扔掉", "is_correct": false, "explanation": "语域：“扔掉”口语色彩重，与书面的“不失”不协调；搭配上也不说“扔掉孝心”。"}, {"text": "冷落", "is_correct": false, "explanation": "搭配：“冷落”指怠慢人，不接“孝心”。"}], "explanations": {"不失": "“不失孝心”表示孝心仍然保持，与语境中的正面评价相合。", "放弃": "搭配：“放弃”多接努力、希望，不说“放弃孝心”。", "扔掉": "语域：“扔掉”口语色彩重，与书面的“不失”不协调；搭配上也不说“扔掉孝心”。", "冷落": "搭配：“冷落”指怠慢人，不接“孝心”。"}, "sentence_index": 6, "correct_answer": "不失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个工厂每天不失三百件的产量。", "explanation": "这里应该用〈保持〉。“不失”只接特点、品质，产量是数量，不能说“不失产量”。"}, {"text": "他每天跑步，不失稳定的心率。", "explanation": "这里应该用〈保持〉。“不失”只接特点、品质，心率是生理指标，不能说“不失心率”。"}, {"text": "这块电池不失充足的电量。", "explanation": "这里应该用〈保持〉。“不失”只接特点、品质，电量是数量，不能说“不失电量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他换了新单位，对同事仍不失了善意。", "corrected_sentence": "他换了新单位，对同事仍不失善意。", "error_description": "“不失”表示保持，后面不加“了”，此处多出“了”，应删去，写作“仍不失善意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子虽然工作忙，对父母仍不失了关心。", "corrected_sentence": "孩子虽然工作忙，对父母仍不失关心。", "error_description": "“不失”表示持续保持，后面不加动态助词“了”，此处多出“了”，应删去，写作“仍不失关心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
