INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26416, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "答案就是回答问题的内容。", "primary_collocate": null, "pronunciation": "dá àn", "ipa": "tɑ˧˥ ɑn˥˩", "syllable_count": 2, "sentences": [{"text": "他的答案很短。", "target_word": "答案", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你写下答案。", "target_word": "答案", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不同意你的答案。", "target_word": "答案", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个答案让大家都笑了。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生举手回答，老师说他的答案很好。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有说出答案，只是笑了笑。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "问题很难，每个人的答案都不一样。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把答案写在纸上，然后交给了老师。", "target_word": "答案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听着问题，慢慢想答案。", "target_word": "答案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师读完题目，我们一起说出了答案。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "标准答案", "label": "复合"}, {"form": "正确答案", "label": "复合"}], "register": "中性", "sense_fingerprint": "答案：回答问题时说出或写出的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cad2001-2aa4-4510-ac23-f965c31811d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "答案", "is_correct": true, "explanation": "正确：“答案”可以“很短”，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用长短来形容，“很短”说的是答案的篇幅。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有长短，句中说的是他的回答。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不与“很短”搭配，不能说心情的长短。"}], "explanations": {"答案": "正确：“答案”可以“很短”，句意通顺。", "颜色": "语义：颜色不能用长短来形容，“很短”说的是答案的篇幅。", "天气": "语义：天气没有长短，句中说的是他的回答。", "心情": "搭配：“心情”不与“很短”搭配，不能说心情的长短。"}, "sentence_index": 0, "correct_answer": "答案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼的答案完工了。", "explanation": "这里应该用〈工程〉。答案指对问题的解答，不能完工；建筑的施工进展要用“工程”。"}, {"text": "他的研究答案很大。", "explanation": "这里应该用〈办公室〉。答案是对问题的解答，不能说“很大”；“研究”后接“办公室”才能说“很大”。"}, {"text": "他写了一条答案。", "explanation": "这里应该用〈个〉。答案的量词是“个”；“条”用于细长的东西，不能修饰答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "答案", "is_correct": true, "explanation": "正确：“答案”可以因人而异，与“每个人的……都不一样”相合。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳只有一个，不能说“每个人的太阳”。"}, {"text": "火车", "is_correct": false, "explanation": "语义：句中是问题的解法，火车与问题无关，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“问题很难”无关，句意不通。"}], "explanations": {"答案": "正确：“答案”可以因人而异，与“每个人的……都不一样”相合。", "太阳": "语义：太阳只有一个，不能说“每个人的太阳”。", "火车": "语义：句中是问题的解法，火车与问题无关，句意不通。", "颜色": "语义：颜色与“问题很难”无关，句意不通。"}, "sentence_index": 6, "correct_answer": "答案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察逮捕了答案。", "explanation": "这里应该用〈小偷〉。答案指问题的解答，不能被逮捕；逮捕的对象是人。"}, {"text": "老师打扫了今天的答案。", "explanation": "这里应该用〈教室〉。答案指问题的解答，不能被打扫；清扫的对象是教室等场所。"}, {"text": "他写下了收信答案。", "explanation": "这里应该用〈地址〉。写下收信的位置要用“地址”；答案不能用于收信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直没有出说答案。", "corrected_sentence": "他一直没有说出答案。", "error_description": "语序错误：“说出”是动补结构，不能颠倒成“出说”，应说“没有说出答案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把答案写在纸上着。", "corrected_sentence": "我把答案写在纸上了。", "error_description": "体标错误：“把……写在纸上”表示动作已经完成，应用“了”，不说“写在纸上着”。应说“我把答案写在纸上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '891782f1-0cd2-45c8-abf3-d6c8dbe33ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
