INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很小的虫子。", "primary_collocate": null, "pronunciation": "xiǎo chóng", "ipa": "ɕjɑʊ̯˨˩˦ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "桌子上爬着一只小虫。", "target_word": "小虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很怕小虫，一看见就叫。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小虫掉进了水里，不动了。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草里有很多小虫，别坐在地上。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟用瓶子捉了一只小虫。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，墙上出现了几只小虫。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种小虫只在夜里出来。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狗的身上有小虫，要洗澡了。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的水果上有小虫，不能吃了。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小虫虽然很小，但是它也会飞。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只小虫", "label": "量词（只）"}, {"form": "一条小虫", "label": "量词（条）"}, {"form": "小虫子", "label": "复合"}, {"form": "小蟲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很小的虫子，常见于桌上、墙上、草里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8123548a-3e19-4ed4-b9a2-7a790a83fd3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小虫", "is_correct": true, "explanation": "正确答案：小虫（xiǎo chóng），指很小的虫子。"}, {"text": "小葱", "is_correct": false, "explanation": "chóng 与 cōng 声母不同（ch 与 c）且声调不同，意思是小葱（一种蔬菜）。"}, {"text": "小钟", "is_correct": false, "explanation": "chóng 与 zhōng 声母不同（ch 与 zh）且声调不同，意思是小钟（小型的钟）。"}, {"text": "小城", "is_correct": false, "explanation": "chóng 与 chéng 韵母不同（ong 与 eng），意思是小城（规模较小的城市）。"}, {"text": "小肠", "is_correct": false, "explanation": "chóng 与 cháng 韵母不同（ong 与 ang），意思是小肠（人体消化器官）。"}], "explanations": {"小虫": "正确答案：小虫（xiǎo chóng），指很小的虫子。", "小葱": "chóng 与 cōng 声母不同（ch 与 c）且声调不同，意思是小葱（一种蔬菜）。", "小钟": "chóng 与 zhōng 声母不同（ch 与 zh）且声调不同，意思是小钟（小型的钟）。", "小城": "chóng 与 chéng 韵母不同（ong 与 eng），意思是小城（规模较小的城市）。", "小肠": "chóng 与 cháng 韵母不同（ong 与 ang），意思是小肠（人体消化器官）。"}, "sentence_index": null, "correct_answer": "小虫"}, "level_3": {"options": [{"text": "小虫", "is_correct": true, "explanation": "正确答案：小虫，很小的虫子，能爬上桌子。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体型过大，爬不上桌子。"}, {"text": "老鹰", "is_correct": false, "explanation": "搭配：“爬”不用于老鹰这类飞禽，老鹰应说“飞”。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是大型猛兽，不会爬上桌子。"}], "explanations": {"小虫": "正确答案：小虫，很小的虫子，能爬上桌子。", "大象": "体貌：大象体型过大，爬不上桌子。", "老鹰": "搭配：“爬”不用于老鹰这类飞禽，老鹰应说“飞”。", "老虎": "语义：老虎是大型猛兽，不会爬上桌子。"}, "sentence_index": 0, "correct_answer": "小虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草里开着一朵小虫。", "explanation": "这里应该用〈只〉。〈朵〉用于花，小虫应说“一只小虫”。"}, {"text": "墙角长着一棵小虫。", "explanation": "这里应该用〈只〉。〈棵〉用于树和植物，小虫应说“一只小虫”。"}, {"text": "桌子上停着一张小虫。", "explanation": "这里应该用〈只〉。〈张〉用于纸、桌子等扁平的东西，小虫应说“一只小虫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小虫", "is_correct": true, "explanation": "正确答案：小虫，夜里出来活动，与“这种”相符。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是家用电器，不会在夜里自己出来，句意不通。"}, {"text": "文件", "is_correct": false, "explanation": "搭配：“出来”不与“文件”搭配，文件不会在夜里出来。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳在白天出现，不会只在夜里出来。"}], "explanations": {"小虫": "正确答案：小虫，夜里出来活动，与“这种”相符。", "电视": "语义：电视是家用电器，不会在夜里自己出来，句意不通。", "文件": "搭配：“出来”不与“文件”搭配，文件不会在夜里出来。", "太阳": "语义：太阳在白天出现，不会只在夜里出来。"}, "sentence_index": 6, "correct_answer": "小虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小虫很大，比一头大象还大。", "explanation": "这里应该用〈大动物〉。小虫指很小的虫子，不能说比大象还大。"}, {"text": "这只小虫长得比房子还高。", "explanation": "这里应该用〈大树〉。小虫很小，不会长得比房子还高，这样形容的是大树。"}, {"text": "院子里种了小虫。", "explanation": "这里应该用〈树苗〉。虫子不能种，种的是树苗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙角有一张小虫在爬。", "corrected_sentence": "墙角有一只小虫在爬。", "error_description": "量词用错：“小虫”应说“一只小虫”，不能说“一张小虫”。“张”多用于纸张、桌子等扁平的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我被把小虫放进了盒子里。", "corrected_sentence": "我把小虫放进了盒子里。", "error_description": "句式错误：“被”与“把”不能同时使用，只能选其一。应说“我把小虫放进了盒子里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b03b1562-f0df-42e4-acf2-3e76a28c8050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
