INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自己心里想做的事。", "primary_collocate": null, "pronunciation": "zhì yuàn", "ipa": "ʈʂɨ˥˩ yɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我的志愿是当老师。", "target_word": "志愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小的志愿就是开飞机。", "target_word": "志愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小的志愿是成为一名画家。", "target_word": "志愿", "complexity_tier": "T3", "furigana": "zhì yuàn", "sentence_source": "generated"}, {"text": "你的志愿是什么？我想听听。", "target_word": "志愿", "complexity_tier": "T3", "furigana": "zhì yuàn", "sentence_source": "generated"}, {"text": "她的志愿很简单，就是帮助别人。", "target_word": "志愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥的志愿是当医生，现在他做到了。", "target_word": "志愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，他的志愿是当警察。", "target_word": "志愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的志愿，爸爸妈妈知道吗？", "target_word": "志愿", "complexity_tier": "T3", "furigana": "zhì yuàn", "sentence_source": "generated"}, {"text": "老师问我们每个人的志愿是什么。", "target_word": "志愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的志愿都不一样。", "target_word": "志愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第一志愿", "label": "复合"}, {"form": "志愿者", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己心里愿意做、想做的事，如职业或学业的愿望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4246d07b-ae3c-4f25-9405-93e74c5a5c69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "志愿", "is_correct": true, "explanation": "正确：“志愿”指自己心里想做的事，“我的志愿是当老师”成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是人的愿望，“是当老师”说不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“是当老师”的主语须是人的志向，“房间”不能这样搭配。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指性情特点，不能说“是当老师”。"}], "explanations": {"志愿": "正确：“志愿”指自己心里想做的事，“我的志愿是当老师”成立。", "颜色": "语义：“颜色”不是人的愿望，“是当老师”说不通。", "房间": "搭配：“是当老师”的主语须是人的志向，“房间”不能这样搭配。", "性格": "语义：“性格”指性情特点，不能说“是当老师”。"}, "sentence_index": 0, "correct_answer": "志愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个周末的志愿是去爬山。", "explanation": "这里应该用〈安排〉。周末的活动要说安排；志愿指长远想做的事，不用于一次具体的出行。"}, {"text": "这台机器的志愿是提高效率。", "explanation": "这里应该用〈功能〉。志愿指人自己心里想做的事，机器的作用要说功能。"}, {"text": "这次比赛的志愿是拿第一名。", "explanation": "这里应该用〈目标〉。比赛的任务要说目标，“志愿”指个人长远的心愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "志愿", "is_correct": true, "explanation": "正确：“志愿”指自己心里想做的事，“他的志愿是当警察”成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不能说“是当警察”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是数字或时间，与“当警察”的志向无关。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不与“是当警察”搭配，身高不是人想做的事。"}], "explanations": {"志愿": "正确：“志愿”指自己心里想做的事，“他的志愿是当警察”成立。", "脾气": "语义：“脾气”指性情，不能说“是当警察”。", "年龄": "语义：“年龄”是数字或时间，与“当警察”的志向无关。", "身高": "搭配：“身高”不与“是当警察”搭配，身高不是人想做的事。"}, "sentence_index": 6, "correct_answer": "志愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天中午我的志愿是吃面条。", "explanation": "这里应该用〈打算〉。志愿指长远的人生理想，今天中午要做的事要说打算。"}, {"text": "这次旅行的志愿是去北京看故宫。", "explanation": "这里应该用〈计划〉。旅行的安排要说计划，志愿只用于个人长远想做的事。"}, {"text": "老师布置的志愿是写一篇作文。", "explanation": "这里应该用〈任务〉。老师布置的作业要说任务，不说志愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我志愿很简单。", "corrected_sentence": "我的志愿很简单。", "error_description": "“的”缺失：主语与“志愿”之间要加“的”，应说“我的志愿很简单”；“我志愿”会被理解为动词“自愿”，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的志愿成为律师。", "corrected_sentence": "他的志愿是成为律师。", "error_description": "系词缺失：主语“他的志愿”与后面的说明之间要用“是”，应说“他的志愿是成为律师”，不能省去“是”直接说“他的志愿成为律师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
