INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26432, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个人特别想做一件事，不想停下。", "primary_collocate": null, "pronunciation": "zhí zhuó", "ipa": "ʈʂɻ̩˧˥ ʈʂwo˧˥", "syllable_count": 2, "sentences": [{"text": "他对画画很执着。", "target_word": "执着", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明执着地想学会骑自行车。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她太执着了，不管多难都不放弃。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟执着地要买那个玩具。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他执着于打游戏，饭也不想吃。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友很执着，每天都去练习唱歌。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈劝了很久，可他还是那么执着。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她执着地想去北京看升旗。", "target_word": "执着", "complexity_tier": "T3", "furigana": "tā zhízhuó de xiǎng qù Běijīng kàn shēngqí.", "sentence_source": "generated"}, {"text": "他对足球很执着，每天都踢球。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这个人很执着，想做的事一定要做。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "执着地", "label": "状语形式"}, {"form": "执着的", "label": "定语形式"}, {"form": "执著", "label": "异体"}], "register": "中性", "sense_fingerprint": "特别想做某件事而不肯停下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不说“对画画很清脆”。"}, {"text": "执着", "is_correct": true, "explanation": "正确。“执着”指特别想做某件事、不肯停下，与“对画画很”搭配，符合句意。"}, {"text": "健壮", "is_correct": false, "explanation": "语义：“健壮”形容身体，与画画无关，句意不通。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物体的质地，不能用来形容对画画的态度。"}], "explanations": {"清脆": "搭配：“清脆”形容声音，不说“对画画很清脆”。", "执着": "正确。“执着”指特别想做某件事、不肯停下，与“对画画很”搭配，符合句意。", "健壮": "语义：“健壮”形容身体，与画画无关，句意不通。", "坚硬": "搭配：“坚硬”形容物体的质地，不能用来形容对画画的态度。"}, "sentence_index": 0, "correct_answer": "执着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他累了，就执着地休息一会儿。", "explanation": "这里应该用〈放松〉。“执着”表示一心想做某件事、不肯停下，与“累了就休息”的停止相矛盾；想歇一歇应说“放松”。"}, {"text": "他的兴趣很执着，今天画画，明天唱歌。", "explanation": "这里应该用〈善变〉。“执着”指一直想做某件事，不轻易转向；“今天画画，明天唱歌”说明兴趣常变，应用“善变”。"}, {"text": "他很执着，每次做作业做到一半就跑去玩。", "explanation": "这里应该用〈贪玩〉。“执着”表示一心想做某件事、不肯停下，与“做到一半就跑去玩”的中途停止相矛盾；爱玩、做事不专心应说“贪玩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听话", "is_correct": false, "explanation": "语义：“听话”与“劝了很久，可他还是那么……”的转折矛盾，句意不通。"}, {"text": "执着", "is_correct": true, "explanation": "正确。“执着”形容他不肯放弃，与“劝了很久，可他还是那么”的转折相合。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地或身体，不用来形容人的态度。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指地方或气氛冷落，与人的态度无关，句意不通。"}], "explanations": {"听话": "语义：“听话”与“劝了很久，可他还是那么……”的转折矛盾，句意不通。", "执着": "正确。“执着”形容他不肯放弃，与“劝了很久，可他还是那么”的转折相合。", "柔软": "搭配：“柔软”形容质地或身体，不用来形容人的态度。", "冷清": "语义：“冷清”指地方或气氛冷落，与人的态度无关，句意不通。"}, "sentence_index": 6, "correct_answer": "执着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事很执着，随便应付一下就算了。", "explanation": "这里应该用〈敷衍〉。“执着”表示一心想做某件事、不肯罢休，与“随便应付一下就算了”的态度相矛盾。"}, {"text": "他做决定很执着，常常一拖再拖。", "explanation": "这里应该用〈犹豫〉。“执着”表示坚持不放弃，与“一拖再拖”的迟疑相矛盾。"}, {"text": "他对那件事很执着，从不愿意去做。", "explanation": "这里应该用〈不屑〉。“执着”表示特别想做某件事，与“从不愿意去做”的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他执着了地想学会游泳。", "corrected_sentence": "他执着地想学会游泳。", "error_description": "体标错误：“了”不能插在“执着”与状语标记“地”之间，应直接说“执着地想学会游泳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他执着地的要学好英语。", "corrected_sentence": "他执着地要学好英语。", "error_description": "结构助词多余：“地”后不能再接“的”，应直接说“执着地要学好英语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26434, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
