INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小树就是一棵小小的、还没长大的树。", "primary_collocate": null, "pronunciation": "xiǎo shù", "ipa": "ɕjɑʊ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "小树还没有我高。", "target_word": "小树", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河边种着一排小树。", "target_word": "小树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去山上种小树。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风把小树吹弯了。", "target_word": "小树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵小树需要多浇水。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟蹲在小树下面看蚂蚁。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小树长得很快，已经有两米高了。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天很冷，我们给小树包上了草。", "target_word": "小树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门口栽了两棵小树。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小树上挂着一张小卡片。", "target_word": "小树", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "小樹", "label": "繁体"}], "register": "中性", "sense_fingerprint": "还没长大的小树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '576e64ee-f9ee-4e44-b7e0-41b533bdad60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26436, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小树", "is_correct": true, "explanation": "正确答案：小树，指还没长大的小树。"}, {"text": "小暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是二十四节气之一的小暑。"}, {"text": "小叔", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是父亲的弟弟。"}, {"text": "小鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是小老鼠。"}, {"text": "小书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是小本的书。"}], "explanations": {"小树": "正确答案：小树，指还没长大的小树。", "小暑": "shǔ（第三声）与 shù（第四声）声调不同，意思是二十四节气之一的小暑。", "小叔": "shū（第一声）与 shù（第四声）声调不同，意思是父亲的弟弟。", "小鼠": "shǔ（第三声）与 shù（第四声）声调不同，意思是小老鼠。", "小书": "shū（第一声）与 shù（第四声）声调不同，意思是小本的书。"}, "sentence_index": null, "correct_answer": "小树"}, "level_3": {"options": [{"text": "小树", "is_correct": true, "explanation": "正确：“小树”指还没长大的树，与“还没有我高”相符。"}, {"text": "书包", "is_correct": false, "explanation": "体貌：书包没有可以拿来和身高比较的高度，句子无法成立。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑与“还没有我高”的比较没有意义。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能与人比较身高，句子不成立。"}], "explanations": {"小树": "正确：“小树”指还没长大的树，与“还没有我高”相符。", "书包": "体貌：书包没有可以拿来和身高比较的高度，句子无法成立。", "电脑": "语义：电脑与“还没有我高”的比较没有意义。", "月亮": "语义：月亮是天体，不能与人比较身高，句子不成立。"}, "sentence_index": 0, "correct_answer": "小树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小树底下好乘凉。", "explanation": "这里应该用〈大树〉。“大树底下好乘凉”的大树枝叶茂密、能遮阴，小树树冠小，遮不住阴，不能说“小树底下好乘凉”。"}, {"text": "那棵小树已经活了一百年。", "explanation": "这里应该用〈大树〉。小树指还没长大的树，不会活了一百年。"}, {"text": "这棵小树的树干粗得要五个人才能围住。", "explanation": "这里应该用〈大树〉。小树的树干细，要五个人才能围住的树不是小树，应说〈大树〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小树", "is_correct": true, "explanation": "正确：“小树”长得快，两米高，与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会“长得很快”，与句子的生长描述不符。"}, {"text": "房子", "is_correct": false, "explanation": "体貌：房子不会长高，与“已经有两米高了”的描述不符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会生长，与“长得很快”不符。"}], "explanations": {"小树": "正确：“小树”长得快，两米高，与句意相符。", "汽车": "语义：汽车不会“长得很快”，与句子的生长描述不符。", "房子": "体貌：房子不会长高，与“已经有两米高了”的描述不符。", "书": "语义：书不会生长，与“长得很快”不符。"}, "sentence_index": 6, "correct_answer": "小树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵小树粗得要两个人才能抱住。", "explanation": "这里应该用〈老树〉。小树的粗细通常较小，粗得要两人合抱不符合“小树”的意思。"}, {"text": "我家门口有一棵小树，已经高得能碰到二楼的窗户了。", "explanation": "这里应该用〈大树〉。小树还没长大，不会高到够着二楼窗户，这样的高度应说〈大树〉。"}, {"text": "这家超市每天卖很多新鲜的小树，给顾客炒菜吃。", "explanation": "这里应该用〈蔬菜〉。小树是树，不是食材，不能拿来卖或炒着吃，应说〈蔬菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小树长得很快。", "corrected_sentence": "这棵小树长得很快。", "error_description": "量词错误：树要用“棵”，应说“这棵小树”，“只”用于动物等，不能用来数树。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷在院子里种了一棵很小树。", "corrected_sentence": "爷爷在院子里种了一棵小树。", "error_description": "多出了“很”：“一棵小树”中“小”直接修饰名词，不能加“很”；要说“很小的树”才能加“很”，“一棵很小树”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
