INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很小的虫，比如蚂蚁、毛毛虫。", "primary_collocate": null, "pronunciation": "xiǎo chóng zi", "ipa": "ɕjɑʊ˨˩˦ ʈʂʰʊŋ˧˥ tsɹ̩", "syllable_count": 3, "sentences": [{"text": "小虫子在叶子上慢慢爬。", "target_word": "小虫子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蚂蚁是一种很勤劳的小虫子。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外飞来一只小虫子。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说，小虫子多是因为天气热。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在菜里发现了一只小虫子。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小虫子钻进了土里。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，路上出现了很多小虫子。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别怕，这只小虫子不咬人。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "儿子把小虫子放进了小盒子里。", "target_word": "小虫子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡喜欢吃地里的小虫子。", "target_word": "小虫子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "小蟲子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "蚂蚁、毛毛虫一类很小的虫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '576e64ee-f9ee-4e44-b7e0-41b533bdad60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能在叶子上爬，「慢慢爬」只适用于能爬行的生物。"}, {"text": "火柴", "is_correct": false, "explanation": "语义：火柴是用来点火的小物件，不会爬。"}, {"text": "小虫子", "is_correct": true, "explanation": "正确：「小虫子」能在叶子上慢慢爬，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：「爬」不用于建筑物，「房子」与「慢慢爬」不搭配。"}], "explanations": {"汽车": "语义：汽车不能在叶子上爬，「慢慢爬」只适用于能爬行的生物。", "火柴": "语义：火柴是用来点火的小物件，不会爬。", "小虫子": "正确：「小虫子」能在叶子上慢慢爬，符合句意。", "房子": "搭配：「爬」不用于建筑物，「房子」与「慢慢爬」不搭配。"}, "sentence_index": 0, "correct_answer": "小虫子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只小虫子比大象还重，几个人都抬不动它。", "explanation": "这里应该用〈大家伙〉。“小虫子”指很小的虫，比大象还重的东西不符合它的本义。"}, {"text": "我家的小虫子是一只花猫，很爱睡觉。", "explanation": "「小虫子」只指蚂蚁、毛毛虫一类小虫，不能用来称呼猫，这是词义用错。"}, {"text": "我家的花园里长着一排小虫子，高得能碰到屋顶。", "explanation": "这里应该用〈树〉。“小虫子”指很小的虫，高得碰到屋顶的东西不符合它的本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不会出现在路上。"}, {"text": "楼房", "is_correct": false, "explanation": "搭配：「路上出现很多楼房」不成搭配，楼房不会出现在路上。"}, {"text": "小虫子", "is_correct": true, "explanation": "正确：雨后地面湿润，很多小虫子出现在路上，符合句意。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是室内的布料，不会出现在路上。"}], "explanations": {"冰箱": "语义：冰箱是家用电器，不会出现在路上。", "楼房": "搭配：「路上出现很多楼房」不成搭配，楼房不会出现在路上。", "小虫子": "正确：雨后地面湿润，很多小虫子出现在路上，符合句意。", "窗帘": "语义：窗帘是室内的布料，不会出现在路上。"}, "sentence_index": 6, "correct_answer": "小虫子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小虫子比小狗还大，把院子都占满了。", "explanation": "这里应该用〈大家伙〉。“小虫子”指很小的虫，比小狗还大的东西不符合它的本义。"}, {"text": "我家的小虫子是一台收音机，每天播放音乐。", "explanation": "「小虫子」只指小型虫类，这里指收音机，词义用错了。"}, {"text": "这个小虫子比房子还高，把街道都挡住了。", "explanation": "这里应该用〈大楼〉。“小虫子”指很小的虫，比房子还高的东西不符合它的本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上趴着一本小虫子。", "corrected_sentence": "墙上趴着一只小虫子。", "error_description": "量词错误：「小虫子」是动物，应用量词「只」。「本」用于书籍，不能用于小虫子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈看见了一朵小虫子。", "corrected_sentence": "妈妈看见了一只小虫子。", "error_description": "量词错误：“朵”用于花，“小虫子”是动物，应用量词“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
