INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26440, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "和别人一起去某个活动或做某件事。", "primary_collocate": null, "pronunciation": "cān jiā", "ipa": "tsʰan˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "周末我和同学一起参加爬山活动。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎你参加我们的晚会。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都参加了这次旅行。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想参加学校的足球队。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你参加不参加明天的聚餐？", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶也来参加孙子的毕业典礼。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为生病，不能参加比赛了。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没参加过这样的活动。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥正在参加朋友的婚礼。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们都来参加社区的春节活动。", "target_word": "参加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参加了", "label": "体标"}, {"form": "参加过", "label": "体标"}, {"form": "参加者", "label": "复合"}, {"form": "參加", "label": "繁体"}], "register": "中性", "sense_fingerprint": "和其他人一起去做某件事或出席某个活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06416bc7-081c-4962-af33-9fe357ea7f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "正确：参加表示和别人一起去参与某个活动，与“和同学一起”的语境相符。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”的对象是破损的东西，不能与“爬山活动”搭配。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”表示躲开，与“和同学一起”的积极语境不合。"}, {"text": "编写", "is_correct": false, "explanation": "搭配：“编写”的对象是文字或程序，不能与“爬山活动”搭配。"}], "explanations": {"参加": "正确：参加表示和别人一起去参与某个活动，与“和同学一起”的语境相符。", "修补": "搭配：“修补”的对象是破损的东西，不能与“爬山活动”搭配。", "逃避": "语义：“逃避”表示躲开，与“和同学一起”的积极语境不合。", "编写": "搭配：“编写”的对象是文字或程序，不能与“爬山活动”搭配。"}, "sentence_index": 0, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑假我们参加了故宫。", "explanation": "这里应该用〈参观〉。参加用于活动，去看景点应说“参观”，应说“暑假我们参观了故宫”。"}, {"text": "具体内容请参加附录。", "explanation": "这里应该用〈参见〉。参加指加入活动，查阅书中内容要说“参见”。"}, {"text": "他参加了这本书。", "explanation": "这里应该用〈阅读〉。参加指参与活动，读书要说“阅读”，不能用“参加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "正确：参加表示参与比赛，与“因为生病，不能”的语境相符。"}, {"text": "制作", "is_correct": false, "explanation": "搭配：“制作”的对象是物品或节目，不能与“比赛”搭配。"}, {"text": "创作", "is_correct": false, "explanation": "搭配：“创作”的对象是作品，不能与“比赛”搭配。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，与因病不能做事的语境不合。"}], "explanations": {"参加": "正确：参加表示参与比赛，与“因为生病，不能”的语境相符。", "制作": "搭配：“制作”的对象是物品或节目，不能与“比赛”搭配。", "创作": "搭配：“创作”的对象是作品，不能与“比赛”搭配。", "发明": "语义：“发明”指创造新事物，与因病不能做事的语境不合。"}, "sentence_index": 6, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们参加了黄山，玩得很开心。", "explanation": "这里应该用〈游览〉。参加指参与活动，去景点应说“游览”。"}, {"text": "他参加了这次的压力。", "explanation": "这里应该用〈承受〉。压力不是可以参与的活动，应说“承受压力”。"}, {"text": "她参加了一通电话。", "explanation": "这里应该用〈接听〉。参加指参与活动，接电话要用“接听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和同伴一起参加了过一次徒步活动。", "corrected_sentence": "我和同伴一起参加过一次徒步活动。", "error_description": "体标错误：“参加过”已表示经历，“过”前不能再加“了”，应去掉“了”，说“一起参加过一次徒步活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天参加着这个聚会。", "corrected_sentence": "我们明天参加这个聚会。", "error_description": "体标错误：“着”表示动作正在进行，与将来的“明天”矛盾，应去掉“着”，说“明天参加这个聚会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43cf442b-edcd-4fbb-8fe2-05aa0cfce2d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
