INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小树苗就是小小的、刚长出来的树。", "primary_collocate": null, "pronunciation": "xiǎo shù miáo", "ipa": "ɕiau˨˩˦ ʂu˥˩ miau˧˥", "syllable_count": 3, "sentences": [{"text": "公园里新种了很多小树苗。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这棵小树苗只有一米高。", "target_word": "小树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸给小树苗浇了水。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天很冷，我们用布把小树苗包起来。", "target_word": "小树苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树苗刚长出来，叶子还很小。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的小树苗一天比一天高。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个周末都去看那棵小树苗。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片地里有五十棵小树苗。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带我们去山上种小树苗。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小树苗喜欢太阳，也需要水。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "小樹苗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "刚长出来的小树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116786dd-4fc5-43e5-bfd0-d8b11bf324a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小树苗", "is_correct": true, "explanation": "正确：“小树苗”指刚长出来的小树，与“新种了很多”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是植物，“新种了很多冰箱”说不通。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“种”的对象是树苗、植株，不能说种树叶。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：木头不能被种植，“新种了很多木头”说不通。"}], "explanations": {"小树苗": "正确：“小树苗”指刚长出来的小树，与“新种了很多”相符。", "冰箱": "语义：冰箱不是植物，“新种了很多冰箱”说不通。", "树叶": "搭配：“种”的对象是树苗、植株，不能说种树叶。", "木头": "搭配：木头不能被种植，“新种了很多木头”说不通。"}, "sentence_index": 0, "correct_answer": "小树苗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里把小树苗洗干净，准备炒菜。", "explanation": "这里应该用〈豆芽〉。小树苗是树的幼苗，不能拿来炒菜，炒菜用的应该是豆芽。"}, {"text": "稻田里的小树苗长得很快。", "explanation": "这里应该用〈秧苗〉。小树苗指树的幼苗，稻田里长的是水稻，要说“秧苗”。"}, {"text": "这棵小树苗已经有十层楼那么高了。", "explanation": "这里应该用〈大树〉。“小树苗”指刚长出来的小树，已经十层楼高的应该说“大树”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小树苗", "is_correct": true, "explanation": "正确：“小树苗”是树的幼苗，可以被特意去看，与“每个周末都去看那棵”相符。"}, {"text": "手机", "is_correct": false, "explanation": "量词与语义：手机不用“棵”，“那棵手机”不成立，“去看手机”的语境也不通。"}, {"text": "书包", "is_correct": false, "explanation": "量词与语义：书包不是植物，“那棵书包”不成立，周末也不会专程去看它。"}, {"text": "冰箱", "is_correct": false, "explanation": "量词与语义：冰箱不是植物，“那棵冰箱”不成立，周末也不会专程去看它。"}], "explanations": {"小树苗": "正确：“小树苗”是树的幼苗，可以被特意去看，与“每个周末都去看那棵”相符。", "手机": "量词与语义：手机不用“棵”，“那棵手机”不成立，“去看手机”的语境也不通。", "书包": "量词与语义：书包不是植物，“那棵书包”不成立，周末也不会专程去看它。", "冰箱": "量词与语义：冰箱不是植物，“那棵冰箱”不成立，周末也不会专程去看它。"}, "sentence_index": 6, "correct_answer": "小树苗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把小树苗戴在头上参加婚礼。", "explanation": "这里应该用〈花环〉。小树苗是树的幼苗，不能戴在头上，参加婚礼戴的应是鲜花编成的花环。"}, {"text": "他枕着小树苗睡觉。", "explanation": "这里应该用〈枕头〉。小树苗是树的幼苗，不能当枕头用，睡觉要枕着枕头。"}, {"text": "我用小树苗写作业。", "explanation": "这里应该用〈铅笔〉。小树苗不能用来写字，写作业要用铅笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家门口种了一个小树苗。", "corrected_sentence": "我家门口种了一棵小树苗。", "error_description": "量词错误：“小树苗”的量词应用“棵”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵小树苗高长了。", "corrected_sentence": "这棵小树苗长高了。", "error_description": "补语错误：“长高”是动补结构，应说“长高了”，不能说“高长了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
