INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用来装水的桶。", "primary_collocate": null, "pronunciation": "shuǐ tǒng", "ipa": "ʂueɪ̯˨˩˦ tʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他提着一个水桶去河边打水。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明拿着红色的水桶在海边玩沙子。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水桶里的水满了，快关上水龙头。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用水桶接屋顶漏下来的雨水。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个水桶太重了，我一个人提不动。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把水桶放在门口，我来拖地。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水桶里的水倒进了花盆里。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水桶的底有一个小洞，水都漏光了。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶家院子里有两个旧水桶，用来存雨水。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用扁担挑着两只水桶下地浇菜。", "target_word": "水桶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来装水、提水的桶状容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116786dd-4fc5-43e5-bfd0-d8b11bf324a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水桶", "is_correct": true, "explanation": "正确：“水桶”是用来装水的桶，提着它去河边打水最合适。"}, {"text": "篮子", "is_correct": false, "explanation": "语义：篮子不能盛水，提着它去河边打水说不通。"}, {"text": "行李箱", "is_correct": false, "explanation": "语义：行李箱是装衣物的箱子，不能用来盛水打水。"}, {"text": "信封", "is_correct": false, "explanation": "搭配：信封是装信件的，“提着信封打水”不搭配。"}], "explanations": {"水桶": "正确：“水桶”是用来装水的桶，提着它去河边打水最合适。", "篮子": "语义：篮子不能盛水，提着它去河边打水说不通。", "行李箱": "语义：行李箱是装衣物的箱子，不能用来盛水打水。", "信封": "搭配：信封是装信件的，“提着信封打水”不搭配。"}, "sentence_index": 0, "correct_answer": "水桶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把水桶戴在头上，去菜园干活。", "explanation": "这里应该用〈草帽〉。水桶是盛水的器具，不能戴在头上，下地干活戴的应是草帽。"}, {"text": "妈妈用菜刀把水桶切成了小块。", "explanation": "这里应该用〈南瓜〉。水桶是容器，不能切块，切块的应是南瓜之类的食材。"}, {"text": "他骑着水桶去上班。", "explanation": "这里应该用〈自行车〉。水桶不能骑，上班应骑自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水桶", "is_correct": true, "explanation": "正确：“水桶”能盛水，“把水桶里的水倒进花盆里”说得通。"}, {"text": "纸盒", "is_correct": false, "explanation": "语义：纸盒不能盛水，“纸盒里的水”说不通。"}, {"text": "信箱", "is_correct": false, "explanation": "语义：信箱是用来收信件的，不装水，“信箱里的水”不成立。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜是放衣物的，不能盛水，“衣柜里的水”说不通。"}], "explanations": {"水桶": "正确：“水桶”能盛水，“把水桶里的水倒进花盆里”说得通。", "纸盒": "语义：纸盒不能盛水，“纸盒里的水”说不通。", "信箱": "语义：信箱是用来收信件的，不装水，“信箱里的水”不成立。", "衣柜": "语义：衣柜是放衣物的，不能盛水，“衣柜里的水”说不通。"}, "sentence_index": 6, "correct_answer": "水桶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他躺在水桶里泡澡。", "explanation": "这里应该用〈浴缸〉。水桶太小，人躺不进去，泡澡要用浴缸。"}, {"text": "妈妈把牛奶倒进水桶里给宝宝喝。", "explanation": "这里应该用〈奶瓶〉。水桶太大，不能用来给婴儿喂奶，喂奶要用奶瓶。"}, {"text": "我用水桶写作业。", "explanation": "这里应该用〈铅笔〉。水桶不能用来写字，写作业要用铅笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提着一条水桶去菜园浇水。", "corrected_sentence": "他提着一个水桶去菜园浇水。", "error_description": "量词错误：“水桶”应用量词“个”，“条”用于细长的东西，不能用于水桶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶找到了一个旧水桶的。", "corrected_sentence": "奶奶找到了一个旧水桶。", "error_description": "结构错误：“旧水桶”是名词短语，末尾不能多加“的”，应说“一个旧水桶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a042ac0-83c9-468c-8309-cd1ec921210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
