INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26454, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "噪音是让人听了不舒服的声音。", "primary_collocate": null, "pronunciation": "zào yīn", "ipa": "tsɑʊ˥˩ in˥", "syllable_count": 2, "sentences": [{"text": "楼下的噪音吵得我睡不好。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的空调几乎没有噪音。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室外面的噪音让学生听不清老师说话。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅很安静，没有什么噪音。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车的噪音在夜里特别明显。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在图书馆学习，因为那里没有噪音。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在走廊里玩，发出了很大的噪音。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人用耳机来挡住噪音。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "装修的噪音从早上八点就开始了。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减少噪音，他们在窗户上装了厚玻璃。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵噪音", "label": "量词"}], "register": "中性", "sense_fingerprint": "让人听了不舒服的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405dfc4a-6ee0-42e9-8dd9-f58f27602e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噪音", "is_correct": true, "explanation": "正确：噪音是让人听了不舒服的声音，能够“吵”人。"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：“吵”用于声音，灯光不能说“吵”，句义不通。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味属于嗅觉对象，与“吵”的听觉含义不合。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：温度不能“吵”人，“吵得我睡不好”的说法不成立。"}], "explanations": {"噪音": "正确：噪音是让人听了不舒服的声音，能够“吵”人。", "灯光": "搭配：“吵”用于声音，灯光不能说“吵”，句义不通。", "气味": "语义：气味属于嗅觉对象，与“吵”的听觉含义不合。", "温度": "搭配：温度不能“吵”人，“吵得我睡不好”的说法不成立。"}, "sentence_index": 0, "correct_answer": "噪音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手的噪音很温柔。", "explanation": "这里应该用〈声音〉。噪音让人不舒服，不能用来形容温柔的嗓音。"}, {"text": "远处飘来悠扬的噪音。", "explanation": "这里应该用〈乐声〉。噪音指刺耳杂乱的声音，不能形容悠扬的乐声。"}, {"text": "这架钢琴的噪音很悦耳。", "explanation": "这里应该用〈音色〉。噪音令人不适，不能用来评价悦耳的音色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "噪音", "is_correct": true, "explanation": "正确：“发出很大的噪音”是常见搭配，噪音是可以被发出的声音。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高不能被“发出”，与“很大的”搭配也不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“发出”不能与“体重”搭配，句义不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会被“发出”，句子读来不通。"}], "explanations": {"噪音": "正确：“发出很大的噪音”是常见搭配，噪音是可以被发出的声音。", "身高": "体貌：身高不能被“发出”，与“很大的”搭配也不通。", "体重": "搭配：“发出”不能与“体重”搭配，句义不通。", "年龄": "语义：年龄不会被“发出”，句子读来不通。"}, "sentence_index": 6, "correct_answer": "噪音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们发出爽朗的噪音。", "explanation": "这里应该用〈笑声〉。噪音令人不适，不能形容爽朗的笑声。"}, {"text": "观众送上热烈的噪音。", "explanation": "这里应该用〈掌声〉。噪音指杂乱刺耳的声音，不能用来形容热烈的掌声。"}, {"text": "教堂传来庄严的噪音。", "explanation": "这里应该用〈钟声〉。噪音让人不舒服，不能形容庄严的钟声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上楼下传来一噪音。", "corrected_sentence": "晚上楼下传来一阵噪音。", "error_description": "量词缺失：噪音前要加量词“阵”，应说“一阵噪音”，不能直接说“一噪音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里传来一块噪音。", "corrected_sentence": "屋里传来一阵噪音。", "error_description": "量词错误：噪音应用“阵”来计量，“块”不能用于噪音，应说“一阵噪音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26456, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难看", "is_correct": true, "explanation": "正确：“难看”与“漂亮”（好看）是反义词，指外表不好看。"}, {"text": "冷静", "is_correct": false, "explanation": "非反义：“冷静”形容态度或性格，与“漂亮”的外表义无关。"}, {"text": "宽敞", "is_correct": false, "explanation": "非反义：“宽敞”说空间大，与“漂亮”的外表义不相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "非反义：“陡峭”形容山坡等地形，与“漂亮”不构成反义。"}], "correct_answer": "难看", "explanations": {"难看": "正确：“难看”与“漂亮”（好看）是反义词，指外表不好看。", "冷静": "非反义：“冷静”形容态度或性格，与“漂亮”的外表义无关。", "宽敞": "非反义：“宽敞”说空间大，与“漂亮”的外表义不相对。", "陡峭": "非反义：“陡峭”形容山坡等地形，与“漂亮”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26456, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“漂亮”（好看）是反义词，指外表不好看。"}, {"text": "勇敢", "is_correct": false, "explanation": "非反义：“勇敢”说性格，与“漂亮”的外表义无关。"}, {"text": "沉重", "is_correct": false, "explanation": "非反义：“沉重”说重量或心情，与“漂亮”不构成反义。"}, {"text": "清醒", "is_correct": false, "explanation": "非反义：“清醒”说头脑状态，与“漂亮”的外表义无关。"}], "correct_answer": "丑", "explanations": {"丑": "正确：“丑”与“漂亮”（好看）是反义词，指外表不好看。", "勇敢": "非反义：“勇敢”说性格，与“漂亮”的外表义无关。", "沉重": "非反义：“沉重”说重量或心情，与“漂亮”不构成反义。", "清醒": "非反义：“清醒”说头脑状态，与“漂亮”的外表义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26456, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很好看，让人喜欢。", "primary_collocate": null, "pronunciation": "piào liang", "ipa": "pʰiɑʊ˥˩ liɑŋ", "syllable_count": 2, "sentences": [{"text": "那个小女孩长得很漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条红裙子漂亮极了。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天的山谷里有很多漂亮的花。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的字写得又快又漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的杯子很漂亮，我特别喜欢。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小鸟的羽毛真漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一个漂亮的本子写日记。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外的月亮又大又圆，真漂亮。", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你今天打扮得真漂亮！", "target_word": "漂亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她画的画儿很漂亮，老师夸了她。", "target_word": "漂亮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "漂漂亮亮", "label": "重叠"}], "register": "口语", "sense_fingerprint": "外表很好看，让人喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405dfc4a-6ee0-42e9-8dd9-f58f27602e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": true, "explanation": "正确：“长得很漂亮”说外貌好看，符合句意。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容环境或物品，不用来形容人的外貌，“长得很潮湿”不成立。"}, {"text": "勤快", "is_correct": false, "explanation": "搭配：“长得”后面不接“勤快”这类形容做事态度的词。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”形容品性，不说外貌，“长得很懒惰”不成立。"}], "explanations": {"漂亮": "正确：“长得很漂亮”说外貌好看，符合句意。", "潮湿": "语义：“潮湿”形容环境或物品，不用来形容人的外貌，“长得很潮湿”不成立。", "勤快": "搭配：“长得”后面不接“勤快”这类形容做事态度的词。", "懒惰": "语义：“懒惰”形容品性，不说外貌，“长得很懒惰”不成立。"}, "sentence_index": 0, "correct_answer": "漂亮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她有一颗漂亮的心灵。", "explanation": "这里应该用〈美丽〉。“漂亮”多指外表，形容心灵这类抽象的美要用“美丽”。"}, {"text": "他的人格很漂亮。", "explanation": "这里应该用〈高尚〉。“漂亮”形容外表，人格是道德品质，要用“高尚”。"}, {"text": "这块饼干的味道很漂亮。", "explanation": "这里应该用〈好吃〉。“漂亮”形容外表好看，形容饼干的味道要用“好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漂亮", "is_correct": true, "explanation": "正确：“漂亮的本子”说本子外观好看，符合想找本子写日记的语境。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或体积很大的东西，不说“高大的本子”。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”说的是心情，不能用来形容本子。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”说温度，与本子无关，“寒冷的本子”不成立。"}], "explanations": {"漂亮": "正确：“漂亮的本子”说本子外观好看，符合想找本子写日记的语境。", "高大": "搭配：“高大”形容人或体积很大的东西，不说“高大的本子”。", "悲伤": "语义：“悲伤”说的是心情，不能用来形容本子。", "寒冷": "语义：“寒冷”说温度，与本子无关，“寒冷的本子”不成立。"}, "sentence_index": 6, "correct_answer": "漂亮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的性格很漂亮。", "explanation": "这里应该用〈温柔〉。“漂亮”形容外表，形容性格要用“温柔”等词。"}, {"text": "这位老人的心肠很漂亮。", "explanation": "这里应该用〈善良〉。“漂亮”形容外表，形容心肠、品性要用“善良”。"}, {"text": "这家店的房租很漂亮。", "explanation": "这里应该用〈便宜〉。“漂亮”形容外表好看，形容房租的高低要用“便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小猫长很漂亮。", "corrected_sentence": "这只小猫长得很漂亮。", "error_description": "错误：“长很漂亮”；正确：“长得很漂亮”。“长”后面要用“得”引出补语“很漂亮”，少了“得”句子就不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她买了一个很漂亮本子。", "corrected_sentence": "她买了一个很漂亮的本子。", "error_description": "错误：“很漂亮本子”；正确：“很漂亮的本子”。“很漂亮”修饰名词时，后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25f006cb-5b59-4041-be28-5e9b648439a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
