INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26458, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回到以前的状态或样子。", "primary_collocate": null, "pronunciation": "huī fù", "ipa": "xweɪ˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "休息几天后，他的身体恢复了。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机坏了，师傅帮我恢复了里面的照片。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了三天雨，路上的交通终于恢复了。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，需要慢慢恢复。", "target_word": "恢复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话线修好后，网络很快恢复了。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，她的力气慢慢恢复了。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪过后，学校恢复上课了。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子已经恢复成以前的样子。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤以后，一个月就恢复了健康。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停了一天电，今天晚上恢复正常了。", "target_word": "恢复", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恢复了", "label": "体标（了）"}, {"form": "恢复过", "label": "体标（过）"}, {"form": "恢复期", "label": "复合"}], "register": "中性", "sense_fingerprint": "回到原来的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生长", "is_correct": false, "explanation": "语义：成年人的身体已经定型，休息后不说“生长”。"}, {"text": "恢复", "is_correct": true, "explanation": "恢复指回到原来的状态，与休息后身体变好的语境相符。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：“锻炼”要求人作主语、身体作宾语，“身体锻炼了”不能成立。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：损坏表示变差，与休息后的好转相矛盾。"}], "explanations": {"生长": "语义：成年人的身体已经定型，休息后不说“生长”。", "恢复": "恢复指回到原来的状态，与休息后身体变好的语境相符。", "锻炼": "搭配：“锻炼”要求人作主语、身体作宾语，“身体锻炼了”不能成立。", "损坏": "语义：损坏表示变差，与休息后的好转相矛盾。"}, "sentence_index": 0, "correct_answer": "恢复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家刚买的新房子已经恢复了。", "explanation": "这里应该说〈建成〉。恢复指回到原来的状态，新房子没有原来的样子，不能说恢复。"}, {"text": "他来到新城市后很快恢复了新朋友。", "explanation": "这里应该用〈结交〉。结交朋友要用〈结交〉，「恢复」指回到原来的状态，不能说“恢复新朋友”。"}, {"text": "他终于恢复了那件事。", "explanation": "这里应该用〈想起〉。回想起记忆中的事情要用〈想起〉，恢复指状态回到原样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延长", "is_correct": false, "explanation": "配价：“延长”的宾语是时间或期限，不能直接接“上课”。"}, {"text": "恢复", "is_correct": true, "explanation": "恢复指回到原来的状态，此处指学校回到正常上课的状态，与大雪过后的语境相符。"}, {"text": "中断", "is_correct": false, "explanation": "语义：中断表示停止，与大雪过后恢复上课的语境相反。"}, {"text": "取消", "is_correct": false, "explanation": "语义：取消表示不再进行，与大雪过后恢复上课的语境相反。"}], "explanations": {"延长": "配价：“延长”的宾语是时间或期限，不能直接接“上课”。", "恢复": "恢复指回到原来的状态，此处指学校回到正常上课的状态，与大雪过后的语境相符。", "中断": "语义：中断表示停止，与大雪过后恢复上课的语境相反。", "取消": "语义：取消表示不再进行，与大雪过后恢复上课的语境相反。"}, "sentence_index": 6, "correct_answer": "恢复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他恢复了欠朋友的钱。", "explanation": "这里应该用〈还〉。还钱要说〈还〉或〈还清〉，「恢复」指状态回到原样，不能用于还钱。"}, {"text": "他的工资恢复了三倍。", "explanation": "这里应该用〈涨〉。工资数额上升要说〈涨〉，「恢复」指回到原来的状态，不能表示倍数增加。"}, {"text": "他终于恢复了丢失的钱包。", "explanation": "这里应该用〈找回〉。丢失的物品被拿回来要用〈找回〉，恢复指状态回到原样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的身体恢复地很快。", "corrected_sentence": "他的身体恢复得很快。", "error_description": "助词错误：状态补语前应用“得”，写成“地”不对（“地”用于修饰动词）。正确：“恢复得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨停后，交通很快恢复的。", "corrected_sentence": "雨停后，交通很快恢复了。", "error_description": "助词错误：动态助词“了”写成了结构助词“的”，“交通很快恢复的”变成了不完整的名词性短语，不能作句子。正确：“交通很快恢复了”，表示已经发生的变化要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
