INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "小时候就是一个人很小的时候。", "primary_collocate": null, "pronunciation": "xiǎo shí hou", "ipa": "ɕjɑʊ˨˩˦ ʂɻ̩˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "我小时候很瘦。", "target_word": "小时候", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她小时候不会游泳。", "target_word": "小时候", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小时候我常常在河边玩。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候他怕黑，晚上要开着灯。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说他小时候没有电视。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候最大的愿望是有一只小狗。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的夏天，我们总是吃西瓜。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候跟外婆住在一起。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈小时候走路去上学。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你小时候也喜欢下雨天吗？", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小時候", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人年纪很小的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d3a53-a647-4a3c-868c-246e143d7708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小时候", "is_correct": true, "explanation": "正确。“小时候”指一个人年纪很小的时候，与“很瘦”描述的童年身形相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来的一天，不能说明一个人过去年幼时的身形。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”指片刻之前，不能与“很瘦”这种长期的身形状态搭配。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：“半夜”指一个具体的夜间时段，不能用来说明一个人长期的身形。"}], "explanations": {"小时候": "正确。“小时候”指一个人年纪很小的时候，与“很瘦”描述的童年身形相符。", "明天": "语义：“明天”指将来的一天，不能说明一个人过去年幼时的身形。", "刚才": "搭配：“刚才”指片刻之前，不能与“很瘦”这种长期的身形状态搭配。", "半夜": "语义：“半夜”指一个具体的夜间时段，不能用来说明一个人长期的身形。"}, "sentence_index": 0, "correct_answer": "小时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小时候在北京读研究生。", "explanation": "这里应该用〈以前〉。“小时候”只指童年，不能用来说成年后读研究生的经历；“以前”可泛指任何过去的时期。"}, {"text": "你等我小时候，我就回来。", "explanation": "“小时候”指童年，不表示一小段时间。这句把它当成了“很快”的意思，与句意不符。"}, {"text": "我小时候明天要考试。", "explanation": "这里应该用〈将来〉。“小时候”只指过去的童年，不能与“明天”这样的将来时间搭配；〈将来〉才泛指将来的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小时候", "is_correct": true, "explanation": "正确。“小时候”指童年，与“夏天”“总是吃西瓜”的过去习惯相符。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指一周前的一段时间，与“夏天”这一季节不相符。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与句中的“夏天”冲突，“冬天的夏天”说不通，不能填入此处。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“昨天”指具体的一天，不能与“夏天”这样的季节搭配。"}], "explanations": {"小时候": "正确。“小时候”指童年，与“夏天”“总是吃西瓜”的过去习惯相符。", "上周": "语义：“上周”指一周前的一段时间，与“夏天”这一季节不相符。", "冬天": "语义：“冬天”与句中的“夏天”冲突，“冬天的夏天”说不通，不能填入此处。", "昨天": "搭配：“昨天”指具体的一天，不能与“夏天”这样的季节搭配。"}, "sentence_index": 6, "correct_answer": "小时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小时候是我的弟弟。", "explanation": "这里应该用〈孩子〉。〈小时候〉表示童年这段时间，不能指人；〈孩子〉才是指人的名词。"}, {"text": "爸爸把小时候装进了箱子。", "explanation": "这里应该用〈玩具〉之类的物品。〈小时候〉是时间，不能被“装”进箱子，应说“爸爸把玩具装进了箱子”。"}, {"text": "吃完饭以后，小时候就出门散步了。", "explanation": "这里应该用〈接着〉。〈小时候〉指童年，不能指吃完饭之后的当下时刻；〈接着〉才表示紧接着的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候的喜欢画画。", "corrected_sentence": "我小时候喜欢画画。", "error_description": "“小时候”是时间状语，后面不能直接加“的”再接动词，“的”应去掉；正确说法是“我小时候喜欢画画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候了常常去河边。", "corrected_sentence": "我小时候常常去河边。", "error_description": "“小时候”是时间词，后面不能直接加“了”，“了”应去掉；正确说法是“我小时候常常去河边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
