INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空着的地方，没有房子。", "primary_collocate": null, "pronunciation": "kòng dì", "ipa": "kʰʊŋ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "村子旁边有一大片空地。", "target_word": "空地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在空地上放风筝。", "target_word": "空地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里没有房子，只有一块空地。", "target_word": "空地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在空地上搭了一个小帐篷。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在了楼旁边的空地上。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面那块空地是谁的？", "target_word": "空地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，空地上长满了小草。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们找了一块空地，在那儿野餐。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空地很安静，没有人也没有车。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带我去空地学骑自行车。", "target_word": "空地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "没有房子的空着的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d3a53-a647-4a3c-868c-246e143d7708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空地", "is_correct": true, "explanation": "空地：没有房子的地面，村子旁边的一大片空地，符合语境。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能铺成村子旁边的一大片。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能成为一大片地方，与语境冲突。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：“村子旁边”是地点，不能说一大片纸在那里。"}], "explanations": {"空地": "空地：没有房子的地面，村子旁边的一大片空地，符合语境。", "面包": "语义：面包是食物，不能铺成村子旁边的一大片。", "蛋糕": "语义：蛋糕是食物，不能成为一大片地方，与语境冲突。", "纸": "搭配：“村子旁边”是地点，不能说一大片纸在那里。"}, "sentence_index": 0, "correct_answer": "空地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车厢里还有一块空地，您可以坐那儿。", "explanation": "这里应该用〈空位〉。空地指户外地面，车厢里没人坐的座位要说空位。"}, {"text": "我在纸的下面留了一块空地。", "explanation": "这里应该用〈空白〉。纸上留出的空处要说空白，空地只指户外的地面。"}, {"text": "表格里还有一块空地，请您填写名字。", "explanation": "这里应该用〈空格〉。表格中待填写的格子要说空格，空地不能指表格里的格子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空地", "is_correct": true, "explanation": "空地：没有房子的地面，春天长满小草，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会从桌面长满小草。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不会长满小草，与语境冲突。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“长满小草”说的是地面，书包不能长草。"}], "explanations": {"空地": "空地：没有房子的地面，春天长满小草，符合语境。", "桌子": "语义：桌子是家具，不会从桌面长满小草。", "冰箱": "语义：冰箱是电器，不会长满小草，与语境冲突。", "书包": "搭配：“长满小草”说的是地面，书包不能长草。"}, "sentence_index": 6, "correct_answer": "空地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这节课和下节课之间有一块空地，正好休息一下。", "explanation": "这里应该用〈空档〉。课与课之间的空余时间要说空档，空地指地面。"}, {"text": "公司的财务部还有一块空地，正在招人。", "explanation": "这里应该用〈空缺〉。职位没人、等待招聘要说空缺，空地不能指职位。"}, {"text": "书架上两本书之间有一块空地。", "explanation": "这里应该用〈空隙〉。两物之间的小缝要说空隙，空地指大片的户外地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在这只空地上装了一个篮球架。", "corrected_sentence": "我们在这块空地上装了一个篮球架。", "error_description": "量词错误：“空地”应该用“块”，不用“只”。改为：这块空地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们把这片空地上放风筝。", "corrected_sentence": "孩子们在这片空地上放风筝。", "error_description": "介词错误：放风筝的地点要用“在……上”，不能用“把”带出空地。改为：在这片空地上放风筝。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f3293ac-da2f-4f2b-9d0a-a9f9e8137453') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
