INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26472, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "植树就是把树苗种到土里，让它长大。", "primary_collocate": null, "pronunciation": "zhí shù", "ipa": "ʈʂɨ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "春天一到，爸爸就带我去山上植树。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树要先挖一个坑，再放进树苗。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎样植树，才能让树苗长得好。", "target_word": "植树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明第一次植树，高兴得睡不着觉。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树以后，每天都要给小树浇水。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里很多人正在植树，场面非常热闹。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说植树是为了让地球更绿。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了植树，他们带来了铲子和水桶。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民们在河边植树，想挡住大风。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树的人越来越多，山变绿了。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "植了树", "label": "体标（了）"}, {"form": "植过树", "label": "体标（过）"}, {"form": "植树节", "label": "复合"}], "register": "中性", "sense_fingerprint": "植树：把树苗种进土里让它长大的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3370b77-fb49-4e42-b46b-5b0a583e1654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26472, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树（zhí shù）：把树苗种进土里让它长大，即本题目标词。"}, {"text": "直属", "is_correct": false, "explanation": "直属（zhí shǔ）第二个音节的声调不同：shǔ 为第三声，shù 为第四声，意思是直接隶属。"}, {"text": "植物", "is_correct": false, "explanation": "植物（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是生物的一类。"}, {"text": "指数", "is_correct": false, "explanation": "指数（zhǐ shù）第一个音节的声调不同：zhǐ 为第三声，zhí 为第二声，意思是表示变化程度的数值。"}], "explanations": {"植树": "植树（zhí shù）：把树苗种进土里让它长大，即本题目标词。", "直属": "直属（zhí shǔ）第二个音节的声调不同：shǔ 为第三声，shù 为第四声，意思是直接隶属。", "植物": "植物（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是生物的一类。", "指数": "指数（zhǐ shù）第一个音节的声调不同：zhǐ 为第三声，zhí 为第二声，意思是表示变化程度的数值。"}, "sentence_index": null, "correct_answer": "植树"}, "level_3": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树：栽种树苗，与“去山上”和“带我”的行程一致。"}, {"text": "滑雪", "is_correct": false, "explanation": "语义：春天一般没有积雪，与“春天一到”的时令冲突。"}, {"text": "堆雪人", "is_correct": false, "explanation": "语义：堆雪人需要积雪，与春天的季节冲突。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割是在庄稼成熟时割取，春天一般不是收割的季节，句中也没有可收割的作物。"}], "explanations": {"植树": "植树：栽种树苗，与“去山上”和“带我”的行程一致。", "滑雪": "语义：春天一般没有积雪，与“春天一到”的时令冲突。", "堆雪人": "语义：堆雪人需要积雪，与春天的季节冲突。", "收割": "语义：收割是在庄稼成熟时割取，春天一般不是收割的季节，句中也没有可收割的作物。"}, "sentence_index": 0, "correct_answer": "植树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "园丁用枝条植树繁殖。", "explanation": "这里应该用〈扦插〉。扦插是把枝条插入土中繁殖，植树指栽种树苗，不用于枝条。"}, {"text": "这条河每天都在植树。", "explanation": "这里应该用〈流淌〉。植树是人栽种树木的动作，河流只能流淌，不能植树。"}, {"text": "这只猫每天都在窗台上植树。", "explanation": "这里应该用〈趴〉。植树是人栽种树苗的动作，猫只能趴在窗台上，不能植树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26472, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树（zhí shù）：把树苗种进土里让它长大，即本题目标词。"}, {"text": "职务", "is_correct": false, "explanation": "职务（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是工作中的职位和责任。"}, {"text": "执事", "is_correct": false, "explanation": "执事（zhí shì）第二个音节的韵母不同：shì 为 i 韵，shù 为 u 韵，意思是负责办事的人。"}, {"text": "志书", "is_correct": false, "explanation": "志书（zhì shū）两个音节的声调都不同：zhì 为第四声，zhí 为第二声；shū 为第一声，shù 为第四声，意思是地方志。"}], "explanations": {"植树": "植树（zhí shù）：把树苗种进土里让它长大，即本题目标词。", "职务": "职务（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是工作中的职位和责任。", "执事": "执事（zhí shì）第二个音节的韵母不同：shì 为 i 韵，shù 为 u 韵，意思是负责办事的人。", "志书": "志书（zhì shū）两个音节的声调都不同：zhì 为第四声，zhí 为第二声；shū 为第一声，shù 为第四声，意思是地方志。"}, "sentence_index": null, "correct_answer": "植树"}, "level_3": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树：栽树使地球变绿，与“让地球更绿”的目的相符。"}, {"text": "砍树", "is_correct": false, "explanation": "语义：砍树会使树木减少，与“让地球更绿”的目的相反。"}, {"text": "污染", "is_correct": false, "explanation": "语义：污染会使环境变差，与“让地球更绿”的目的相反。"}, {"text": "排放", "is_correct": false, "explanation": "配价：“排放”需要排放物作宾语，这里缺少宾语，句子不完整。"}], "explanations": {"植树": "植树：栽树使地球变绿，与“让地球更绿”的目的相符。", "砍树": "语义：砍树会使树木减少，与“让地球更绿”的目的相反。", "污染": "语义：污染会使环境变差，与“让地球更绿”的目的相反。", "排放": "配价：“排放”需要排放物作宾语，这里缺少宾语，句子不完整。"}, "sentence_index": 6, "correct_answer": "植树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班去超市植树。", "explanation": "植树需要土地和树苗，超市里不能植树，这里应该用〈购物〉。"}, {"text": "这位歌手昨天在舞台上植树。", "explanation": "这里应该用〈演唱〉。植树指栽种树木，歌手在舞台上应该说演唱，不能用植树。"}, {"text": "这篇作文每天都在植树。", "explanation": "这里应该用〈写〉。植树的施动者须是人，作文不能植树，应该说写作文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小时候他在山上过植树。", "corrected_sentence": "小时候他在山上植过树。", "error_description": "经历标记“过”应紧跟动词之后。错误形式把“过”放在“植树”之前，应为“植过树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在村后了植树。", "corrected_sentence": "他们在村后植了树。", "error_description": "完成标记“了”应紧跟动词“植”之后。错误形式把“了”放在“植树”之前，应为“植了树”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
